export function Modal({
  open,
  onClose,
  children,
  title,
  subtitle,
  className = '',
  hideClose = false,
  wide = false,
}: {
  open: boolean
  onClose: () => void
  children: ReactNode
  title?: string
  subtitle?: string
  className?: string
  hideClose?: boolean
  wide?: boolean
}) {
  const panelRef = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!open) return
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKey)
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    window.setTimeout(() => panelRef.current?.focus(), 50)
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = previousOverflow
    }
  }, [open, onClose])

  if (!open) return null
  return createPortal(
    <div className="modal-backdrop" onPointerDown={(event) => event.target === event.currentTarget && onClose()}>
      <div
        className={`modal-panel ${wide ? 'modal-wide' : ''} ${className}`}
        role="dialog"
        aria-modal="true"
        aria-label={title || '대화상자'}
        ref={panelRef}
        tabIndex={-1}
      >
        {(title || !hideClose) && (
          <div className="modal-head">
            <div>
              {title && <h2>{title}</h2>}
              {subtitle && <p>{subtitle}</p>}
            </div>
            {!hideClose && (
              <IconButton
                icon="close"
                label="닫기"
                onClick={() => {
                  sfx('click')
                  onClose()
                }}
              />
            )}
          </div>
        )}
        <div className="modal-body">{children}</div>
      </div>
    </div>,
    document.body,
  )
}

