            <>
              <div className="aed-side-title">
                <span className="eyebrow">CURRENT STEP</span>
                <h2>{phase === 'power' ? 'AED 전원 켜기' : phase === 'pads' ? '패드 부착하기' : phase === 'clear' ? '안전 확보' : phase === 'analyze' ? '리듬 분석' : phase === 'shock' ? '충격 전달' : phase === 'cpr' ? '가슴압박 재개' : '훈련 완료'}</h2>
