  --green: #3fbd83;
  --red: #e94c4c;
  --cream: #fff9ef;
  --paper: #fffdf8;
  --line: #ece2d3;
  --line-strong: #ddceb8;
  --sky: #bfeaf8;
  --shadow-sm: 0 4px 12px rgba(26, 54, 84, 0.08);
  --shadow: 0 14px 34px rgba(26, 54, 84, 0.12);
  --shadow-lg: 0 28px 60px rgba(20, 44, 72, 0.2);
  --radius-sm: 10px;
  --radius: 18px;
  --radius-lg: 26px;
  --text-scale: 1;
  --header-h: 72px;
  --display: 'Jua', 'Noto Sans KR', 'Apple SD Gothic Neo', sans-serif;
  --body: 'Noto Sans KR', 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  font-size: calc(16px * var(--text-scale));
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100%;
  font-family: var(--body);
  color: var(--ink);
  background:
    radial-gradient(1200px 600px at 8% -10%, #dff5ff 0%, transparent 55%),
    radial-gradient(900px 500px at 100% 0%, #fff2cf 0%, transparent 50%),
    #f6f1e7;
  line-height: 1.55;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  background-image: radial-gradient(rgba(27, 57, 88, 0.055) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: linear-gradient(to bottom, #000 0%, transparent 78%);
}

h1, h2, h3, h4, h5 {
  margin: 0;
  font-family: var(--display);
  font-weight: 400;
  letter-spacing: -0.015em;
  color: var(--navy);
  line-height: 1.2;
}

p {
  margin: 0;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

a {
  color: var(--blue);
}

ul, ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

svg {
  display: block;
}

::selection {
  background: #ffd76d;
  color: var(--navy);
}

:focus-visible {
  outline: 3px solid #2d8fe0;
  outline-offset: 3px;
  border-radius: 6px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ---------- app shell ---------- */
.app {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  position: relative;
  padding-bottom: env(safe-area-inset-bottom);
}

.app-main {
  flex: 1 0 auto;
  width: 100%;
}

.screen-pad {
  width: min(1300px, 100%);
  margin: 0 auto;
  padding: 30px clamp(16px, 4vw, 48px) 54px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--display);
  font-size: 0.72rem;
  letter-spacing: 0.13em;
  color: var(--primary);
  text-transform: uppercase;
}

.eyebrow svg {
  flex: 0 0 auto;
}

.icon {
  flex: 0 0 auto;
  vertical-align: -0.16em;
}

/* ---------- buttons ---------- */
.game-btn {
  --btn-bg: var(--primary);
  --btn-fg: #fff;
  --btn-shadow: 0 6px 0 var(--primary-dark);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 44px;
  padding: 0 21px;
  border: 0;
  border-radius: 14px;
  background: var(--btn-bg);
  color: var(--btn-fg);
  font-family: var(--display);
  font-size: 1rem;
  line-height: 1;
  letter-spacing: -0.01em;
  box-shadow: var(--btn-shadow), 0 9px 18px rgba(30, 52, 78, 0.14);
  transition: transform 0.14s ease, box-shadow 0.14s ease, filter 0.14s ease;
  position: relative;
  white-space: nowrap;
  user-select: none;
}

.game-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  filter: saturate(1.06) brightness(1.03);
  box-shadow: var(--btn-shadow), 0 14px 24px rgba(30, 52, 78, 0.18);
}

.game-btn:active:not(:disabled) {
  transform: translateY(3px);
  box-shadow: 0 2px 0 rgba(30, 52, 78, 0.3);
}

.game-btn:disabled {
  opacity: 0.52;
  filter: grayscale(0.4);
  box-shadow: none;
}

.game-btn svg {
  flex: 0 0 auto;
}

.btn-primary {
  --btn-bg: linear-gradient(180deg, #ff825c, #fa623a);
  --btn-shadow: 0 5px 0 #cf3f21;
}

.btn-secondary {
  --btn-bg: linear-gradient(180deg, #4179b6, #2c5f97);
  --btn-fg: #fff;
  --btn-shadow: 0 5px 0 #1d426a;
}

.btn-ghost {
  --btn-bg: #fff;
  --btn-fg: var(--navy);
  --btn-shadow: 0 4px 0 #d9cdbb;
  border: 1.5px solid #e1d5c3;
}

.btn-danger {
  --btn-bg: linear-gradient(180deg, #f66b6b, #e24141);
  --btn-fg: #fff;
  --btn-shadow: 0 5px 0 #b32b2b;
}

.btn-gold {
  --btn-bg: linear-gradient(180deg, #ffda6a, #ffc62f);
  --btn-fg: #6b4700;
  --btn-shadow: 0 5px 0 #d99c12;
}

.btn-soft {
  --btn-bg: #eef6f8;
  --btn-fg: #2b5f72;
  --btn-shadow: 0 4px 0 #cfdee2;
  border: 1.5px solid #d7e7eb;
}

.btn-white {
  --btn-bg: #fff;
  --btn-fg: var(--navy);
  --btn-shadow: 0 5px 0 #d7c9b5;
}

.btn-sm {
  min-height: 36px;
  padding: 0 15px;
  font-size: 0.86rem;
  border-radius: 11px;
}

.btn-md {
  min-height: 46px;
}

.btn-lg {
  min-height: 56px;
  padding: 0 30px;
  font-size: 1.14rem;
  border-radius: 16px;
}

.btn-full {
  width: 100%;
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border: 1.5px solid #e2d7c6;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.88);
  color: var(--navy);
  transition: 0.15s ease;
}

.icon-btn:hover,
.icon-btn.is-active {
  background: var(--primary-soft);
  border-color: #ffc0ad;
  color: var(--primary-dark);
  transform: translateY(-1px);
}

.link-button,
.modal-text-link,
.text-action {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  border: 0;
  background: none;
  color: var(--blue);
  font-size: 0.82rem;
  font-weight: 700;
  padding: 2px 0;
}

.link-button:hover,
.modal-text-link:hover {
  text-decoration: underline;
}

/* ---------- pills / progress ---------- */
.resource-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 34px;
  padding: 0 12px;
  border-radius: 999px;
  background: #fff9e8;
  border: 1.5px solid #f0e0b4;
  color: #77520a;
  font-size: 0.88rem;
  font-weight: 700;
  line-height: 1;
}

.resource-pill.compact {
  padding: 0 10px;
  height: 32px;
}

.resource-pill b {
  font-family: var(--display);
  font-weight: 400;
  font-size: 0.98rem;
}

.coin-icon {
  display: inline-grid;
  place-items: center;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: linear-gradient(180deg, #ffdf72, #f5b21d);
  border: 1.5px solid #d79a13;
  color: #7b4d00;
  font-size: 0.68rem;
  font-weight: 900;
  flex: 0 0 auto;
}

.xp-pill {
  background: #eaf3ff;
  border-color: #cadef4;
  color: #255d9a;
}

.mini-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 24px;
  padding: 0 9px;
  border-radius: 999px;
  background: #edf4fa;
  color: #3b678c;
  font-size: 0.7rem;
  font-weight: 700;
}

.progress-track {
  width: 100%;
  background: rgba(26, 53, 83, 0.1);
  border-radius: 999px;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.stars {
  display: inline-flex;
  gap: 1px;
  line-height: 0;
}

.star {
  color: #d9d1c4;
  fill: currentColor;
}

.star-filled {
  color: #ffc02e;
  fill: #ffc02e;
  filter: drop-shadow(0 1px 0 #d99c12);
}

.stars-animated .star-filled {
  animation: star-pop 0.5s cubic-bezier(0.2, 1.6, 0.4, 1) both;
}

.stars-animated .star-filled:nth-child(2) { animation-delay: 0.15s; }
.stars-animated .star-filled:nth-child(3) { animation-delay: 0.3s; }

.score-ring {
  position: relative;
  flex: 0 0 auto;
}

.score-ring svg {
  display: block;
}

.score-ring-text {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.score-ring-text strong {
  font-family: var(--display);
  font-size: 1.55rem;
  color: var(--navy);
  line-height: 1;
}

.score-ring-text span {
  font-size: 0.62rem;
  color: var(--muted);
  margin-top: 3px;
}

/* ---------- header ---------- */
.app-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 252, 245, 0.9);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid rgba(216, 201, 180, 0.62);
}

.app-header-inner {
  width: min(1400px, 100%);
  height: var(--header-h);
  margin: 0 auto;
  padding: 0 clamp(14px, 3vw, 34px);
  display: flex;
  align-items: center;
  gap: 18px;
}

.app-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 0;
  background: none;
  padding: 0;
  text-align: left;
  flex: 0 0 auto;
}

.app-brand-mark {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: linear-gradient(145deg, #ff7c54, #e8452d);
  color: #fff;
  display: grid;
  place-items: center;
  position: relative;
  box-shadow: 0 5px 12px rgba(217, 64, 34, 0.3);
  overflow: hidden;
}

.app-brand-mark span {
  position: absolute;
  font-size: 13px;
  top: 2px;
  left: 4px;
  opacity: 0.65;
}

.app-brand-mark b {
  font-family: var(--display);
  font-weight: 400;
  font-size: 1rem;
  letter-spacing: -0.04em;
  margin-top: 7px;
}

.app-brand-copy {
  display: flex;
  flex-direction: column;
  line-height: 1.08;
}

.app-brand-copy b {
  font-family: var(--display);
  font-weight: 400;
  color: var(--navy);
  font-size: 1.02rem;
  letter-spacing: 0.015em;
}

.app-brand-copy b i {
  font-style: normal;
  color: var(--primary);
}

.app-brand-copy small {
  font-size: 0.62rem;
  color: var(--muted);
  letter-spacing: 0.1em;
}

.app-nav {
  display: flex;
  align-items: center;
  gap: 2px;
  margin: 0 auto;
}

.app-nav button {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 42px;
  padding: 0 15px;
  border: 0;
  border-radius: 12px;
  background: none;
  color: #576d82;
  font-size: 0.88rem;
  font-weight: 700;
  position: relative;
  transition: 0.15s ease;
}

.app-nav button:hover {
  background: #fff5ea;
  color: var(--navy);
}

.app-nav button.is-active {
  background: var(--primary-soft);
  color: var(--primary-dark);
}

.app-nav button.is-active::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -15px;
  width: 22px;
  height: 3px;
  transform: translateX(-50%);
  border-radius: 3px;
  background: var(--primary);
}

.app-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.header-level {
  display: flex;
  align-items: center;
  gap: 7px;
  padding-right: 6px;
  border-right: 1px solid #e6dbca;
  margin-right: 2px;
}

.header-grade {
  font-size: 1.25rem;
  filter: drop-shadow(0 2px 2px rgba(0,0,0,.08));
}

.header-level > div {
  width: 76px;
}

.header-level b {
  display: block;
  font-family: var(--display);
  font-weight: 400;
  font-size: 0.8rem;
  color: var(--navy);
  margin-bottom: 4px;
}

.header-icon-btn {
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: #5d7387;
  display: grid;
  place-items: center;
  transition: 0.15s;
}

.header-icon-btn:hover,
.header-icon-btn.is-active {
  background: #fff1e7;
  color: var(--primary-dark);
}

.header-profile {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid #fff;
  background: linear-gradient(145deg, #e6f6ff, #c8ecff);
  display: grid;
  place-items: center;
  overflow: hidden;
  padding: 0;
  box-shadow: 0 2px 8px rgba(30, 60, 90, 0.16);
}

.header-profile svg {
  width: 34px;
  height: auto;
  margin-top: 4px;
}

.app-footer {
  width: min(1400px, 100%);
  margin: 0 auto;
  padding: 18px clamp(16px, 3vw, 34px) calc(20px + env(safe-area-inset-bottom));
  display: flex;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  border-top: 1px solid rgba(215, 200, 179, 0.6);
  color: #8898a7;
  font-size: 0.7rem;
}

.app-footer span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.footer-save i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 3px rgba(63, 189, 131, 0.16);
}

.mobile-nav {
  display: none;
}

/* ---------- loading ---------- */
.loading-screen {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: linear-gradient(180deg, #a8e4f7 0%, #e6f7fb 56%, #fdf4db 100%);
  overflow: hidden;
}

.loading-sky {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.loading-cloud {
  position: absolute;
  width: 170px;
  height: 54px;
  border-radius: 60px;
  background: rgba(255, 255, 255, 0.86);
  filter: blur(0.5px);
  animation: cloud-drift 12s ease-in-out infinite alternate;
}

.loading-cloud::before,
.loading-cloud::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  background: inherit;
}

.loading-cloud::before {
  width: 74px;
  height: 74px;
  left: 25px;
  top: -38px;
}

.loading-cloud::after {
  width: 54px;
  height: 54px;
  right: 24px;
  top: -26px;
}

.lc1 { top: 15%; left: 8%; }
.lc2 { top: 27%; right: 11%; transform: scale(0.8); animation-delay: -4s; }

.loading-sun {
  position: absolute;
  top: 10%;
  right: 18%;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  background: #fff3a8;
  box-shadow: 0 0 0 24px rgba(255, 246, 186, 0.35), 0 0 70px #ffe97a;
}

.loading-logo {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 30px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.9);
  box-shadow: 0 20px 50px rgba(34, 88, 118, 0.16);
  backdrop-filter: blur(6px);
}

.loading-mark {
  display: grid;
  place-items: center;
  width: 66px;
  height: 66px;
  border-radius: 20px;
  background: linear-gradient(145deg, #ff7b55, #d83b27);
  color: #fff;
  font-family: var(--display);
  font-size: 1.5rem;
  box-shadow: 0 7px 0 #a92b1c;
}

.loading-logo b {
  display: block;
  font-family: var(--display);
  font-weight: 400;
  color: var(--navy);
  font-size: 1.5rem;
  letter-spacing: 0.04em;
  line-height: 1.1;
}

.loading-logo span:not(.loading-mark) {
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 700;
}

.loading-road {
  position: relative;
  z-index: 2;
  width: min(420px, 74vw);
  height: 54px;
  border-radius: 27px;
  background: #8c9ba6;
  overflow: hidden;
  box-shadow: inset 0 4px 10px rgba(0, 0, 0, 0.16);
}

.loading-road-line {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 4px;
  background: repeating-linear-gradient(90deg, #f8edc9 0 18px, transparent 18px 34px);
  animation: road-scroll 0.7s linear infinite;
}

.loading-truck {
  position: absolute;
  top: 3px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 2rem;
  filter: drop-shadow(0 3px 2px rgba(0,0,0,.2));
  animation: truck-bounce 0.5s ease-in-out infinite alternate;
}

.loading-progress {
  position: relative;
  z-index: 2;
  width: min(340px, 68vw);
  height: 10px;
  border-radius: 999px;
  background: rgba(24, 52, 94, 0.13);
  overflow: hidden;
}

.loading-progress span {
  display: block;
  width: 40%;
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #ffce4a, #ff7b45);
  animation: loading-slide 1.2s ease-in-out infinite;
}

.loading-tip {
  position: relative;
  z-index: 2;
  color: var(--navy);
  font-family: var(--display);
  font-size: 1.04rem;
}

.loading-disclaimer {
  position: relative;
  z-index: 2;
  color: #617a88;
  font-size: 0.72rem;
}

/* ---------- title ---------- */
.title-screen {
  position: relative;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background:
    radial-gradient(860px 420px at 82% 78%, #ffe8a6 0%, transparent 62%),
    linear-gradient(180deg, #8ed8f4 0%, #c4ecf8 44%, #f7f0d7 72%, #fae6bb 100%);
}

.title-sky {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.title-sun {
  position: absolute;
  top: 8%;
  right: 13%;
  width: 92px;
  height: 92px;
  border-radius: 50%;
  background: #fff5a6;
  box-shadow: 0 0 0 26px rgba(255, 246, 183, 0.34), 0 0 80px rgba(255, 233, 122, 0.9);
  animation: sun-pulse 5s ease-in-out infinite;
}

.title-cloud {
  position: absolute;
  width: 190px;
  height: 58px;
  border-radius: 80px;
  background: rgba(255, 255, 255, 0.78);
  animation: cloud-drift 14s ease-in-out infinite alternate;
}

.title-cloud::before,
.title-cloud::after {
  content: '';
  position: absolute;
  background: inherit;
  border-radius: 50%;
}

.title-cloud::before {
  width: 84px;
  height: 84px;
  left: 30px;
  top: -42px;
}

.title-cloud::after {
  width: 62px;
  height: 62px;
  right: 27px;
  top: -29px;
}

.tc-one { top: 13%; left: 4%; }
.tc-two { top: 28%; left: 32%; transform: scale(0.62); opacity: 0.72; animation-delay: -5s; }
.tc-three { top: 20%; right: 2%; transform: scale(0.86); animation-delay: -9s; }

.title-birds {
  position: absolute;
  top: 21%;
  left: 57%;
  color: #567b90;
  font-size: 1.4rem;
  letter-spacing: 0.8em;
  opacity: 0.55;
}

.title-topbar {
  position: relative;
  z-index: 5;
  width: min(1280px, 100%);
  margin: 0 auto;
  padding: 22px clamp(18px, 4vw, 48px) 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.title-edu-badge {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 13px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.66);
  border: 1px solid rgba(255, 255, 255, 0.9);
  color: #2d5f7c;
  font-size: 0.74rem;
  font-weight: 700;
  backdrop-filter: blur(6px);
}

.title-settings {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 38px;
  padding: 0 15px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.9);
  background: rgba(255, 255, 255, 0.6);
  color: #315f79;
  font-size: 0.78rem;
  font-weight: 700;
  backdrop-filter: blur(6px);
}

.title-settings:hover {
  background: #fff;
}

.title-content {
  position: relative;
  z-index: 3;
  flex: 1;
  width: min(1280px, 100%);
  margin: 0 auto;
  padding: 30px clamp(18px, 4vw, 48px) 18px;
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 0.98fr);
  align-items: center;
  gap: clamp(12px, 3vw, 44px);
}

.title-copy {
  max-width: 590px;
  padding-bottom: 20px;
}

.title-kicker {
  display: inline-block;
  margin-bottom: 16px;
  padding: 6px 13px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.58);
  color: #295b78;
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.015em;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.8);
}

.logo-lockup {
  display: flex;
  align-items: center;
  gap: 16px;
}

.logo-mark {
  position: relative;
  width: 86px;
  height: 86px;
  flex: 0 0 auto;
  border-radius: 25px;
  background: linear-gradient(145deg, #ff845e, #e53d26);
  box-shadow: 0 8px 0 #b62e1d, 0 20px 34px rgba(187, 47, 27, 0.25);
  display: grid;
  place-items: center;
  transform: rotate(-3deg);
}

.logo-flame {
  position: absolute;
  top: 3px;
  right: 3px;
  font-size: 1.15rem;
  filter: saturate(0.9);
}

.logo-119 {
  font-family: var(--display);
  color: #fff;
  font-size: 2rem;
  letter-spacing: -0.05em;
  margin-top: 8px;
  text-shadow: 0 2px 0 rgba(120, 23, 10, 0.26);
}

.game-logo {
  display: flex;
  align-items: baseline;
  gap: 9px;
  line-height: 0.9;
  font-size: clamp(2.9rem, 6vw, 5.1rem);
  filter: drop-shadow(0 4px 0 rgba(255, 255, 255, 0.5));
}

.logo-safe { color: #1a3c63; }
.logo-city { color: #f05233; }
.logo-number {
  color: #f6b421;
  -webkit-text-stroke: 2px #b8740c;
  font-size: 0.74em;
  letter-spacing: -0.07em;
  transform: rotate(-4deg);
}

.game-logo-ko {
  margin-top: 7px;
  color: #31566f;
  font-family: var(--display);
  font-size: 1.28rem;
  letter-spacing: 0.09em;
}

.title-description {
  margin: 22px 0 26px;
  color: #395d72;
  font-size: clamp(0.94rem, 1.6vw, 1.05rem);
  font-weight: 500;
  line-height: 1.8;
}

.title-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: center;
}

.title-continue {
  animation: gentle-pulse 2.4s ease-in-out infinite;
}

.title-save-card {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(390px, 100%);
  margin-top: 20px;
  padding: 11px 15px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.58);
  border: 1px solid rgba(255, 255, 255, 0.86);
  backdrop-filter: blur(8px);
  box-shadow: 0 8px 20px rgba(52, 101, 118, 0.1);
}

.title-avatar {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #fff;
  font-size: 1.35rem;
  box-shadow: inset 0 0 0 2px rgba(255, 197, 74, 0.4);
}

.title-save-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.title-save-name {
  font-size: 0.84rem;
  font-weight: 700;
  color: #24475f;
}

.title-save-name b {
  color: var(--primary-dark);
  font-family: var(--display);
  font-weight: 400;
}

.title-save-meta {
  font-size: 0.67rem;
  color: #658091;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.title-save-info .progress-track {
  margin-top: 5px;
}

.title-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 24px;
}

.title-tags span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.42);
  color: #3e6377;
  font-size: 0.7rem;
  font-weight: 700;
}

.title-visual {
  position: relative;
  min-height: clamp(390px, 50vw, 560px);
  align-self: stretch;
}

.title-city-glow {
  position: absolute;
  left: 5%;
  right: 0;
  bottom: 4%;
  height: 52%;
  background: radial-gradient(ellipse at 55% 60%, rgba(255, 242, 177, 0.85), transparent 65%);
  filter: blur(10px);
}

.title-ground {
  position: absolute;
  left: -2%;
  right: -6%;
  bottom: 3%;
  height: 24%;
  border-radius: 50% 48% 0 0;
  background: linear-gradient(180deg, #a9d985, #67b363);
  box-shadow: 0 -4px 0 rgba(255, 255, 255, 0.26) inset;
}

.title-building {
  position: absolute;
  bottom: 12%;
  border-radius: 14px 14px 4px 4px;
  box-shadow: 0 20px 28px rgba(44, 91, 67, 0.2);
}

.title-firehouse {
  left: 6%;
  width: 32%;
  height: 40%;
  background: linear-gradient(145deg, #ff8a68, #e34b33);
  border: 4px solid #c93b28;
}

.title-school {
  right: 4%;
  width: 30%;
  height: 33%;
  background: linear-gradient(145deg, #ffeec2, #f2c983);
  border: 4px solid #d9ae6c;
}

.tb-roof {
  position: absolute;
  left: -7%;
  right: -7%;
  top: -8%;
  height: 13%;
  border-radius: 9px;
  background: #f3e3c5;
}

.title-firehouse .tb-window {
  position: absolute;
  left: 11%;
  right: 11%;
  top: 17%;
  height: 27%;
  border-radius: 7px;
  background: linear-gradient(145deg, #bfeefc, #6fc4e4);
  border: 4px solid #f8dfba;
}

.title-firehouse .tb-door {
  position: absolute;
  left: 33%;
  right: 33%;
  bottom: 0;
  height: 48%;
  display: grid;
  place-items: center;
  border-radius: 9px 9px 0 0;
  background: #933126;
  color: #ffd873;
  font-family: var(--display);
  font-size: 1.4rem;
}

.title-school .tb-roof {
  background: #e99351;
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
  top: -20%;
  height: 22%;
}

.title-school .tb-window {
  position: absolute;
  inset: 18% 12% 30%;
  border-radius: 6px;
  background:
    repeating-linear-gradient(90deg, #84cde1 0 28%, #fff3d9 28% 33%),
    #84cde1;
  border: 4px solid #fff3d9;
}

.title-school .tb-clock {
  position: absolute;
  top: 8%;
  left: 44%;
  width: 17px;
  height: 17px;
  border: 3px solid #fff;
  border-radius: 50%;
}

.title-character {
  position: absolute;
  z-index: 5;
  filter: drop-shadow(0 18px 16px rgba(33, 66, 51, 0.2));
}

.char-fire {
  left: 30%;
  bottom: 10%;
  animation: mascot-bob 3.4s ease-in-out infinite;
}

.char-safi {
  right: 7%;
  bottom: 7%;
  animation: mascot-bob 3.8s ease-in-out -0.8s infinite;
}

.char-medi {
  left: 4%;
  bottom: 6%;
  animation: mascot-bob 4.1s ease-in-out -1.6s infinite;
}

.title-bubble {
  position: absolute;
  z-index: 6;
  padding: 8px 14px;
  border-radius: 14px;
  background: #fff;
  color: #315a74;
  font-family: var(--display);
  font-size: 0.88rem;
  box-shadow: 0 6px 16px rgba(30, 66, 84, 0.14);
}

.title-bubble::after {
  content: '';
  position: absolute;
  bottom: -7px;
  left: 22px;
  width: 14px;
  height: 14px;
  background: #fff;
  transform: rotate(45deg);
  border-radius: 2px;
}

.bubble-fire { left: 43%; top: 7%; animation: bubble-float 4s ease-in-out infinite; }
.bubble-safi { right: 2%; top: 27%; animation: bubble-float 4.6s ease-in-out -1s infinite; }

.title-spark {
  position: absolute;
  color: #fff5b1;
  font-size: 1.5rem;
  text-shadow: 0 0 12px #fff5b1;
  animation: twinkle 2.8s ease-in-out infinite;
}

.spark-a { left: 15%; top: 18%; }
.spark-b { right: 28%; top: 6%; animation-delay: -1s; }
.spark-c { right: 2%; bottom: 38%; animation-delay: -2s; }

.title-footer {
  position: relative;
  z-index: 4;
  width: min(1280px, 100%);
  margin: 0 auto;
  padding: 14px clamp(18px, 4vw, 48px) calc(18px + env(safe-area-inset-bottom));
  display: flex;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  color: #547284;
  font-size: 0.67rem;
}

.title-footer-note {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

/* ---------- modal / toast / confetti ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(13, 31, 53, 0.46);
  backdrop-filter: blur(5px);
  animation: fade-in 0.18s ease both;
}

.modal-panel {
  width: min(600px, 100%);
  max-height: min(90svh, 920px);
  display: flex;
  flex-direction: column;
  border-radius: 24px;
  background: var(--paper);
  box-shadow: var(--shadow-lg), inset 0 0 0 1px rgba(255, 255, 255, 0.7);
  overflow: hidden;
  animation: modal-pop 0.24s cubic-bezier(0.2, 1.3, 0.5, 1) both;
}

.modal-wide {
  width: min(900px, 100%);
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 20px 24px 15px;
  border-bottom: 1px solid #f0e7d9;
  flex: 0 0 auto;
}

.modal-head h2 {
  font-size: 1.42rem;
}

.modal-head p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.78rem;
}

.modal-body {
  padding: 22px 24px 24px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 22px;
}

.field-label {
  display: block;
  margin-bottom: 7px;
  color: #4a6478;
  font-size: 0.78rem;
  font-weight: 700;
}

.text-input {
  width: 100%;
  height: 48px;
  padding: 0 15px;
  border: 1.5px solid #ded2c0;
  border-radius: 12px;
  background: #fff;
  color: var(--ink);
  font-size: 1rem;
  transition: 0.15s;
}

.text-input:focus {
  border-color: #81bde9;
  box-shadow: 0 0 0 4px rgba(58, 153, 223, 0.13);
  outline: none;
}

.text-input.compact {
  height: 40px;
  max-width: 190px;
}

.new-game-note {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin-top: 14px;
  padding: 11px 13px;
  border-radius: 10px;
  background: #eef8fb;
  color: #487080;
  font-size: 0.76rem;
}

.new-game-note svg {
  margin-top: 1px;
  color: #3a99df;
}

.danger-note {
  margin-top: 10px;
  color: #c34436;
  font-size: 0.78rem;
  font-weight: 700;
}

.danger-panel {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 14px 15px;
  border-radius: 12px;
  background: #fff1ee;
  border: 1px solid #ffd5cc;
  color: #97422f;
  font-size: 0.82rem;
}

.danger-panel svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.toast-host {
  position: fixed;
  z-index: 300;
  right: max(16px, env(safe-area-inset-right));
  bottom: max(20px, calc(18px + env(safe-area-inset-bottom)));
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
  max-width: min(360px, calc(100vw - 32px));
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 15px;
  border-radius: 13px;
  background: #fff;
  color: var(--navy);
  font-size: 0.81rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(18, 43, 71, 0.22);
  border: 1px solid #eee4d5;
  animation: toast-in 0.25s cubic-bezier(0.2, 1.2, 0.4, 1) both;
}

.toast-icon {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #dff7ea;
  color: #138755;
  font-size: 0.75rem;
  font-weight: 900;
}

.toast-error .toast-icon { background: #ffe4e1; color: #c0392b; }
.toast-info .toast-icon { background: #e3f1ff; color: #246fae; }

.confetti-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 3;
}

.confetti-piece {
  position: absolute;
  top: -18px;
  left: var(--x);
  width: 9px;
  height: 15px;
  border-radius: 2px;
  background: var(--color);
  opacity: 0;
  animation: confetti-fall var(--duration) linear var(--delay) infinite;
}

/* ---------- city ---------- */
.city-screen {
  width: min(1380px, 100%);
  margin: 0 auto;
  padding: 24px clamp(14px, 3vw, 40px) 40px;
}

.city-topline {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 16px;
}

.city-title-block h1 {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: clamp(1.7rem, 3vw, 2.25rem);
}

.city-title-level {
  display: inline-grid;
  place-items: center;
  height: 26px;
  padding: 0 10px;
  border-radius: 8px;
  background: var(--navy);
  color: #fff;
  font-family: var(--display);
  font-weight: 400;
  font-size: 0.76rem;
  letter-spacing: 0;
}

.city-title-block p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.83rem;
}

.city-title-block p b {
  color: var(--navy);
}

.city-quick-stats {
  display: flex;
  gap: 8px;
  flex: 0 0 auto;
}

.quick-stat {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 104px;
  padding: 9px 13px;
  border-radius: 14px;
  background: rgba(255, 253, 248, 0.86);
  border: 1px solid #eee5d6;
  box-shadow: var(--shadow-sm);
}

.quick-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 10px;
}

.coin-bg { background: #fff2c9; color: #a2740c; }
.flame-bg { background: #ffe6dd; color: #d64d2e; }
.streak-bg { background: #e5f7f1; color: #168c72; }

.quick-stat div {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}

.quick-stat b {
  font-family: var(--display);
  font-weight: 400;
  color: var(--navy);
  font-size: 1rem;
}

.quick-stat span:not(.quick-icon) {
  font-size: 0.63rem;
  color: var(--muted);
}

.city-main {
  position: relative;
}

.city-overlay-card {
  position: absolute;
  z-index: 20;
  border-radius: 16px;
  background: rgba(255, 253, 247, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.94);
  box-shadow: 0 10px 24px rgba(29, 60, 83, 0.16);
  backdrop-filter: blur(9px);
}

.city-greeting-card {
  top: 16px;
  left: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px 9px 9px;
  min-width: 228px;
}

.greeting-mascot {
  width: 54px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.greeting-mascot svg {
  width: 52px;
  height: auto;
}

.city-greeting-card > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.overlay-label {
  display: block;
  color: #8399a8;
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.city-greeting-card b {
  font-family: var(--display);
  font-weight: 400;
  color: var(--navy);
  font-size: 0.92rem;
}

.mini-xp {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 3px;
}

.mini-xp .progress-track {
  width: 90px;
}

.mini-xp span {
  font-size: 0.55rem;
  color: var(--muted);
  white-space: nowrap;
}

.safety-index-card {
  top: 16px;
  right: 16px;
  width: 158px;
  padding: 10px 13px 11px;
  text-align: center;
}

.safety-gauge {
  position: relative;
  margin: 0 auto;
  width: 126px;
  height: 70px;
}

.safety-gauge svg {
  width: 100%;
  height: auto;
}

.safety-gauge strong {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  font-family: var(--display);
  font-weight: 400;
  color: var(--navy);
  font-size: 1.6rem;
  line-height: 1;
}

.safety-gauge span {
  position: absolute;
  right: 12px;
  bottom: 1px;
  color: var(--muted);
  font-size: 0.58rem;
}

.safety-status {
  font-size: 0.65rem;
  font-weight: 700;
  color: #3f8a77;
  margin: 2px 0 3px;
}

.safety-index-card .link-button {
  font-size: 0.62rem;
}

.city-scroll {
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 22px 44px rgba(32, 67, 84, 0.18), 0 0 0 1px rgba(255, 255, 255, 0.55) inset;
  background: #c5ecf6;
}

.city-stage {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  isolation: isolate;
}

.city-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.city-sun {
  position: absolute;
  top: 9%;
  right: 10%;
  width: 7%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: #fff6bc;
  box-shadow: 0 0 0 16px rgba(255, 248, 200, 0.28), 0 0 60px rgba(255, 235, 120, 0.8);
}

.city-cloud {
  position: absolute;
  width: 10%;
  height: 3.2%;
  border-radius: 50px;
  background: rgba(255, 255, 255, 0.82);
  filter: blur(0.4px);
  animation: cloud-drift 18s ease-in-out infinite alternate;
}

.city-cloud::before,
.city-cloud::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  background: inherit;
}

.city-cloud::before {
  width: 58%;
  aspect-ratio: 1;
  left: 18%;
  bottom: 24%;
}

.city-cloud::after {
  width: 44%;
  aspect-ratio: 1;
  right: 16%;
  bottom: 18%;
}

.cloud-one { top: 12%; left: 8%; }
.cloud-two { top: 20%; left: 42%; transform: scale(0.72); animation-delay: -6s; }
.cloud-three { top: 7%; right: 22%; transform: scale(0.9); animation-delay: -11s; }

.city-road-cars {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.toy-car {
  position: absolute;
  width: 4.4%;
  height: 2.4%;
  border-radius: 40% 40% 25% 25%;
  background: #4d92dd;
  box-shadow: 0 3px 5px rgba(30, 45, 60, 0.22);
  animation: car-drive 16s linear infinite;
}

.toy-car span {
  position: absolute;
  width: 52%;
  height: 62%;
  left: 24%;
  top: -48%;
  border-radius: 50% 50% 20% 20%;
  background: #a9dcf1;
}

.toy-car i {
  position: absolute;
  width: 22%;
  aspect-ratio: 1;
  bottom: -25%;
  right: 14%;
  border-radius: 50%;
  background: #28394a;
  box-shadow: -70% 0 0 #28394a;
}

.car-one { left: -6%; top: 87%; animation-duration: 19s; }
.car-two { left: 38%; top: 82%; background: #f1b643; animation-duration: 15s; animation-delay: -4s; transform: scale(1.2); }
.car-three { right: -6%; top: 92%; background: #5fc4a8; animation-duration: 23s; animation-delay: -9s; transform: scale(0.9); }

.city-citizens {
  position: absolute;
  inset: 0;
  pointer-events: none;
  font-size: clamp(12px, 1.5vw, 22px);
}

.citizen {
  position: absolute;
  filter: drop-shadow(0 3px 2px rgba(40, 70, 50, 0.18));
  animation: citizen-bob 2.8s ease-in-out infinite;
}

.citizen-a { left: 27%; top: 73%; }
.citizen-b { left: 44%; top: 79%; animation-delay: -0.7s; }
.citizen-c { left: 62%; top: 68%; animation-delay: -1.4s; }
.citizen-d { left: 13%; top: 80%; animation-delay: -2s; }

.city-building,
.city-plot {
  position: absolute;
  display: block;
  padding: 0;
  border: 0;
  background: none;
  transform-origin: bottom center;
  transition: filter 0.2s ease, transform 0.2s ease;
  text-align: left;
}

.city-building:hover,
.city-building:focus-visible,
.city-plot:hover,
