  --primary: #ff6b45;
  --primary-dark: #e94928;
  --primary-soft: #fff0ea;
  --gold: #ffce4a;
  --gold-dark: #e9a91f;
  --gold-soft: #fff8dd;
  --teal: #2cc0a7;
  --teal-dark: #189c88;
  --blue: #3a99df;
  --blue-soft: #eaf5ff;
  --pink: #ef5b7b;
  --green: #3fbd83;
  --red: #e94c4c;
  --cream: #fff9ef;
  --paper: #fffdf8;
  --line: #ece2d3;
  --line-strong: #ddceb8;
  --sky: #bfeaf8;
  --shadow-sm: 0 4px 12px rgba(26, 54, 84, 0.08);
  --shadow: 0 14px 34px rgba(26, 54, 84, 0.12);
  --shadow-lg: 0 28px 60px rgba(20, 44, 72, 0.2);
  --radius-sm: 10px;
  --radius: 18px;
  --radius-lg: 26px;
  --text-scale: 1;
  --header-h: 72px;
  --display: 'Jua', 'Noto Sans KR', 'Apple SD Gothic Neo', sans-serif;
  --body: 'Noto Sans KR', 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
}

* {
  box-sizing: border-box;
}

html {
  font-size: calc(16px * var(--text-scale));
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100%;
  font-family: var(--body);
  color: var(--ink);
  background:
    radial-gradient(1200px 600px at 8% -10%, #dff5ff 0%, transparent 55%),
    radial-gradient(900px 500px at 100% 0%, #fff2cf 0%, transparent 50%),
    #f6f1e7;
  line-height: 1.55;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
  background-image: radial-gradient(rgba(27, 57, 88, 0.055) 1px, transparent 1px);
  background-size: 22px 22px;
  mask-image: linear-gradient(to bottom, #000 0%, transparent 78%);
}

h1, h2, h3, h4, h5 {
  margin: 0;
  font-family: var(--display);
  font-weight: 400;
  letter-spacing: -0.015em;
  color: var(--navy);
  line-height: 1.2;
}

p {
  margin: 0;
}

button, input, select, textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

a {
  color: var(--blue);
}

ul, ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

svg {
  display: block;
}

::selection {
  background: #ffd76d;
  color: var(--navy);
}

:focus-visible {
  outline: 3px solid #2d8fe0;
  outline-offset: 3px;
  border-radius: 6px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ---------- app shell ---------- */
.app {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  position: relative;
  padding-bottom: env(safe-area-inset-bottom);
}

.app-main {
  flex: 1 0 auto;
  width: 100%;
}

.screen-pad {
  width: min(1300px, 100%);
  margin: 0 auto;
  padding: 30px clamp(16px, 4vw, 48px) 54px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-family: var(--display);
  font-size: 0.72rem;
  letter-spacing: 0.13em;
  color: var(--primary);
  text-transform: uppercase;
}

.eyebrow svg {
  flex: 0 0 auto;
}

.icon {
  flex: 0 0 auto;
  vertical-align: -0.16em;
}

/* ---------- modal / toast / confetti ---------- */
.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(13, 31, 53, 0.46);
  backdrop-filter: blur(5px);
  animation: fade-in 0.18s ease both;
}

.modal-panel {
  width: min(600px, 100%);
  max-height: min(90svh, 920px);
  display: flex;
  flex-direction: column;
  border-radius: 24px;
  background: var(--paper);
  box-shadow: var(--shadow-lg), inset 0 0 0 1px rgba(255, 255, 255, 0.7);
  overflow: hidden;
  animation: modal-pop 0.24s cubic-bezier(0.2, 1.3, 0.5, 1) both;
}

.modal-wide {
  width: min(900px, 100%);
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 20px 24px 15px;
  border-bottom: 1px solid #f0e7d9;
  flex: 0 0 auto;
}

.modal-head h2 {
  font-size: 1.42rem;
}

.modal-head p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.78rem;
}

.modal-body {
  padding: 22px 24px 24px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.modal-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 22px;
}

.field-label {
  display: block;
  margin-bottom: 7px;
  color: #4a6478;
  font-size: 0.78rem;
  font-weight: 700;
}

.text-input {
  width: 100%;
  height: 48px;
  padding: 0 15px;
  border: 1.5px solid #ded2c0;
  border-radius: 12px;
  background: #fff;
  color: var(--ink);
  font-size: 1rem;
  transition: 0.15s;
}

.text-input:focus {
  border-color: #81bde9;
  box-shadow: 0 0 0 4px rgba(58, 153, 223, 0.13);
  outline: none;
}

.text-input.compact {
  height: 40px;
  max-width: 190px;
}

.new-game-note {
  display: flex;
  gap: 8px;
  align-items: flex-start;
  margin-top: 14px;
  padding: 11px 13px;
  border-radius: 10px;
  background: #eef8fb;
  color: #487080;
  font-size: 0.76rem;
}

.new-game-note svg {
  margin-top: 1px;
  color: #3a99df;
}

.danger-note {
  margin-top: 10px;
  color: #c34436;
  font-size: 0.78rem;
  font-weight: 700;
}

.danger-panel {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 14px 15px;
  border-radius: 12px;
  background: #fff1ee;
  border: 1px solid #ffd5cc;
  color: #97422f;
  font-size: 0.82rem;
}

.danger-panel svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.toast-host {
  position: fixed;
  z-index: 300;
  right: max(16px, env(safe-area-inset-right));
  bottom: max(20px, calc(18px + env(safe-area-inset-bottom)));
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: none;
  max-width: min(360px, calc(100vw - 32px));
}

.toast {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 15px;
  border-radius: 13px;
  background: #fff;
  color: var(--navy);
  font-size: 0.81rem;
  font-weight: 600;
  box-shadow: 0 12px 30px rgba(18, 43, 71, 0.22);
  border: 1px solid #eee4d5;
  animation: toast-in 0.25s cubic-bezier(0.2, 1.2, 0.4, 1) both;
}

.toast-icon {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #dff7ea;
  color: #138755;
  font-size: 0.75rem;
  font-weight: 900;
}

.toast-error .toast-icon { background: #ffe4e1; color: #c0392b; }
.toast-info .toast-icon { background: #e3f1ff; color: #246fae; }

.confetti-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 3;
}

.confetti-piece {
  position: absolute;
  top: -18px;
  left: var(--x);
  width: 9px;
  height: 15px;
  border-radius: 2px;
  background: var(--color);
  opacity: 0;
  animation: confetti-fall var(--duration) linear var(--delay) infinite;
}

