input.oldString:
.knowledge-source b.verified {
  color: #188d70;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

input.newString:
.knowledge-source b.verified {
  color: #188d70;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

/* ============================================================
   HEADER FIXES
   ============================================================ */
.app-brand-copy b,
.app-brand-copy small,
.app-nav button,
.header-level b {
  white-space: nowrap;
}

.app-nav {
  flex: 0 1 auto;
  min-width: 0;
}

.app-nav button {
  flex: 0 0 auto;
  white-space: nowrap;
}

/* ============================================================
   PROFILE
   ============================================================ */
.profile-screen {
  padding-top: 30px;
}

.profile-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  gap: 18px;
  align-items: start;
}

.profile-hero-card,
.coach-card,
.skill-card,
.badge-collection,
.stats-card,
.profile-mission-history,
.settings-card {
  position: relative;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 22px;
  box-shadow: var(--shadow-sm);
}

.profile-hero-card {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 26px;
  min-height: 230px;
  padding: 28px 34px;
  overflow: hidden;
  background:
    radial-gradient(500px 260px at 92% -10%, rgba(255, 221, 128, 0.45), transparent 65%),
    radial-gradient(420px 300px at 4% 120%, rgba(87, 199, 255, 0.22), transparent 60%),
    linear-gradient(120deg, #fffdf8 20%, #f7fffb 70%, #eefaff);
}

.profile-card-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.profile-bg-circle {
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(44, 192, 167, 0.16);
}

.profile-bg-circle.c1 {
  width: 360px;
  height: 360px;
  right: -80px;
  top: -180px;
  background: rgba(255, 206, 74, 0.08);
}

.profile-bg-circle.c2 {
  width: 240px;
  height: 240px;
  left: -110px;
  bottom: -130px;
  background: rgba(58, 153, 223, 0.07);
}

.profile-bg-star {
  position: absolute;
  color: #f4c84c;
  font-size: 1.3rem;
  opacity: 0.65;
}

.profile-bg-star.s1 { right: 26%; top: 20%; }
.profile-bg-star.s2 { right: 7%; bottom: 18%; font-size: 0.85rem; }

.profile-avatar-wrap {
  position: relative;
  width: 154px;
  height: 154px;
  flex: 0 0 auto;
}

.profile-avatar-ring {
  width: 154px;
  height: 154px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(145deg, #e9f8ff, #fff6dc);
  border: 5px solid #fff;
  box-shadow: 0 12px 28px rgba(28, 70, 105, 0.15), inset 0 0 0 1px #e5efe9;
  overflow: hidden;
}

.profile-avatar-ring svg {
  width: 132px;
  height: auto;
  margin-top: 9px;
}

.profile-grade-badge {
  position: absolute;
  right: -2px;
  bottom: 4px;
  width: 45px;
  height: 45px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  border: 3px solid #fff;
  box-shadow: 0 5px 14px rgba(30, 60, 90, 0.2);
  font-size: 1.5rem;
}

.profile-identity {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.profile-grade-name {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 11px;
  border-radius: 999px;
  background: #e6f8f2;
  color: #167f6b;
  font-size: 0.68rem;
  font-weight: 800;
}

.profile-identity h2 {
  margin: 8px 0 2px;
  font-size: clamp(1.8rem, 3.3vw, 2.5rem);
}

.profile-identity h2 small {
  display: inline-flex;
  align-items: center;
  margin-left: 7px;
  padding: 3px 9px;
  border-radius: 8px;
  background: var(--navy);
  color: #fff;
  font-family: var(--body);
  font-size: 0.66rem;
  vertical-align: middle;
}

.profile-identity > p {
  color: var(--muted);
  font-size: 0.78rem;
}

.profile-xp {
  width: min(420px, 100%);
  margin-top: 16px;
}

.profile-xp-labels {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
  color: #68808f;
  font-size: 0.66rem;
}

.profile-xp-labels b {
  color: var(--navy);
}

.profile-mini-badges {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 13px;
}

.mini-badge {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #f1f0ea;
  font-size: 1rem;
  filter: grayscale(1);
  opacity: 0.5;
}

.mini-badge.earned {
  background: #fff7dc;
  box-shadow: inset 0 0 0 1px #f3e1a9;
  filter: none;
  opacity: 1;
}

.profile-quick-stats {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 142px;
}

.profile-quick-stats > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 15px;
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(218, 232, 226, 0.9);
  backdrop-filter: blur(4px);
}

.profile-quick-stats b {
  font-family: var(--display);
  color: var(--navy);
  font-size: 1.35rem;
  font-weight: 400;
  line-height: 1;
}

.profile-quick-stats span {
  color: var(--muted);
  font-size: 0.66rem;
  font-weight: 700;
  white-space: nowrap;
}

.coach-card {
  padding: 22px 24px;
  background:
    radial-gradient(330px 180px at 100% 0%, rgba(77, 186, 226, 0.17), transparent 64%),
    linear-gradient(150deg, #183c65 0%, #1d527d 58%, #1c687e 100%);
  border-color: #153a5f;
  color: #effbff;
  overflow: hidden;
}

.coach-card .eyebrow { color: #82e3d2; }
.coach-card h3 { color: #fff; }

.coach-head {
  display: flex;
  align-items: center;
  gap: 11px;
  position: relative;
}

.coach-avatar {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.13);
  border: 1px solid rgba(255, 255, 255, 0.18);
  font-size: 1.5rem;
}

.coach-head h3 { font-size: 1.15rem; margin-top: 2px; }

.coach-online {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border-radius: 999px;
