.coach-note {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 12px;
  color: #9dc5d2;
  font-size: 0.62rem;
  line-height: 1.5;
}

.coach-note svg { flex: 0 0 auto; margin-top: 1px; }

.skill-card {
  padding: 22px 24px;
}

.skill-card-head,
.badge-head,
.stats-head,
.history-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 15px;
}

.skill-card-head h3,
.badge-head h3,
.stats-head h3,
.history-head h3 {
  font-size: 1.18rem;
  margin-top: 2px;
}

.badge-head h3 small {
  color: var(--muted-2);
  font-family: var(--body);
  font-size: 0.64rem;
  font-weight: 700;
}

.skill-sample,
.badge-sub {
  color: #91a1ad;
  font-size: 0.62rem;
  white-space: nowrap;
}

.skill-chart-wrap {
  display: flex;
  align-items: center;
  gap: 14px;
}

.radar-chart {
  width: min(220px, 42%);
  height: auto;
  flex: 0 0 auto;
}

.skill-bars {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.skill-bar-row {
  display: grid;
  grid-template-columns: minmax(90px, 1.2fr) minmax(50px, 1fr) 26px;
  align-items: center;
  gap: 8px;
}

.skill-label {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #50697b;
  font-size: 0.68rem;
  font-weight: 700;
  white-space: nowrap;
}

.skill-label i {
  font-style: normal;
  font-size: 0.78rem;
}

.skill-bar-track {
  height: 7px;
