}

.skill-bar-row > b {
  color: var(--navy);
  font-family: var(--display);
  font-size: 0.8rem;
  font-weight: 400;
  text-align: right;
}

.badge-collection { padding: 22px 24px; }

.badge-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.badge-item {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 10px;
  border-radius: 12px;
  border: 1px solid #eef0e9;
  background: #fffefa;
}

.badge-item.locked { opacity: 0.62; }

.badge-medal {
  position: relative;
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 13px;
  font-size: 1.35rem;
}

.badge-lock {
  position: absolute;
  right: -4px;
  bottom: -4px;
  width: 19px;
  height: 19px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  color: #9aa8ae;
  box-shadow: 0 2px 6px rgba(20, 45, 70, 0.15);
}

.badge-info { min-width: 0; }
.badge-info b { display: block; color: var(--navy); font-size: 0.76rem; }
.badge-info p { color: #7d8f9b; font-size: 0.65rem; line-height: 1.45; }
.badge-info span { color: #a2aeb5; font-size: 0.59rem; }

.stats-card { padding: 22px 24px; }

.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stats-grid > div {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  padding: 11px 6px;
  border-radius: 11px;
  background: #faf8f1;
  border: 1px solid #f0ece1;
}

.stats-grid span { color: #8395a0; font-size: 0.58rem; }
.stats-grid b { color: var(--navy); font-family: var(--display); font-size: 1.25rem; font-weight: 400; }
.stats-grid small { color: #a6b1b6; font-size: 0.56rem; }

.stats-tip {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 11px;
  color: #758b98;
  font-size: 0.63rem;
  line-height: 1.5;
}

.stats-tip svg { flex: 0 0 auto; color: var(--blue); margin-top: 1px; }

.profile-mission-history {
  grid-column: 1 / -1;
  padding: 20px 24px;
}

.history-head { margin-bottom: 10px; }

.profile-history-rows {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 7px;
}

.profile-history-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 11px;
  border-radius: 11px;
  background: #fbfaf5;
  border: 1px solid #f0ece2;
}

.phr-icon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #fff2dc;
  font-size: 1rem;
}

.profile-history-row > div {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
}

.profile-history-row > div b {
  color: var(--navy);
  font-size: 0.71rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.profile-history-row > div span { color: #9aa8b0; font-size: 0.57rem; }
.phr-score { color: var(--teal-dark); font-size: 0.8rem; }

/* ============================================================
   SETTINGS
   ============================================================ */
.settings-screen { padding-top: 30px; }

.settings-layout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  align-items: start;
}

.settings-card {
  padding: 22px 24px;
}

.mode-settings { grid-column: 1 / -1; }

.settings-card-head {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 16px;
}

.settings-head-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: #fff4df;
  font-size: 1.15rem;
}

.settings-card-head h2 { font-size: 1.12rem; margin-top: 1px; }
.settings-card-head p { color: var(--muted); font-size: 0.68rem; margin-top: 2px; }

.mode-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 9px;
}

.mode-option {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 12px;
  border-radius: 13px;
  border: 1.5px solid #e9e2d5;
  background: #fffefa;
  text-align: left;
  transition: 0.15s ease;
  position: relative;
}

.mode-option:hover {
  border-color: #cfe3d9;
  background: #fbfffd;
}

.mode-option.is-active {
  border-color: var(--teal);
  background: #f0fdf9;
  box-shadow: 0 0 0 3px rgba(44, 192, 167, 0.11);
}

.mode-emoji { font-size: 1.35rem; line-height: 1.2; flex: 0 0 auto; }

.mode-copy { min-width: 0; }
.mode-copy b { display: block; color: var(--navy); font-size: 0.8rem; }
.mode-copy p { color: #7a8e9a; font-size: 0.63rem; line-height: 1.5; margin: 2px 0 6px; }
.mode-tags { display: flex; flex-wrap: wrap; gap: 3px; }
.mode-tags i { padding: 2px 6px; border-radius: 5px; background: #f0f1e9; color: #87968f; font-size: 0.53rem; font-style: normal; font-weight: 700; }
.mode-option.is-active .mode-tags i { background: #d9f4ed; color: #168c76; }

.mode-radio {
  position: absolute;
  right: 9px;
  top: 9px;
  width: 18px;
  height: 18px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1.5px solid #d9ded7;
  color: #fff;
}

.mode-option.is-active .mode-radio {
  border-color: var(--teal);
  background: var(--teal);
}

.setting-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 54px;
  padding: 10px 0;
  border-bottom: 1px solid #f3eee4;
}

.setting-row:last-of-type { border-bottom: 0; }

.setting-row > div:first-child {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.setting-row b { color: #334e63; font-size: 0.76rem; }
.setting-row span { color: #91a0a9; font-size: 0.62rem; }

.toggle {
  width: 46px;
  height: 26px;
  flex: 0 0 auto;
  border: 0;
  border-radius: 999px;
  background: #dce3df;
  padding: 3px;
  transition: background 0.18s;
}

.toggle span {
  display: block;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 2px 5px rgba(20, 50, 70, 0.18);
  transition: transform 0.18s;
}

.toggle.on { background: var(--teal); }
.toggle.on span { transform: translateX(20px); }

.audio-note {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 11px;
  color: #8798a2;
  font-size: 0.62rem;
}

.text-size-row { align-items: flex-start; }

.text-size-options {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.text-size-options button {
  padding: 6px 9px;
  border-radius: 8px;
  border: 1px solid #e4ddd1;
  background: #fffefa;
  color: #6f828e;
  font-size: 0.61rem;
  font-weight: 700;
}

.text-size-options button.is-active {
  border-color: var(--navy);
  background: var(--navy);
  color: #fff;
}

.status-chip {
  flex: 0 0 auto;
  padding: 5px 9px;
  border-radius: 999px;
  background: #f1f2ec;
  color: #8d9b9b;
  font-size: 0.58rem !important;
  font-weight: 700;
}

.status-chip.on { background: #e3f8f1; color: #168d73; }

.name-edit-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 12px;
}

.name-edit-row label {
  color: #5d7281;
  font-size: 0.72rem;
  font-weight: 700;
}

.save-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 11px;
  border-radius: 11px;
  background: #faf8f1;
  border: 1px solid #f1ece1;
}

.save-info-grid > div { display: flex; flex-direction: column; }
.save-info-grid span { color: #9ba8ae; font-size: 0.57rem; }
.save-info-grid b { color: #547081; font-size: 0.67rem; }

.data-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 13px;
}

.about-copy p {
  color: #61798a;
  font-size: 0.7rem;
  line-height: 1.7;
  margin-bottom: 7px;
}

.about-warning {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 9px 10px;
  border-radius: 9px;
  background: #fff7e7 !important;
  color: #7c682c !important;
}

.about-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 9px;
}

.about-meta span {
  padding: 3px 8px;
  border-radius: 5px;
  background: #f2f2eb;
  color: #8a978f;
  font-size: 0.56rem;
  font-weight: 700;
}

.inline-back-row {
  max-width: 1300px;
  margin: 14px auto 0;
  padding: 0 clamp(16px, 4vw, 48px);
}

.inline-back-row button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 7px 10px;
  border: 0;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.7);
  color: #5e7889;
  font-size: 0.7rem;
  font-weight: 700;
}

/* ============================================================
   MISSION BRIEF MODAL
   ============================================================ */
.mission-brief-modal {
  width: min(980px, 100%);
}

.mission-brief-modal .modal-head {
  padding: 17px 26px 13px;
}

.mission-brief-modal .modal-head h2 { font-size: 1.18rem; }

.mission-brief-modal .modal-body {
  padding: 0 26px 22px;
}

.brief-hero {
  position: relative;
  display: flex;
  align-items: center;
