}

.brief-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(95deg, rgba(20, 35, 55, 0.25), transparent 58%);
  z-index: 0;
}

.brief-hero-art {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
}

.brief-emoji {
  position: absolute;
  right: 158px;
  top: 50%;
  transform: translateY(-52%) rotate(-7deg);
  font-size: 6.8rem;
  opacity: 0.2;
  filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.12));
}

.brief-sun {
  position: absolute;
  width: 120px;
  height: 120px;
  right: 205px;
  top: -42px;
  border-radius: 50%;
  background: rgba(255, 244, 184, 0.45);
  box-shadow: 0 0 0 22px rgba(255, 244, 184, 0.13);
}

.brief-cloud {
  position: absolute;
  height: 20px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.3);
}

.brief-cloud.bc1 { width: 82px; top: 38px; left: 41%; }
.brief-cloud.bc2 { width: 54px; top: 70px; right: 33%; height: 15px; }

.brief-hill {
  position: absolute;
  bottom: -50px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.12);
}

.brief-hill.bh1 { width: 330px; height: 160px; right: -30px; }
.brief-hill.bh2 { width: 250px; height: 120px; left: 35%; bottom: -70px; background: rgba(255, 255, 255, 0.08); }

.brief-hero-copy {
  position: relative;
  z-index: 2;
  max-width: 62%;
}

.brief-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 9px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.22);
  border: 1px solid rgba(255, 255, 255, 0.22);
  font-size: 0.6rem;
  font-weight: 800;
