.brief-hero-copy > p {
  color: rgba(255, 255, 255, 0.93);
  font-size: 0.78rem;
  max-width: 430px;
}

.brief-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 14px;
}

.brief-meta span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(18, 33, 50, 0.17);
  color: #fff;
