}

.brief-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(220px, 0.85fr);
  gap: 16px;
}

.brief-story {
  padding: 2px 2px 0;
}

.brief-story .eyebrow { font-size: 0.59rem; }

.brief-story h3 {
  font-size: 1.12rem;
  margin: 2px 0 7px;
}

.brief-story > p {
  color: #526c7d;
  font-size: 0.8rem;
  line-height: 1.75;
}

.brief-location {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 11px;
  padding: 8px 10px;
  border-radius: 8px;
  background: #f7f8f2;
