  grid-template-columns: 1fr 1fr;
  gap: 7px;
}

.brief-reward {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 3px;
  padding: 7px 8px;
  border-radius: 8px;
  background: #fff;
  border: 1px solid #f0e7d6;
  font-size: 0.59rem;
