.brief-reward b { font-family: var(--display); font-size: 1.02rem; font-weight: 400; }
.brief-reward small { width: 100%; color: #9aa7ae; font-size: 0.54rem; font-weight: 600; }
.brief-reward.coin { color: #a67712; }
