.brief-rewards > p { margin-top: 7px; color: #96a2a6; font-size: 0.57rem; }

.brief-skill-chips { display: flex; flex-wrap: wrap; gap: 4px; }
.brief-skill-chips span { padding: 3px 8px; border-radius: 5px; background: #fff; border: 1px solid #ede7dc; color: #637f8d; font-size: 0.59rem; font-weight: 700; }

.brief-learn ul { display: flex; flex-direction: column; gap: 5px; }
