.brief-source {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 15px;
  padding-top: 12px;
  border-top: 1px solid #f0e9dc;
  flex-wrap: wrap;
}

.brief-verify {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.verify-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  padding: 3px 7px;
  border-radius: 5px;
  background: #f1f1ea;
  color: #8e998f;
  font-size: 0.56rem;
  font-weight: 800;
}

.verify-pill.verified { background: #e3f7ef; color: #16876e; }
.brief-verify p { color: #8c9ba3; font-size: 0.6rem; }
.brief-source-date { color: #9eabb1; font-size: 0.58rem; white-space: nowrap; }

.brief-lock-note {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 12px;
  padding: 9px 11px;
  border-radius: 8px;
  background: #fff4e6;
  color: #8a6425;
  font-size: 0.66rem;
}

.brief-actions {
  margin-top: 15px;
  padding-top: 13px;
  border-top: 1px solid #f1ece3;
}

.brief-disclaimer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 11px;
  color: #9ba8ae;
  font-size: 0.57rem;
  text-align: center;
}

/* ============================================================
   RESULT
   ============================================================ */
.result-screen {
  position: relative;
  flex: 1;
  min-height: 100svh;
  padding: 28px 18px 40px;
  overflow: hidden;
  background:
    radial-gradient(800px 380px at 12% -5%, rgba(144, 221, 255, 0.55), transparent 60%),
    radial-gradient(760px 380px at 95% 4%, rgba(255, 221, 116, 0.36), transparent 58%),
    linear-gradient(#eefbff 0%, #f7fbf3 48%, #fffaf0 100%);
}

.result-failed {
  background:
    radial-gradient(800px 380px at 12% -5%, rgba(191, 222, 240, 0.6), transparent 60%),
    radial-gradient(760px 380px at 95% 4%, rgba(255, 205, 177, 0.32), transparent 58%),
    linear-gradient(#eff7fa 0%, #faf8f1 50%, #fffaf0 100%);
}

.result-sky {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.result-sun {
  position: absolute;
  width: 180px;
  height: 180px;
  top: -45px;
  right: 12%;
  border-radius: 50%;
  background: rgba(255, 226, 122, 0.42);
  box-shadow: 0 0 0 35px rgba(255, 226, 122, 0.1);
}

.result-cloud {
  position: absolute;
  height: 34px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.65);
}

.result-cloud.rc1 { width: 160px; height: 46px; top: 9%; left: 6%; }
.result-cloud.rc2 { width: 100px; height: 30px; top: 18%; right: 25%; }
.result-cloud::before,
.result-cloud::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  background: inherit;
}
.result-cloud::before { width: 55%; height: 160%; left: 10%; bottom: 18%; }
.result-cloud::after { width: 42%; height: 125%; right: 8%; bottom: 22%; }

.result-rays {
  position: absolute;
  width: 340px;
  height: 340px;
  top: -140px;
  right: 4%;
  background: repeating-conic-gradient(from 0deg, rgba(255, 215, 94, 0.12) 0 8deg, transparent 8deg 19deg);
  border-radius: 50%;
  mask-image: radial-gradient(circle, #000 25%, transparent 69%);
}

.result-inner {
  position: relative;
  z-index: 4;
  width: min(1080px, 100%);
  margin: 0 auto;
}

.result-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.result-mode {
  color: #7e94a3;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.result-status {
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 800;
}

.result-status.success { background: #dcf8ed; color: #137c60; }
.result-status.failed { background: #ffe9e2; color: #ae4d31; }

.result-hero {
  display: flex;
  align-items: center;
  gap: 22px;
  padding: 22px 26px;
  border-radius: 24px;
  background: rgba(255, 253, 247, 0.86);
  border: 1px solid rgba(255, 255, 255, 0.9);
  box-shadow: 0 16px 38px rgba(35, 74, 101, 0.12);
  backdrop-filter: blur(10px);
}

.result-failed .result-hero { background: rgba(255, 253, 247, 0.9); }

.result-mascot {
  flex: 0 0 auto;
  width: 150px;
  display: grid;
  place-items: center;
}

.result-mascot svg { width: 148px; height: auto; }

.result-title-block {
  flex: 1;
  min-width: 0;
}

.result-title-block .eyebrow { font-size: 0.6rem; }
.result-title-block h1 { font-size: clamp(1.55rem, 3vw, 2.3rem); margin: 4px 0 7px; }
.result-title-block > p { color: #617a8b; font-size: 0.8rem; line-height: 1.6; max-width: 480px; }
.result-title-block .stars { margin-top: 11px; }

.result-score-card {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 9px;
  padding: 8px 4px 8px 18px;
  border-left: 1px solid #eee5d7;
}

.result-score-meta {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  color: #8193a0;
  font-size: 0.6rem;
}

.result-score-meta b { color: var(--navy); font-size: 0.8rem; }

.result-fail-card {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  max-width: 300px;
  padding: 13px 15px;
  border-radius: 13px;
  background: #fff4ed;
  border: 1px solid #ffd9ca;
}

.result-fail-icon {
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #ffdfcf;
  color: #c6502e;
  font-family: var(--display);
  font-size: 1.1rem;
}

.result-fail-card b { display: block; color: #9b492b; font-size: 0.72rem; }
.result-fail-card p { color: #9c7564; font-size: 0.65rem; line-height: 1.5; margin-top: 2px; }

.result-reward-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 13px;
}

.result-reward-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 15px;
  border-radius: 15px;
  background: rgba(255, 253, 247, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow: 0 8px 20px rgba(35, 74, 101, 0.07);
}

.reward-icon {
  width: 39px;
  height: 39px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 11px;
  font-family: var(--display);
  font-size: 1.25rem;
}

.result-reward-card.coin .reward-icon { background: #fff3c9; color: #ae7f0d; }
.result-reward-card.xp .reward-icon { background: #e3f1ff; color: #2b76b9; }
.result-reward-card.best .reward-icon { background: #edf9f1; color: #1c8b63; }

.result-reward-card > div { display: flex; flex-direction: column; min-width: 0; }
.result-reward-card small { color: #95a3ac; font-size: 0.56rem; font-weight: 700; }
.result-reward-card b { color: var(--navy); font-family: var(--display); font-size: 1.27rem; font-weight: 400; line-height: 1.2; }
.reward-note { margin-left: auto; max-width: 78px; color: #9ca9ae; font-size: 0.54rem; line-height: 1.4; text-align: right; }

.result-unlocks {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 11px;
}

.unlock-row {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 13px;
  border-radius: 12px;
  background: rgba(255, 253, 247, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.9);
  box-shadow: 0 5px 14px rgba(35, 74, 101, 0.06);
}

.unlock-row.level-up-row { background: linear-gradient(100deg, #fff8de, #fffdf7); border-color: #f5e5af; }
.unlock-icon {
  width: 35px;
  height: 35px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #fff1be;
  font-size: 1.1rem;
}

.unlock-icon.knowledge { background: #e8f6ff; }
.unlock-row > div { flex: 1; min-width: 0; }
.unlock-row b { display: block; color: var(--navy); font-size: 0.74rem; }
.unlock-row p { color: #84949e; font-size: 0.63rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.unlock-tag { padding: 3px 8px; border-radius: 5px; background: #e4f8f0; color: #16836b; font-size: 0.55rem; font-weight: 800; white-space: nowrap; }
.unlock-link { display: inline-flex; align-items: center; gap: 3px; border: 0; background: none; color: #2b76b9; font-size: 0.62rem; font-weight: 800; white-space: nowrap; }
.levelup-track { width: 110px; flex: 0 0 auto; }

.result-breakdown {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  margin-top: 11px;
  overflow: hidden;
  border-radius: 12px;
  background: #eee8dc;
  border: 1px solid #f0e9db;
}

.result-breakdown > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 12px;
  background: rgba(255, 253, 247, 0.92);
}

.result-breakdown span { color: #8b9aa4; font-size: 0.6rem; }
.result-breakdown b { color: var(--navy); font-size: 0.72rem; }

.result-retry-tips {
  margin-top: 12px;
  padding: 15px 18px;
  border-radius: 16px;
  background: rgba(255, 253, 247, 0.9);
  border: 1px solid #eee6d9;
}

.retry-tip-head {
  display: flex;
  align-items: flex-start;
  gap: 9px;
}

.retry-tip-head > span {
  width: 35px;
  height: 35px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #fff1d4;
  font-size: 1.1rem;
}

.retry-tip-head b { color: var(--navy); font-size: 0.79rem; }
.retry-tip-head p { color: #81919b; font-size: 0.64rem; }
.result-retry-tips ul { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 11px; }

.result-retry-tips li {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 8px 10px;
  border-radius: 8px;
  background: #f8f8f1;
  color: #657b89;
  font-size: 0.64rem;
  line-height: 1.5;
}

.result-retry-tips li span {
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #e7ece7;
  color: #758a83;
  font-size: 0.55rem;
  font-weight: 800;
}

.result-actions {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 17px;
}

.result-disclaimer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 13px;
  color: #9aa8ae;
  font-size: 0.58rem;
  text-align: center;
}

/* ============================================================
   GAME SHELL / SHARED GAME UI
   ============================================================ */
.app-game {
  background:
    radial-gradient(900px 400px at 10% -10%, rgba(206, 238, 250, 0.6), transparent 60%),
    #f4f0e6;
}

.game-shell {
  width: min(1440px, 100%);
  margin: 0 auto;
  padding: 14px clamp(10px, 2vw, 24px) 28px;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
}

.game-status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 54px;
  margin-bottom: 12px;
  padding: 8px 13px;
  border-radius: 14px;
  background: rgba(255, 253, 248, 0.9);
  border: 1px solid #eae2d5;
  box-shadow: 0 3px 10px rgba(26, 54, 84, 0.04);
  backdrop-filter: blur(8px);
}

.game-status-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.game-quit {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  height: 32px;
  padding: 0 10px;
  border: 1px solid #e8dfd2;
  border-radius: 8px;
  background: #fff;
  color: #687f8e;
  font-size: 0.68rem;
  font-weight: 700;
}

.game-quit:hover { border-color: #d9c9b6; color: var(--navy); }

.mission-live-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--navy);
  font-size: 0.8rem;
  font-weight: 800;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mission-live-title span { font-size: 0.95rem; }

.hint-button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex: 0 0 auto;
  height: 32px;
  padding: 0 10px;
  border: 1px solid #f0ddb1;
  border-radius: 8px;
  background: #fff8e4;
  color: #967020;
  font-size: 0.68rem;
  font-weight: 800;
}

.hint-button:hover:not(:disabled) { background: #fff3cc; }
.hint-button.used,
.hint-button:disabled { opacity: 0.5; }

.quit-overlay,
.pause-overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(15, 35, 55, 0.55);
  backdrop-filter: blur(5px);
  animation: fade-in 0.16s ease both;
}

.quit-panel,
.pause-panel {
  width: min(380px, 100%);
  padding: 25px;
  border-radius: 20px;
  background: var(--paper);
  box-shadow: var(--shadow-lg);
  text-align: center;
  animation: modal-pop 0.22s cubic-bezier(0.2, 1.2, 0.4, 1) both;
}

.quit-emoji { display: block; font-size: 2.4rem; margin-bottom: 4px; }
.quit-panel h2, .pause-panel h2 { font-size: 1.35rem; }
.quit-panel p, .pause-panel p { margin: 5px 0 0; color: var(--muted); font-size: 0.78rem; }
.quit-panel .modal-actions { justify-content: center; }

.hint-popover {
  position: fixed;
  z-index: 100;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  width: min(470px, calc(100vw - 32px));
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 13px;
  border-radius: 14px;
  background: #fffdf5;
  border: 1px solid #f0dfb6;
  box-shadow: 0 14px 34px rgba(20, 45, 70, 0.2);
  animation: toast-in 0.22s ease both;
}

.hint-popover > span {
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #fff1c8;
  font-size: 1rem;
}

.hint-popover p { flex: 1; color: #6b5b37; font-size: 0.72rem; line-height: 1.55; }
.hint-popover button { flex: 0 0 auto; padding: 6px 10px; border: 0; border-radius: 7px; background: var(--navy); color: #fff; font-size: 0.64rem; font-weight: 700; }

.pause-panel > span { display: block; font-size: 2.2rem; }
.pause-panel .game-btn { margin-top: 14px; }

.training-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.86);
  color: #587484;
  font-size: 0.58rem;
  font-weight: 700;
}

.training-pill i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #42c88f;
  box-shadow: 0 0 0 3px rgba(66, 200, 143, 0.18);
}

.eyebrow { text-transform: uppercase; }

