input.newString:
.eyebrow { text-transform: uppercase; }

/* ============================================================
   FIRE ESCAPE GAME
   ============================================================ */
.fire-game {
  min-height: 100svh;
}

.stage-progress {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.stage-progress-label {
  color: #7b8f9c;
  font-size: 0.58rem;
  font-weight: 800;
}

.stage-dots {
  display: flex;
  gap: 5px;
}

.stage-dots span {
  width: 17px;
  height: 4px;
  border-radius: 99px;
  background: #e4e3d8;
  transition: 0.2s;
}

.stage-dots span.done { background: var(--teal); }
.stage-dots span.active { width: 26px; background: var(--primary); }

.safety-meter {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 0 0 auto;
}

.safety-meter-label {
  color: #8d9ca5;
  font-size: 0.57rem;
  font-weight: 700;
  white-space: nowrap;
}

.safety-meter-track {
  width: 82px;
  height: 6px;
  overflow: hidden;
  border-radius: 99px;
  background: #edeee7;
}

.safety-meter-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  transition: width 0.3s ease, background 0.3s;
}

.safety-meter b {
  color: var(--navy);
  font-family: var(--display);
  font-size: 0.85rem;
  font-weight: 400;
}

.fire-game-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(390px, 0.96fr);
  gap: 14px;
  align-items: stretch;
}

.fire-scene-column {
  display: flex;
  flex-direction: column;
  gap: 9px;
  min-width: 0;
}

.fire-scene {
  position: relative;
  aspect-ratio: 900 / 560;
  min-height: 330px;
  max-height: calc(100svh - 215px);
  width: 100%;
  border-radius: 20px;
  overflow: hidden;
  background: #e8d7bd;
  box-shadow: 0 12px 30px rgba(26, 54, 84, 0.15);
  isolation: isolate;
}

.fire-scene-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.scene-sky-glow {
  position: absolute;
  inset: 0;
  background: radial-gradient(500px 300px at 72% 42%, rgba(255, 139, 64, 0.18), transparent 68%);
  z-index: 1;
  pointer-events: none;
}

.scene-vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    linear-gradient(to bottom, transparent 58%, rgba(23, 39, 54, 0.55) 100%),
    radial-gradient(circle at 50% 45%, transparent 48%, rgba(20, 38, 52, 0.18) 100%);
}

.scene-caption {
  position: absolute;
  z-index: 6;
  left: 13px;
  right: 13px;
  bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.danger-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 9px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.92);
  color: #607480;
  font-size: 0.6rem;
  font-weight: 800;
  box-shadow: 0 3px 9px rgba(15, 35, 55, 0.17);
}

.danger-badge i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #55bf8d;
}

.danger-badge.danger-2 { color: #8d6b21; }
.danger-badge.danger-2 i { background: #f3b23e; }
.danger-badge.danger-3 { color: #a8492f; }
.danger-badge.danger-3 i { background: #ec5a42; animation: soft-blink 1.2s infinite; }

.scene-location-label {
  padding: 4px 9px;
  border-radius: 6px;
  background: rgba(18, 37, 55, 0.55);
  color: #f1f8f9;
  font-size: 0.6rem;
  font-weight: 700;
  backdrop-filter: blur(3px);
}

.scene-character {
  position: absolute;
  z-index: 5;
  right: 4%;
  bottom: 13%;
  filter: drop-shadow(0 8px 10px rgba(15, 35, 52, 0.24));
  animation: mascot-bob 3s ease-in-out infinite;
}

.scene-character svg { width: 92px; height: auto; }

.fire-particles {
  position: absolute;
  inset: 0;
  z-index: 3;
  overflow: hidden;
  pointer-events: none;
}

.fire-particles span {
  position: absolute;
  left: var(--x);
  bottom: 18%;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #ffcb66;
  opacity: 0;
  box-shadow: 0 0 5px #ff9b4a;
  animation: ember-rise 3.1s linear var(--delay) infinite;
}

.fire-particles span:nth-child(3n) { width: 3px; height: 3px; background: #ff8a4d; }
.fire-particles span:nth-child(4n) { left: calc(var(--x) + 9%); }

.scene-smoke-layer {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  overflow: hidden;
}

.smoke-puff {
  position: absolute;
  border-radius: 50%;
  background: rgba(121, 131, 137, 0.17);
  filter: blur(7px);
  animation: smoke-drift 8s ease-in-out infinite alternate;
}

.smoke-puff.sp1 { width: 32%; height: 18%; left: -6%; bottom: 15%; }
.smoke-puff.sp2 { width: 26%; height: 15%; right: 15%; top: 18%; animation-delay: -2s; }
.smoke-puff.sp3 { width: 22%; height: 12%; left: 34%; bottom: 9%; animation-delay: -4s; }

.scene-flame { animation: flame-flicker 0.9s ease-in-out infinite alternate; transform-origin: center bottom; }
.window-fire-glow { animation: glow-pulse 2s ease-in-out infinite alternate; }
.scene-smoke-source { animation: smoke-drift 6s ease-in-out infinite alternate; }

.scene-condition {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 11px 13px;
  border-radius: 12px;
  background: rgba(255, 252, 245, 0.94);
  border: 1px solid #ebe2d4;
  box-shadow: var(--shadow-sm);
}

.condition-icon {
  width: 29px;
  height: 29px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: #e9f5ff;
  color: #2d81c5;
}

.scene-condition b { display: block; color: #537080; font-size: 0.63rem; margin-bottom: 1px; }
.scene-condition p { color: #6f8491; font-size: 0.7rem; line-height: 1.55; }

.scene-bottom-note {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 4px;
  color: #94a3aa;
  font-size: 0.59rem;
}

.scene-bottom-note button {
  flex: 0 0 auto;
  padding: 3px 6px;
  border: 0;
  background: none;
  color: #7d929d;
  font-size: 0.59rem;
  font-weight: 700;
  text-decoration: underline;
}

.decision-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 16px 18px;
  border-radius: 20px;
  background: rgba(255, 253, 248, 0.96);
  border: 1px solid #eae1d3;
  box-shadow: 0 10px 28px rgba(26, 54, 84, 0.08);
}

.decision-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 9px;
}

.decision-step-chip {
  padding: 4px 8px;
  border-radius: 6px;
  background: var(--navy);
  color: #fff;
  font-size: 0.56rem;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.decision-topic {
  color: #8799a4;
  font-size: 0.61rem;
  font-weight: 700;
}

.decision-header .hint-button { margin-left: auto; }

.narrative-chip {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 11px;
  border-radius: 10px;
  background: #f6f8f1;
  border: 1px solid #edf0e4;
}

.narrative-icon { flex: 0 0 auto; font-size: 0.9rem; margin-top: 1px; }
.narrative-chip p { color: #617888; font-size: 0.72rem; line-height: 1.55; }

.decision-question {
  margin: 11px 0 9px;
  color: var(--navy);
  font-size: clamp(1.02rem, 1.5vw, 1.22rem);
  line-height: 1.38;
  letter-spacing: -0.005em;
}

.choice-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.choice-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-height: 51px;
  padding: 9px 12px 9px 10px;
  border: 1.5px solid #e9e2d5;
  border-radius: 12px;
  background: #fffefa;
  text-align: left;
  transition: border-color 0.14s, background 0.14s, transform 0.14s;
}

.choice-card:hover:not(:disabled):not(.is-eliminated) {
  border-color: #bcdcd1;
  background: #f9fffc;
  transform: translateX(2px);
}

.choice-marker {
  width: 27px;
  height: 27px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 8px;
  background: #f2efe6;
  color: #7f8e91;
  font-family: var(--display);
  font-size: 0.68rem;
}

.choice-copy {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  gap: 1px;
}

.choice-copy b { color: #375263; font-size: 0.74rem; line-height: 1.45; font-weight: 700; }
.choice-copy small { color: #92a0a6; font-size: 0.61rem; line-height: 1.4; }

.choice-card.is-selected { border-color: #90b8d7; background: #f5fbff; }

.choice-card.is-correct {
  border-color: #47c79f;
  background: #eefbf6;
  box-shadow: 0 0 0 3px rgba(71, 199, 159, 0.1);
}

.choice-card.is-correct .choice-marker { background: #41bf98; color: #fff; }

.choice-card.is-wrong {
  border-color: #ef8d7a;
  background: #fff5f2;
  animation: card-shake 0.35s ease;
}

.choice-card.is-wrong .choice-marker { background: #ed7b65; color: #fff; }

.choice-card.is-eliminated {
  opacity: 0.5;
  background: #f5f3ed;
  text-decoration: line-through;
  text-decoration-color: #c9a09a;
}

.choice-result-icon {
  width: 23px;
  height: 23px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
}

.choice-result-icon.correct { background: #41bf98; }
.choice-result-icon.wrong { background: #eb715c; }

.choice-eliminated-label {
  flex: 0 0 auto;
  padding: 2px 5px;
  border-radius: 4px;
  background: #f7dfd8;
  color: #b26755;
  font-size: 0.5rem;
  font-weight: 800;
}

.feedback-card {
  margin-top: 9px;
  padding: 10px 12px;
  border-radius: 12px;
  border: 1px solid;
  animation: feedback-in 0.2s ease both;
}

.feedback-correct { background: #f1fcf8; border-color: #ccefe4; }
.feedback-wrong { background: #fff7f4; border-color: #f5d6cc; }

.feedback-head {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.feedback-icon {
  width: 24px;
  height: 24px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #fff;
  font-size: 0.7rem;
  font-weight: 900;
}

.feedback-correct .feedback-icon { background: #3fbd93; }
.feedback-wrong .feedback-icon { background: #e87963; }

.feedback-head > div { flex: 1; min-width: 0; }
.feedback-head b { display: block; color: #245e51; font-size: 0.74rem; }
.feedback-wrong .feedback-head b { color: #984a3a; }
.feedback-head > div span { color: #6e8e86; font-size: 0.63rem; line-height: 1.45; display: block; }
.feedback-xp { flex: 0 0 auto; padding: 2px 6px; border-radius: 5px; background: #fff; color: #1d9a78; font-size: 0.58rem; font-weight: 900; }
.feedback-wrong .feedback-xp { color: #cf604a; }

.feedback-card > p {
  margin: 6px 0 0 32px;
  color: #56736b;
  font-size: 0.67rem;
  line-height: 1.55;
}

.feedback-wrong > p { color: #916e64; }

.explanation-box {
  margin: 8px 0 0 32px;
  padding: 8px 9px;
  border-radius: 8px;
  background: #fffdf7;
  border: 1px solid #eee8d8;
}

.explain-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 3px;
  color: #8b7a4d;
  font-size: 0.56rem;
  font-weight: 800;
}

.explanation-box p { color: #6b7c78; font-size: 0.65rem; line-height: 1.55; }

.caution-line {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin: 6px 0 0 32px;
  color: #a37b2c;
  font-size: 0.61rem;
  line-height: 1.45;
}

.caution-line svg { flex: 0 0 auto; margin-top: 1px; }

.source-line {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
  margin: 6px 0 0 32px;
  color: #98a4a7;
  font-size: 0.56rem;
}

.source-line span { color: #a2aeb0; }
.source-line i.verified { padding: 1px 5px; border-radius: 4px; background: #def5eb; color: #16886c; font-size: 0.5rem; font-style: normal; font-weight: 800; }

.feedback-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
  margin-top: 9px;
}

.text-action {
  padding: 5px 7px;
  border: 0;
  background: none;
  color: #98a5a9;
  font-size: 0.62rem;
  text-decoration: underline;
}

.decision-footnote {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin-top: auto;
  padding-top: 9px;
  color: #9aa8ad;
  font-size: 0.59rem;
  line-height: 1.5;
}

.decision-footnote svg { flex: 0 0 auto; margin-top: 1px; }

/* ---------- hazard hunt ---------- */
.hazard-game { min-height: 100svh; }

.hazard-mode-note {
  color: #8b9ba4;
  font-size: 0.62rem;
  font-weight: 700;
  white-space: nowrap;
}

.hazard-hud {
  display: flex;
  align-items: center;
  gap: 7px;
  flex: 0 0 auto;
}

.timer-chip {
  display: flex;
  align-items: center;
  gap: 5px;
  position: relative;
  min-width: 105px;
  height: 33px;
  padding: 0 9px;
  border-radius: 8px;
  background: #f0f7f4;
  color: #367065;
  overflow: hidden;
}

.timer-chip b {
  font-size: 0.72rem;
  font-variant-numeric: tabular-nums;
}

.timer-chip.urgent { background: #fff0eb; color: #cf4d30; animation: soft-blink 1s infinite; }

.timer-track {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  height: 3px;
  background: rgba(49, 117, 100, 0.1);
}

.timer-track i { display: block; height: 100%; background: #43bd99; transition: width 1s linear; }
.timer-chip.urgent .timer-track i { background: #eb654c; }

.combo-chip {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 33px;
  padding: 0 9px;
  border-radius: 8px;
  background: #fff6df;
  color: #9b7627;
  font-size: 0.58rem;
  font-weight: 700;
  white-space: nowrap;
}

.combo-chip b { font-size: 0.72rem; color: #b47711; }
.combo-chip > span { font-size: 0.75rem; }

.hazard-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 268px;
  gap: 12px;
  align-items: start;
}

.hazard-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.hazard-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
}

.hazard-progress-card {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex: 1;
  padding: 9px 12px;
  border-radius: 11px;
  background: rgba(255, 253, 248, 0.9);
  border: 1px solid #eae2d4;
}

.hazard-progress-icon {
  width: 31px;
  height: 31px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #fff1d4;
  font-size: 0.95rem;
}

.hazard-progress-card > div:not(.hazard-found-dots) { display: flex; flex-direction: column; min-width: 0; }
.hazard-progress-card b { color: var(--navy); font-size: 0.72rem; }
.hazard-progress-card span { color: #90a0a8; font-size: 0.59rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.hazard-found-dots { display: flex; gap: 3px; margin-left: auto; flex: 0 0 auto; }
.hazard-found-dots i { width: 7px; height: 7px; border-radius: 50%; background: #e5e3d8; }
.hazard-found-dots i.done { background: #43bd98; box-shadow: 0 0 0 2px rgba(67, 189, 152, 0.12); }

.hazard-actions { display: flex; align-items: center; gap: 6px; flex: 0 0 auto; }
.hazard-actions .game-btn { min-height: 33px; padding: 0 10px; font-size: 0.64rem; }

.room-canvas {
  position: relative;
  width: 100%;
  aspect-ratio: 900 / 560;
  min-height: 330px;
  max-height: calc(100svh - 300px);
  overflow: hidden;
  border-radius: 20px;
  border: 1px solid #e6d9c4;
  background: #eeddc8;
  box-shadow: 0 13px 32px rgba(27, 54, 80, 0.15);
  isolation: isolate;
  touch-action: manipulation;
}

.room-canvas.room-shake { animation: room-shake 0.34s ease; }

.room-art {
  position: absolute;
  inset: 0;
  overflow: hidden;
}

.room-ceiling { position: absolute; left: 0; right: 0; top: 0; height: 8%; background: linear-gradient(#efdfca, #f7ecdc); border-bottom: 2px solid rgba(150, 125, 97, 0.15); }
.room-wall { position: absolute; left: 0; right: 0; top: 8%; height: 63%; }
.room-floor { position: absolute; left: 0; right: 0; bottom: 0; height: 29%; }
.room-door { position: absolute; right: 3%; bottom: 11%; width: 11%; height: 44%; z-index: 1; }
.door-frame { position: absolute; inset: 0; border-radius: 4px; background: #8f6a4e; }
.door-panel { position: absolute; inset: 5px; border-radius: 2px; background: #b28662; box-shadow: inset 0 0 0 2px rgba(255, 245, 225, 0.18); }
.door-knob { position: absolute; right: 12%; top: 52%; width: 5px; height: 5px; border-radius: 50%; background: #f4cf7b; }

.room-tip {
  position: absolute;
  left: 50%;
  bottom: 10px;
  transform: translateX(-50%);
  z-index: 8;
  padding: 5px 12px;
  border-radius: 99px;
  background: rgba(20, 39, 56, 0.64);
  color: #f5fbfa;
  font-size: 0.6rem;
  font-weight: 600;
  backdrop-filter: blur(3px);
  white-space: nowrap;
}

.hazard-object {
  position: absolute;
  z-index: 5;
  transform: translate(-50%, -50%) scale(var(--scale, 1)) rotate(var(--rotate, 0deg));
  width: clamp(38px, 5.5vw, 68px);
  height: clamp(38px, 5.5vw, 68px);
  display: grid;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 13px;
  background: transparent;
  transition: background 0.14s, border-color 0.14s, transform 0.14s;
}

.hazard-object:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.4);
  border-color: rgba(255, 255, 255, 0.65);
  transform: translate(-50%, -50%) scale(calc(var(--scale, 1) * 1.1)) rotate(var(--rotate, 0deg));
}

.hazard-object:focus-visible { outline-offset: 1px; }

.object-emoji {
  font-size: clamp(1.65rem, 3.05vw, 2.7rem);
  line-height: 1;
  filter: drop-shadow(0 3px 3px rgba(45, 35, 20, 0.18));
  pointer-events: none;
}

.hazard-object.is-found {
  background: rgba(226, 249, 240, 0.8);
  border-color: rgba(49, 174, 138, 0.55);
  transform: translate(-50%, -50%) scale(var(--scale, 1));
}

.hazard-object.is-found .object-emoji { opacity: 0.52; filter: grayscale(0.35); }

.found-check {
  position: absolute;
  right: -4px;
  top: -4px;
  width: 21px;
  height: 21px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #36b78d;
  color: #fff;
  border: 2px solid #fff;
  z-index: 2;
}

.hint-ring {
  position: absolute;
  inset: -7px;
  border-radius: 16px;
  border: 2.5px dashed #f3b534;
  animation: hint-pulse 0.85s ease-in-out infinite alternate;
  pointer-events: none;
}

.decoy-object { z-index: 4; opacity: 0.9; }
.decoy-object .object-emoji { font-size: clamp(1.4rem, 2.6vw, 2.25rem); }
.decoy-object.is-wrong { animation: card-shake 0.4s ease; }

.wrong-mark {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #e4563e;
  font-size: 1.3rem;
  font-weight: 900;
  text-shadow: 0 1px 0 #fff;
}

/* kitchen scene */
.kitchen-wall {
  background:
    repeating-linear-gradient(90deg, transparent 0 54px, rgba(170, 148, 116, 0.11) 54px 56px),
    repeating-linear-gradient(0deg, transparent 0 42px, rgba(170, 148, 116, 0.11) 42px 44px),
    linear-gradient(#f2e2cc, #e8d1b6);
}

.kitchen-floor {
  background:
    repeating-linear-gradient(90deg, transparent 0 64px, rgba(128, 94, 65, 0.11) 64px 67px),
    linear-gradient(105deg, #cba37a 0 38%, #bf936b 38% 64%, #c8a077 64%);
  border-top: 5px solid #a87b57;
}

.kitchen-window {
  position: absolute;
