}

.sofa-back { position: absolute; left: 4%; right: 4%; top: 0; height: 59%; border-radius: 13px 13px 4px 4px; background: #6e9482; }
.sofa-seat { position: absolute; left: 0; right: 0; top: 46%; height: 31%; border-radius: 7px; background: #83a894; box-shadow: 0 4px 0 #557666; }
