}

.tv-screen { position: absolute; inset: 0 0 22%; border-radius: 5px; background: #334858; border: 5px solid #26333d; box-shadow: inset 0 0 0 2px rgba(158, 196, 205, 0.16); }
.tv-stand { position: absolute; left: 15%; right: 15%; bottom: 0; height: 20%; border-radius: 3px; background: #88684e; }

.living-table {
  position: absolute;
  left: 38%;
  bottom: 17%;
  width: 22%;
  height: 15%;
  z-index: 3;
}

.coffee-top { position: absolute; left: 0; right: 0; top: 0; height: 19%; border-radius: 5px; background: #c18d60; box-shadow: 0 3px 0 #936844; }
.coffee-leg { position: absolute; top: 18%; width: 6%; height: 82%; background: #9d704d; }
.coffee-leg.l { left: 10%; }
.coffee-leg.r { right: 10%; }

.living-rug { position: absolute; left: 32%; bottom: 3%; width: 36%; height: 12%; border-radius: 50%; background: #bba384; opacity: 0.7; box-shadow: inset 0 0 0 5px rgba(255, 247, 230, 0.25); }

.living-lamp { position: absolute; left: 79%; bottom: 35%; width: 12%; height: 33%; z-index: 2; }
.lamp-shade { position: absolute; left: 12%; top: 0; width: 76%; height: 28%; background: #f3d79c; clip-path: polygon(20% 0, 80% 0, 100% 100%, 0 100%); border-radius: 3px; box-shadow: 0 0 22px rgba(255, 222, 146, 0.35); }
.lamp-pole { position: absolute; left: 47%; top: 27%; width: 6%; height: 60%; background: #756044; }
.lamp-base { position: absolute; left: 25%; bottom: 0; width: 50%; height: 5%; border-radius: 50%; background: #68523a; }

.living-tree { position: absolute; right: 1%; bottom: 12%; width: 12%; height: 23%; z-index: 2; }
.tree-top { position: absolute; left: 0; top: -9%; font-size: clamp(2rem, 4vw, 3.4rem); line-height: 1; }
.tree-pot { position: absolute; left: 27%; bottom: 0; width: 46%; height: 27%; border-radius: 2px 2px 6px 6px; background: #a96f4c; }
.wall-art { position: absolute; left: 41%; top: 20%; width: 14%; height: 15%; border: 5px solid #f7efe1; background: #9fc8c2; box-shadow: 0 3px 7px rgba(95, 70, 48, 0.14); }
.wall-art span { display: block; color: #fff; font-family: var(--display); font-size: clamp(0.4rem, 0.8vw, 0.7rem); text-align: center; line-height: 1.3; padding-top: 12%; letter-spacing: 0.04em; }

/* bedroom scene */
.bedroom-wall {
  background:
    radial-gradient(circle at 20% 30%, rgba(255, 255, 255, 0.17) 1px, transparent 2px) 0 0 / 24px 24px,
    linear-gradient(#dcd3e2, #d2c5d7);
}

.bedroom-floor {
  background:
    repeating-linear-gradient(92deg, transparent 0 51px, rgba(83, 63, 62, 0.13) 51px 54px),
    linear-gradient(#b58e74, #a67d68);
  border-top: 6px solid #8c6654;
}

.bedroom-window {
  position: absolute;
  right: 5%;
  top: 11%;
  width: 23%;
  height: 36%;
  border: 6px solid #f3ecdf;
  border-radius: 6px;
  background: #263c60;
  overflow: hidden;
}

.moon { position: absolute; right: 16%; top: 13%; width: 28%; height: 25%; border-radius: 50%; background: #fff2b0; box-shadow: 0 0 22px rgba(255, 238, 164, 0.28); }
.bedroom-window .window-curtain { position: absolute; left: 0; top: 0; bottom: 0; width: 23%; background: #b8a3c3; }
.bedroom-window::after { content: ''; position: absolute; left: 50%; top: 0; bottom: 0; width: 4px; background: #f1e9dc; }

.bedroom-bed {
  position: absolute;
  left: 21%;
  bottom: 20%;
  width: 39%;
  height: 30%;
  z-index: 2;
}

.bed-headboard { position: absolute; left: 0; top: -42%; width: 12%; height: 138%; border-radius: 8px 8px 2px 2px; background: #7a5b53; }
.bed-mattress { position: absolute; left: 8%; right: 0; top: 24%; height: 54%; border-radius: 7px; background: #f3eadd; box-shadow: 0 7px 0 rgba(100, 73, 66, 0.25); }
.bed-pillow { position: absolute; left: 13%; top: 17%; width: 26%; height: 33%; border-radius: 9px; background: #fffdf6; transform: rotate(-3deg); box-shadow: inset 0 0 0 1px #e9e1d2; }
.bed-blanket { position: absolute; left: 37%; right: 1%; top: 29%; height: 50%; border-radius: 4px 7px 5px 4px; background: linear-gradient(135deg, #87a5b5, #6f8d9f); box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.14); }
.bed-leg { position: absolute; bottom: 0; width: 5%; height: 19%; background: #6c4f47; }
.bed-leg.l { left: 10%; }
.bed-leg.r { right: 4%; }

.bedroom-nightstand { position: absolute; right: 15%; bottom: 22%; width: 11%; height: 18%; z-index: 2; }
.night-lamp { position: absolute; left: 20%; top: -56%; width: 60%; height: 60%; border-radius: 50% 50% 7px 7px; background: #f3d592; box-shadow: 0 0 17px rgba(255, 218, 137, 0.45); }
.night-lamp i { position: absolute; left: 47%; top: 80%; width: 7%; height: 80%; background: #7f674e; }
.night-drawer { position: absolute; inset: 10% 0 0; border-radius: 3px; background: #b38d6b; box-shadow: inset 0 0 0 1px #9f7a5b; }
.night-drawer::after { content: ''; position: absolute; left: 42%; top: 30%; width: 16%; height: 4px; border-radius: 2px; background: #7f5f47; }

.bedroom-wardrobe {
  position: absolute;
  left: 3%;
  bottom: 18%;
  width: 14%;
  height: 40%;
  z-index: 2;
  display: flex;
  gap: 2px;
  padding: 4px;
  border-radius: 5px;
  background: #98756a;
}

.wardrobe-door { flex: 1; border-radius: 2px; background: #b08c7c; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.12); }
.wardrobe-handle { position: absolute; left: 48%; top: 47%; width: 5%; height: 8%; border-radius: 99px; background: #dfc07f; }

.bedroom-rug { position: absolute; left: 27%; bottom: 3%; width: 39%; height: 12%; border-radius: 50%; background: #b9a0b4; opacity: 0.72; box-shadow: inset 0 0 0 5px rgba(255, 250, 243, 0.2); }

.bedroom-dresser { position: absolute; left: 62%; bottom: 24%; width: 16%; height: 19%; z-index: 2; }
.dresser-top { position: absolute; inset: 0 0 72%; background: #a68164; border-radius: 3px 3px 0 0; }
.dresser-drawer { position: absolute; left: 5%; right: 5%; height: 28%; background: #bd9977; border-radius: 2px; }
.dresser-drawer:nth-of-type(2) { top: 33%; }
.dresser-drawer:nth-of-type(3) { top: 65%; }

.bedroom-smoke-detector { position: absolute; left: 47%; top: 10%; width: 5%; height: 2.2%; border-radius: 50%; background: #f7f1e2; box-shadow: 0 2px 4px rgba(50, 50, 70, 0.2); font-size: 0; }

.hazard-bottom-row {
  display: flex;
  align-items: stretch;
  gap: 8px;
}

.hazard-clue {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex: 1;
  min-width: 0;
  padding: 9px 11px;
  border-radius: 10px;
  background: rgba(255, 253, 248, 0.92);
  border: 1px solid #ece4d7;
}

.hazard-clue > span { flex: 0 0 auto; font-size: 0.9rem; margin-top: 1px; }
.hazard-clue p { color: #6d8391; font-size: 0.65rem; line-height: 1.5; }

.hazard-score-chip {
  flex: 0 0 auto;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 2px;
  min-width: 72px;
  padding: 9px 10px;
  border-radius: 10px;
  background: #173d66;
  color: #fff;
}

.hazard-score-chip b { font-family: var(--display); font-size: 1.15rem; font-weight: 400; }
.hazard-score-chip span { color: #9fc3d7; font-size: 0.56rem; }

.hazard-finish-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: #9aa8ad;
  font-size: 0.58rem;
}

.hazard-finish-row .game-btn { min-height: 30px; padding: 0 10px; font-size: 0.6rem; }

.hazard-side {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  padding: 13px;
  border-radius: 16px;
  background: rgba(255, 253, 248, 0.94);
  border: 1px solid #eae2d4;
  box-shadow: var(--shadow-sm);
}

.hazard-side-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid #f0e9dc;
  color: #728796;
  font-size: 0.65rem;
  font-weight: 800;
}

.hazard-side-head b { color: var(--teal-dark); font-size: 0.7rem; }

.hazard-checklist {
  display: flex;
  flex-direction: column;
  gap: 6px;
  overflow-y: auto;
  max-height: calc(100svh - 250px);
  padding-right: 2px;
}

.hazard-check-item {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  padding: 7px;
  border-radius: 8px;
  background: #f8f7f1;
  border: 1px solid #f0ece2;
}

.hazard-check-item.is-found { background: #f0fbf6; border-color: #d7f0e6; }

.hazard-check-icon {
  width: 19px;
  height: 19px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #e9e7dc;
  color: #9aa59f;
  font-size: 0.55rem;
  font-weight: 900;
}

.hazard-check-item.is-found .hazard-check-icon { background: #3db990; color: #fff; }

.hazard-check-item > div { min-width: 0; }
.hazard-check-item b { display: block; color: #566e7d; font-size: 0.63rem; line-height: 1.35; }
.hazard-check-item.is-found b { color: #1a705c; }
.hazard-check-item p { color: #94a2a8; font-size: 0.55rem; line-height: 1.45; margin-top: 1px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }

.hazard-clear-note {
  padding: 9px 10px;
  border-radius: 9px;
  background: #e9faf3;
  color: #17836a;
  font-size: 0.65rem;
  font-weight: 700;
  line-height: 1.45;
}

.hazard-clear-note svg { display: inline-block; vertical-align: -3px; margin-right: 3px; }
.hazard-clear-note span { color: #77a397; font-size: 0.56rem; font-weight: 500; }

.hazard-side-tip {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin-top: auto;
  padding-top: 8px;
  border-top: 1px solid #f1ece2;
  color: #98a5aa;
  font-size: 0.56rem;
  line-height: 1.5;
}

.hazard-side-tip svg { flex: 0 0 auto; margin-top: 1px; color: #7fa8b8; }

files.patch:
Index: src/index.css
===================================================================
--- src/index.css
+++ src/index.css
@@ -6328,4 +6328,1307 @@
 }

 .eyebrow { text-transform: uppercase; }

+/* ============================================================
+   FIRE ESCAPE GAME
+   ============================================================ */
+.fire-game {
+  min-height: 100svh;
+}
+
+.stage-progress {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 4px;
+}
+
+.stage-progress-label {
+  color: #7b8f9c;
+  font-size: 0.58rem;
+  font-weight: 800;
+}
+
+.stage-dots {
+  display: flex;
+  gap: 5px;
+}
+
+.stage-dots span {
+  width: 17px;
+  height: 4px;
+  border-radius: 99px;
+  background: #e4e3d8;
+  transition: 0.2s;
+}
+
+.stage-dots span.done { background: var(--teal); }
+.stage-dots span.active { width: 26px; background: var(--primary); }
+
+.safety-meter {
+  display: flex;
+  align-items: center;
+  gap: 7px;
+  flex: 0 0 auto;
+}
+
+.safety-meter-label {
+  color: #8d9ca5;
+  font-size: 0.57rem;
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+.safety-meter-track {
+  width: 82px;
+  height: 6px;
+  overflow: hidden;
+  border-radius: 99px;
+  background: #edeee7;
+}
+
+.safety-meter-track span {
+  display: block;
+  height: 100%;
+  border-radius: inherit;
+  transition: width 0.3s ease, background 0.3s;
+}
+
+.safety-meter b {
+  color: var(--navy);
+  font-family: var(--display);
+  font-size: 0.85rem;
+  font-weight: 400;
+}
+
+.fire-game-layout {
+  flex: 1;
+  display: grid;
+  grid-template-columns: minmax(0, 1.04fr) minmax(390px, 0.96fr);
+  gap: 14px;
+  align-items: stretch;
+}
+
+.fire-scene-column {
+  display: flex;
+  flex-direction: column;
+  gap: 9px;
+  min-width: 0;
+}
+
+.fire-scene {
+  position: relative;
+  aspect-ratio: 900 / 560;
+  min-height: 330px;
+  max-height: calc(100svh - 215px);
+  width: 100%;
+  border-radius: 20px;
+  overflow: hidden;
+  background: #e8d7bd;
+  box-shadow: 0 12px 30px rgba(26, 54, 84, 0.15);
+  isolation: isolate;
+}
+
+.fire-scene-svg {
+  position: absolute;
+  inset: 0;
+  width: 100%;
+  height: 100%;
+}
+
+.scene-sky-glow {
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(500px 300px at 72% 42%, rgba(255, 139, 64, 0.18), transparent 68%);
+  z-index: 1;
+  pointer-events: none;
+}
+
+.scene-vignette {
+  position: absolute;
+  inset: 0;
