.extinguisher-game { min-height: 100svh; }

.equip-progress-steps {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-wrap: wrap;
  justify-content: center;
}

.equip-progress-steps span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 7px;
  border-radius: 6px;
  color: #9aa8ad;
  font-size: 0.57rem;
  font-weight: 700;
  white-space: nowrap;
}

.equip-progress-steps span i {
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eceae1;
  color: #9ba5a4;
  font-size: 0.5rem;
  font-style: normal;
  font-weight: 900;
}

.equip-progress-steps span.active { background: #fff1e8; color: #cc5b3b; }
.equip-progress-steps span.active i { background: var(--primary); color: #fff; }
.equip-progress-steps span.done { color: #3a9379; }
.equip-progress-steps span.done i { background: #d7f4e9; color: #198b6d; }

.extinguisher-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.8fr) minmax(330px, 1fr);
  gap: 12px;
  align-items: stretch;
}

.extinguisher-arena-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.extinguisher-arena {
  position: relative;
  flex: 1;
  min-height: 490px;
  overflow: hidden;
  border-radius: 20px;
  background: linear-gradient(#e8dfd0 0 62%, #c9b292 62% 100%);
  box-shadow: 0 13px 34px rgba(27, 54, 80, 0.16);
  isolation: isolate;
}

.extinguisher-wall {
  position: absolute;
  inset: 0 0 38%;
  background:
    repeating-linear-gradient(90deg, transparent 0 70px, rgba(154, 130, 102, 0.16) 70px 73px),
    repeating-linear-gradient(0deg, transparent 0 56px, rgba(154, 130, 102, 0.13) 56px 59px),
    linear-gradient(#eee3d4, #e1d0b8);
}

.eq-tile { position: absolute; width: 5px; height: 5px; border-radius: 50%; background: rgba(122, 102, 81, 0.20); }
.eq-tile.t1 { left: 18%; top: 22%; }
.eq-tile.t2 { left: 87%; top: 16%; }
.eq-tile.t3 { left: 55%; top: 12%; }

.extinguisher-arena::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 38%;
  background:
    repeating-linear-gradient(98deg, transparent 0 83px, rgba(112, 82, 54, 0.14) 83px 87px),
    linear-gradient(#bd9f7d, #ac8d6e);
  border-top: 7px solid #9e7e5f;
}

.eq-fire-glow {
  position: absolute;
  left: 8%;
  top: 37%;
  width: 36%;
  height: 48%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 184, 67, 0.62), rgba(255, 114, 47, 0.17) 55%, transparent 72%);
  filter: blur(5px);
  animation: glow-pulse 1.6s ease-in-out infinite alternate;
  z-index: 1;
}

.eq-fire {
  position: absolute;
  left: 15%;
  bottom: 20%;
  width: 27%;
  height: 45%;
  z-index: 2;
}

.eq-flame {
  position: absolute;
  bottom: 16%;
  border-radius: 54% 46% 50% 50% / 68% 68% 32% 32%;
  background: linear-gradient(#ffd45a, #ff8b31 54%, #e94c28);
  transform-origin: center bottom;
  animation: flame-flicker 0.8s ease-in-out infinite alternate;
  filter: drop-shadow(0 0 15px rgba(255, 138, 52, 0.5));
}

.eq-flame.f1 { left: 37%; width: 26%; height: 55%; }
.eq-flame.f2 { left: 17%; width: 31%; height: 38%; background: linear-gradient(#ffdf68, #ff9f37 58%, #ee5c2d); animation-delay: -0.3s; }
.eq-flame.f3 { right: 15%; width: 21%; height: 43%; background: linear-gradient(#ffd45a, #ff8f2f 60%, #e44b2a); animation-delay: -0.55s; }

.eq-pan {
  position: absolute;
  left: 2%;
  right: 2%;
  bottom: 5%;
  height: 17%;
  border-radius: 5px 5px 50% 50% / 5px 5px 34% 34%;
  background: linear-gradient(#4c4d4b, #2c3030);
  box-shadow: 0 5px 0 #1f2424, 0 7px 8px rgba(40, 30, 20, 0.24);
}

.eq-smoke { position: absolute; border-radius: 50%; background: rgba(115, 115, 115, 0.24); filter: blur(4px); animation: smoke-drift 5s ease-in-out infinite alternate; }
.eq-smoke.s1 { width: 54%; height: 17%; right: 3%; bottom: 55%; }
.eq-smoke.s2 { width: 41%; height: 12%; right: -8%; bottom: 72%; animation-delay: -2s; }

.extinguisher-device {
  position: absolute;
  z-index: 4;
  right: 5%;
  bottom: 2%;
  width: 35%;
  height: 86%;
  max-width: 340px;
}

.eq-svg { width: 100%; height: 100%; overflow: visible; filter: drop-shadow(0 12px 13px rgba(37, 40, 43, 0.18)); }

.handle-pressed { transform: translateY(5px); transform-origin: 200px 70px; }

.pulled-pin {
  transform: translate(10px, -18px) rotate(26deg);
  transform-box: fill-box;
  transform-origin: center;
  animation: pin-pop 0.3s ease both;
}

.pin-hotspot {
  position: absolute;
  left: 60%;
  top: 8%;
  width: 26%;
  height: 24%;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: grab;
  z-index: 7;
  touch-action: none;
}

.pin-hotspot:active { cursor: grabbing; }
.pin-hotspot.is-pulled { pointer-events: none; }

.pin-ring {
  display: block;
  width: 46%;
  height: 46%;
  margin: 0 auto;
  border-radius: 50%;
  border: 3px solid #e3bc4a;
  background: rgba(255, 244, 184, 0.3);
  box-shadow: 0 0 0 4px rgba(255, 235, 155, 0.25);
  transition: transform 0.05s;
}

.pin-drag-hint {
  position: absolute;
  left: 50%;
  top: 72%;
  transform: translateX(-50%);
  padding: 4px 8px;
  border-radius: 99px;
  background: rgba(28, 43, 55, 0.84);
  color: #fff;
  font-size: 0.58rem;
  font-weight: 800;
  white-space: nowrap;
  animation: hint-pulse 0.9s ease-in-out infinite alternate;
}

.aim-layer {
  position: absolute;
  inset: 0;
  z-index: 8;
  touch-action: none;
}

.aim-hint-bubble {
  position: absolute;
  left: 50%;
  top: 7%;
  transform: translateX(-50%);
  padding: 8px 15px;
  border-radius: 99px;
  background: rgba(18, 40, 58, 0.86);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  white-space: nowrap;
  box-shadow: 0 5px 18px rgba(20, 30, 40, 0.2);
  backdrop-filter: blur(4px);
}

.aim-hint-bubble::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: -5px;
  width: 10px;
  height: 10px;
  transform: translateX(-50%) rotate(45deg);
  background: inherit;
}

.aim-target {
  position: absolute;
  display: grid;
  place-items: center;
  min-width: 49px;
  min-height: 49px;
  padding: 5px;
  border-radius: 50%;
  border: 2px dashed rgba(255, 255, 255, 0.85);
  background: rgba(255, 251, 238, 0.25);
  color: #fff;
  font-size: 0.55rem;
  font-weight: 800;
  text-shadow: 0 1px 3px rgba(30, 30, 30, 0.4);
  transition: 0.15s;
}

.aim-target:hover { background: rgba(255, 255, 255, 0.45); color: var(--navy); text-shadow: none; transform: scale(1.06); }
.aim-target.target-smoke { right: 29%; top: 15%; }
.aim-target.target-flame { left: 34%; top: 30%; }
.aim-target.target-base { left: 18%; top: 58%; border-color: #ffe06e; box-shadow: 0 0 0 6px rgba(255, 222, 92, 0.18); }

.drag-nozzle {
  position: absolute;
  left: 55%;
  bottom: 16%;
  width: 64px;
  height: 110px;
  transform: translate(-50%, 0) rotate(-22deg);
  animation: nozzle-float 1.4s ease-in-out infinite alternate;
  filter: drop-shadow(0 6px 7px rgba(20, 30, 40, 0.28));
  pointer-events: none;
}

.nozzle-tip { position: absolute; left: 9px; top: 0; width: 25px; height: 47px; border-radius: 8px 8px 2px 2px; background: linear-gradient(90deg, #525c5f, #9aa5a5 48%, #5d686a); }
.nozzle-hose { position: absolute; left: 27px; top: 39px; width: 18px; height: 70px; border-radius: 9px; background: #343a3d; }
.nozzle-label { position: absolute; left: 36px; top: 60px; padding: 2px 6px; border-radius: 4px; background: #f8f3e5; color: #596468; font-size: 0.5rem; font-weight: 800; }

.lever-hotspot-wrap {
  position: absolute;
  right: 4%;
  bottom: 7%;
  z-index: 8;
}

.lever-hotspot {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 112px;
  padding: 8px;
  border: 2px dashed #f1d36f;
  border-radius: 12px;
  background: rgba(255, 251, 233, 0.85);
  color: #6f5b2d;
  font-size: 0.58rem;
  font-weight: 800;
  touch-action: none;
  user-select: none;
}

.lever-hotspot.is-holding { background: #fff6cf; border-style: solid; }

.lever-handle {
  width: 52px;
  height: 13px;
  border-radius: 6px;
  background: linear-gradient(#5b6669, #30383a);
  box-shadow: 0 3px 0 #252c2e;
  transition: transform 0.08s;
}

.lever-hotspot.is-holding .lever-handle { transform: translateY(4px); }

.lever-progress {
  width: 100%;
  height: 4px;
  overflow: hidden;
  border-radius: 99px;
  background: #e3dcc8;
}

.lever-progress i { display: block; height: 100%; border-radius: inherit; background: #e3a931; transition: width 0.08s linear; }
.lever-copy { white-space: nowrap; }

.sweep-layer {
  position: absolute;
  inset: 0;
  z-index: 8;
  touch-action: none;
  cursor: crosshair;
}

.sweep-instruction {
  position: absolute;
  left: 50%;
  top: 9%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 11px 18px;
  border-radius: 14px;
  background: rgba(18, 42, 58, 0.82);
  color: #fff;
  text-align: center;
  backdrop-filter: blur(4px);
}

.sweep-instruction b { font-size: 0.76rem; }
.sweep-instruction > span { color: #bbd2dc; font-size: 0.58rem; }
.sweep-track { display: flex; gap: 4px; margin-top: 3px; }
.sweep-track i { width: 27px; height: 5px; border-radius: 99px; background: rgba(255, 255, 255, 0.25); }
.sweep-track i.done { background: #5ae0b8; }
.sweep-count { color: #ffdd7d; font-size: 0.56rem; font-weight: 800; }

.spray-stream {
  position: absolute;
  left: 12%;
  top: 43%;
  width: 42%;
  height: 26%;
  border-radius: 50%;
  background: radial-gradient(ellipse at left, rgba(255, 248, 217, 0.85), rgba(255, 243, 194, 0.18) 58%, transparent 75%);
  filter: blur(5px);
  animation: spray-pulse 0.6s ease-in-out infinite alternate;
}

.equip-success-panel {
  position: absolute;
  z-index: 10;
  left: 50%;
  top: 46%;
  transform: translate(-50%, -50%);
  width: min(360px, 82%);
  padding: 22px;
  border-radius: 18px;
  background: rgba(255, 253, 244, 0.96);
  box-shadow: var(--shadow-lg);
  text-align: center;
  animation: modal-pop 0.28s ease both;
}

.success-burst { display: block; font-size: 2.3rem; }
.equip-success-panel h2 { margin-top: 5px; font-size: 1.3rem; }
.equip-success-panel p { margin: 6px 0 13px; color: #748b95; font-size: 0.7rem; line-height: 1.55; }

.eq-scene-label {
  position: absolute;
  left: 12px;
  bottom: 10px;
  z-index: 7;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(20, 39, 55, 0.55);
  color: #eff8f8;
  font-size: 0.56rem;
  font-weight: 600;
  backdrop-filter: blur(3px);
}

.live-dot { width: 5px; height: 5px; border-radius: 50%; background: #5fe1ae; box-shadow: 0 0 0 3px rgba(95, 225, 174, 0.18); animation: soft-blink 1.6s infinite; }

.equip-scene-note {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 9px 12px;
  border-radius: 10px;
  background: #fff7e7;
  border: 1px solid #f2e3c5;
  color: #826b37;
  font-size: 0.62rem;
  line-height: 1.5;
}

.equip-scene-note svg { flex: 0 0 auto; margin-top: 1px; color: #d59b30; }

.equip-side {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 15px;
  border-radius: 18px;
  background: rgba(255, 253, 248, 0.96);
  border: 1px solid #eae1d3;
  box-shadow: var(--shadow-sm);
}

.equip-step-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 9px;
  margin-bottom: 10px;
  border-bottom: 1px solid #f0e9dc;
}

.equip-step-count { color: var(--navy); font-size: 0.62rem; font-weight: 900; letter-spacing: 0.05em; }
.equip-mode { padding: 2px 7px; border-radius: 5px; background: #e8f7f2; color: #16866d; font-size: 0.52rem; font-weight: 800; }

.safety-check-box { display: flex; flex-direction: column; }

.check-icon {
  width: 45px;
  height: 45px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  background: #fff5dc;
  font-size: 1.5rem;
  margin-bottom: 8px;
}

.safety-check-box h3 { font-size: 1.08rem; }
.safety-check-box > p { margin: 5px 0 11px; color: #6e8593; font-size: 0.68rem; line-height: 1.6; }

.check-choices { display: flex; flex-direction: column; gap: 6px; }

.check-choice {
  width: 100%;
  padding: 9px 11px;
  border: 1.5px solid #e8e1d4;
  border-radius: 10px;
  background: #fffefa;
  color: #4d6878;
  font-size: 0.66rem;
  line-height: 1.45;
  text-align: left;
  transition: 0.13s;
}

.check-choice:hover:not(:disabled) { border-color: #bfdcd2; background: #f9fffc; }
.check-choice.is-correct { border-color: #4bc59d; background: #eefbf6; color: #1c725d; }
.check-choice.is-wrong { border-color: #ed8f7b; background: #fff4f0; color: #a4523e; }

.check-feedback { margin-top: 9px; padding: 9px 10px; border-radius: 9px; background: #fff5ef; border: 1px solid #f5d9ce; }
.check-feedback b { display: block; color: #9e4e39; font-size: 0.67rem; }
.check-feedback p { margin-top: 2px; color: #91746b; font-size: 0.61rem; line-height: 1.5; }
.check-feedback button { margin-top: 6px; padding: 4px 8px; border: 0; border-radius: 6px; background: #fff; color: #a75b46; font-size: 0.58rem; font-weight: 800; }

.current-instruction {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding-bottom: 11px;
}

.instruction-icon {
  width: 43px;
  height: 43px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #fff2d5;
  font-size: 1.25rem;
}

.instruction-icon.done { background: #e2f8ef; color: #16876b; font-size: 1.1rem; }
.current-instruction .eyebrow { font-size: 0.52rem; }
.current-instruction h2 { font-size: 1.06rem; margin: 1px 0 3px; }
.current-instruction p { color: #728995; font-size: 0.64rem; line-height: 1.5; }

.equip-photo-guide {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  margin-bottom: 9px;
  border-radius: 11px;
  background: #f8f8f1;
  border: 1px solid #eeece3;
}

.guide-visual { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }
.guide-ext, .guide-fire { font-size: 1.2rem; }
.guide-arrow { color: #a6a494; font-size: 0.8rem; }
.equip-photo-guide > span { color: #6e8290; font-size: 0.62rem; line-height: 1.45; }
.equip-photo-guide b { color: #ca5e3b; }

.equip-continuous { display: flex; flex-direction: column; gap: 6px; margin-bottom: 9px; }

.equip-fact {
  padding: 8px 10px;
  border-radius: 8px;
  background: #f4fbf8;
  border-left: 3px solid #50c09a;
}

.equip-fact.subtle { background: #fff8eb; border-color: #ecc56d; }
.equip-fact b { display: block; color: #3c7467; font-size: 0.6rem; }
.equip-fact.subtle b { color: #8d6c28; }
.equip-fact p { margin-top: 1px; color: #7b9189; font-size: 0.57rem; line-height: 1.5; }

.equip-side-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: auto; padding-top: 10px; border-top: 1px solid #f2ece2; }
.equip-side-actions .game-btn { min-height: 30px; padding: 0 9px; font-size: 0.58rem; }

/* ============================================================
   AED GAME
   ============================================================ */
.aed-game { min-height: 100svh; }

.aed-top-progress { display: flex; align-items: center; gap: 3px; justify-content: center; flex-wrap: wrap; }

.aed-top-progress span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border-radius: 5px;
  color: #99a7ac;
  font-size: 0.55rem;
  font-weight: 700;
  white-space: nowrap;
}

.aed-top-progress span i {
  width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eae8de;
  color: #99a39f;
  font-size: 0.48rem;
  font-style: normal;
  font-weight: 900;
}

.aed-top-progress span.active { background: #fff3e6; color: #bd6239; }
.aed-top-progress span.active i { background: var(--primary); color: #fff; }
.aed-top-progress span.done { color: #2c9174; }
.aed-top-progress span.done i { background: #d9f5ea; color: #11866a; }

.aed-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.72fr) minmax(330px, 1fr);
  gap: 12px;
  align-items: stretch;
}

.aed-scene {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 540px;
  overflow: hidden;
  border-radius: 20px;
  background:
    radial-gradient(420px 240px at 24% 10%, rgba(213, 245, 248, 0.72), transparent 65%),
    linear-gradient(#e7f1ef 0 64%, #c4d6ce 64% 100%);
  box-shadow: 0 13px 34px rgba(27, 54, 80, 0.15);
  border: 1px solid #dce5df;
}

.aed-scene-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 11px 14px;
  z-index: 3;
}

.aed-location { color: #829b98; font-size: 0.58rem; font-weight: 600; }

.aed-scene-body {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  padding: 4px 16px 25px;
  position: relative;
}

.aed-patient-area {
  position: relative;
  flex: 1;
  align-self: stretch;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
}

.patient-floor {
  position: absolute;
  left: 2%;
  right: 2%;
  bottom: 5%;
  height: 18%;
  border-radius: 50%;
  background: rgba(72, 101, 92, 0.14);
  filter: blur(4px);
}

.patient-torso-wrap {
  position: relative;
  width: min(340px, 92%);
  max-height: 100%;
  z-index: 2;
}

.patient-svg { width: 100%; height: auto; overflow: visible; }

.patient-label {
  position: absolute;
  left: 50%;
  bottom: -18px;
  transform: translateX(-50%);
  padding: 3px 8px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.8);
  color: #708b84;
  font-size: 0.51rem;
  white-space: nowrap;
}

.aed-zone { cursor: pointer; }
.aed-zone.selectable:hover circle { fill: rgba(255, 215, 86, 0.45); }
.zone-center, .zone-abdomen { cursor: default; }

.aed-device-area {
  flex: 0 0 42%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  position: relative;
  align-self: stretch;
}

.aed-device {
  position: relative;
  width: 152px;
  height: 200px;
  border-radius: 12px 12px 18px 18px;
  background: linear-gradient(145deg, #f6c543, #e9a51d);
  box-shadow: 0 12px 22px rgba(82, 67, 25, 0.25), inset 0 0 0 2px rgba(255, 255, 255, 0.24);
  border: 2px solid #d49417;
  transition: box-shadow 0.2s;
}

.aed-device.is-on { box-shadow: 0 12px 22px rgba(82, 67, 25, 0.25), 0 0 0 5px rgba(92, 226, 188, 0.13); }

.aed-handle {
  position: absolute;
  left: 50%;
  top: -15px;
  transform: translateX(-50%);
  width: 67px;
  height: 19px;
  border-radius: 9px 9px 3px 3px;
  background: #b77b1d;
  box-shadow: inset 0 -3px 0 #925f12;
}

.aed-screen {
  position: absolute;
  left: 13px;
  right: 13px;
  top: 16px;
  height: 114px;
  overflow: hidden;
  border-radius: 8px;
  background: #182a35;
  border: 3px solid #42433a;
  padding: 8px;
}

.aed-logo {
  display: flex;
  align-items: center;
  gap: 4px;
  color: #ffd65c;
  font-family: var(--display);
  font-size: 0.8rem;
  line-height: 1;
}

.aed-logo span { font-size: 0.65rem; }

.aed-off {
  position: absolute;
  left: 50%;
  top: 56%;
  transform: translate(-50%, -50%);
  color: #56707a;
  font-family: var(--display);
  font-size: 1.35rem;
  font-weight: 400;
}

.aed-wave {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 3px;
  height: 48px;
  margin-top: 8px;
}

.aed-wave > span { width: 4px; height: 18%; border-radius: 3px; background: #5be2ba; animation: free-wave 0.8s ease-in-out infinite alternate; }
.aed-wave > span:nth-child(2) { animation-delay: -0.2s; height: 55%; }
.aed-wave > span:nth-child(3) { animation-delay: -0.4s; height: 100%; }
.aed-wave > span:nth-child(4) { animation-delay: -0.1s; height: 66%; }
.aed-wave > span:nth-child(5) { animation-delay: -0.3s; height: 34%; }
.aed-wave b { position: absolute; left: 0; right: 0; bottom: 6px; color: #89e8cd; font-size: 0.48rem; text-align: center; font-weight: 700; }
.aed-wave.is-analyzing > span { background: #ffd65c; animation-duration: 0.35s; }

.aed-power {
  position: absolute;
  left: 10px;
  bottom: 10px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 6px;
  border: 0;
  border-radius: 4px;
  background: #45606a;
  color: #d6eeea;
  font-size: 0.45rem;
  font-weight: 800;
}

.aed-power i { width: 6px; height: 6px; border-radius: 50%; background: #688187; box-shadow: 0 0 0 2px rgba(100, 140, 140, 0.15); }
.aed-power.on i { background: #55e3b7; box-shadow: 0 0 6px #55e3b7; }
.aed-power:disabled { opacity: 0.8; }

.aed-shock-btn {
  position: absolute;
  right: 9px;
  bottom: 8px;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 5px 7px;
  border: 0;
  border-radius: 5px;
  background: #4a6a70;
  color: #c6d7d3;
  font-size: 0.48rem;
  font-weight: 900;
}

.aed-shock-btn.ready { background: #ed5a40; color: #fff; animation: soft-blink 0.8s infinite; box-shadow: 0 0 12px rgba(237, 90, 64, 0.55); }
.aed-shock-btn.pressed { background: #7e2c23; animation: none; }

.aed-speaker { position: absolute; left: 22px; right: 22px; bottom: 42px; display: flex; gap: 3px; }
.aed-speaker i { flex: 1; height: 3px; border-radius: 99px; background: rgba(90, 68, 14, 0.32); }

.aed-brand {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 15px;
  color: #6c5210;
  font-family: var(--display);
  font-size: 0.56rem;
  text-align: center;
  letter-spacing: 0.04em;
}

.pad-tray {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex-wrap: wrap;
  padding: 7px 9px;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.72);
