.pad-shape { width: 31px; height: 36px; border-radius: 5px; background: linear-gradient(145deg, #fbf7e5, #e7ddbf); border: 2px solid #d4c9a9; position: relative; }
.pad-shape::before { content: ''; position: absolute; inset: 9px 8px; border-radius: 50%; background: #e65c4a; }
.pad-shape::after { content: '+'; position: absolute; inset: 0; display: grid; place-items: center; color: #fff; font-size: 0.8rem; font-weight: 900; line-height: 1; }
