}

.clear-warning, .shock-warning {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 9px;
  border-radius: 8px;
  background: rgba(255, 250, 234, 0.94);
  border: 1px solid #f1dfb0;
  color: #7d682f;
  font-size: 0.56rem;
  line-height: 1.4;
}

.shock-warning { background: rgba(255, 241, 235, 0.96); border-color: #f5cab9; color: #a14c32; }
.clear-warning .game-btn, .shock-controls .game-btn { min-height: 34px; padding: 0 12px; font-size: 0.62rem; }

.analyze-overlay {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 10px;
  border-radius: 11px;
  background: rgba(20, 39, 46, 0.82);
  color: #e9fffb;
  max-width: 250px;
  backdrop-filter: blur(3px);
}

.analyze-scan { display: flex; gap: 3px; margin-bottom: 3px; }
.analyze-scan span { width: 5px; height: 22px; border-radius: 3px; background: #62e1bd; animation: free-wave 0.5s ease-in-out infinite alternate; }
.analyze-scan span:nth-child(2) { animation-delay: -0.18s; }
.analyze-scan span:nth-child(3) { animation-delay: -0.36s; }
.analyze-overlay b { font-size: 0.64rem; }
.analyze-overlay p { color: #a5c8c1; font-size: 0.52rem; }

.cpr-resume { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 12px 15px; border-radius: 12px; background: rgba(255, 248, 236, 0.96); border: 1px solid #f0ddb7; text-align: center; }
.cpr-beat { display: flex; gap: 3px; }
.cpr-beat span { width: 22px; height: 22px; display: grid; place-items: center; border-radius: 50%; background: #ef6d55; color: #fff; font-size: 0.55rem; font-weight: 900; animation: cpr-beat 0.55s ease-in-out infinite; }
.cpr-beat span:nth-child(2) { animation-delay: 0.13s; }
.cpr-beat span:nth-child(3) { animation-delay: 0.26s; }
.cpr-resume b { color: #a85039; font-size: 0.7rem; }
.cpr-resume p { color: #9b8377; font-size: 0.55rem; }

.aed-done-badge {
  position: absolute;
  left: 50%;
  bottom: 4%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 16px;
  border-radius: 12px;
  background: rgba(255, 252, 240, 0.95);
  border: 1px solid #d8f0e4;
  box-shadow: 0 8px 20px rgba(20, 50, 60, 0.12);
  z-index: 5;
}

.aed-done-badge > span { width: 25px; height: 25px; display: grid; place-items: center; border-radius: 50%; background: #44c49b; color: #fff; font-size: 0.7rem; font-weight: 900; }
.aed-done-badge b { color: #217661; font-size: 0.65rem; }
.aed-done-badge small { color: #8daaa1; font-size: 0.5rem; }

.aed-dialogue {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 14px 13px;
  padding: 9px 12px;
  border-radius: 12px;
  background: rgba(24, 48, 57, 0.9);
  color: #edfffb;
  box-shadow: 0 6px 16px rgba(20, 40, 45, 0.12);
}

.aed-voice-icon { width: 27px; height: 27px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 7px; background: rgba(92, 226, 188, 0.16); font-size: 0.85rem; }
.aed-dialogue > div:not(.voice-wave) { flex: 1; min-width: 0; }
.aed-dialogue span { display: block; color: #76c8b5; font-size: 0.49rem; font-weight: 700; }
.aed-dialogue p { color: #e4f7f2; font-size: 0.64rem; line-height: 1.45; }
.voice-wave { display: flex; align-items: center; gap: 2px; height: 20px; flex: 0 0 auto; }
.voice-wave i { width: 3px; height: 8px; border-radius: 3px; background: #5de2b9; animation: free-wave 0.7s ease-in-out infinite alternate; }
.voice-wave i:nth-child(2) { animation-delay: -0.2s; height: 15px; }
.voice-wave i:nth-child(3) { animation-delay: -0.4s; height: 11px; }
.voice-wave i:nth-child(4) { animation-delay: -0.1s; height: 6px; }

.aed-side {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding: 16px;
  border-radius: 18px;
  background: rgba(255, 253, 248, 0.96);
  border: 1px solid #eae1d3;
  box-shadow: var(--shadow-sm);
}

.aed-check .eyebrow { font-size: 0.52rem; }
.aed-check h2 { margin: 3px 0 6px; font-size: 1.14rem; }
.aed-check > p { color: #6e8593; font-size: 0.69rem; line-height: 1.6; }
.aed-check-choices { display: flex; flex-direction: column; gap: 6px; margin-top: 11px; }
.aed-check-choices button { width: 100%; padding: 9px 10px; border: 1.5px solid #e8e1d4; border-radius: 9px; background: #fffefa; color: #4f6978; font-size: 0.64rem; line-height: 1.5; text-align: left; }
.aed-check-choices button:hover:not(:disabled) { border-color: #b9dcd2; background: #f8fffc; }
.aed-check-choices button.is-correct { border-color: #46bd95; background: #edfbf6; color: #1b705b; }
.aed-check-choices button.is-wrong { border-color: #ef8a74; background: #fff4ef; color: #a54c37; }
.aed-check-feedback { margin-top: 9px; padding: 9px 10px; border-radius: 8px; background: #fff6f1; border: 1px solid #f3d5c8; }
.aed-check-feedback p { color: #8e6a5e; font-size: 0.61rem; line-height: 1.55; }
.aed-check-feedback button { margin-top: 5px; padding: 4px 8px; border: 0; border-radius: 5px; background: #fff; color: #a35944; font-size: 0.56rem; font-weight: 800; }

.aed-side-title .eyebrow { font-size: 0.52rem; }
.aed-side-title h2 { font-size: 1.14rem; margin: 2px 0 4px; }
.aed-side-title p { color: #728996; font-size: 0.65rem; line-height: 1.55; }

.aed-pad-diagram {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 12px;
  padding: 9px 10px;
  border-radius: 10px;
  background: #faf8f0;
  border: 1px solid #f0ece2;
}

.diagram-body { position: relative; width: 45px; height: 56px; flex: 0 0 auto; }
.diagram-head { position: absolute; left: 50%; top: 0; transform: translateX(-50%); width: 17px; height: 17px; border-radius: 50%; background: #f1c39e; }
.diagram-chest { position: absolute; left: 50%; top: 17px; transform: translateX(-50%); width: 31px; height: 38px; border-radius: 8px 8px 4px 4px; background: #f5d2b2; }
.diagram-pad { position: absolute; width: 11px; height: 15px; border-radius: 3px; background: #faf6e3; border: 1px solid #d6cbaa; }
.diagram-pad.right { left: 30px; top: 20px; transform: rotate(-13deg); }
.diagram-pad.left { left: 5px; top: 32px; transform: rotate(12deg); }
.diagram-pad i { display: grid; place-items: center; height: 100%; color: #e45e4d; font-size: 0.46rem; font-weight: 900; font-style: normal; }
.aed-pad-diagram b { color: #5c7580; font-size: 0.62rem; }
.aed-pad-diagram p { color: #93a1a5; font-size: 0.56rem; line-height: 1.4; margin-top: 1px; }

.aed-reminders { display: flex; flex-direction: column; gap: 5px; margin-top: 10px; }
.aed-reminders > div { display: flex; align-items: flex-start; gap: 6px; }
.aed-reminders span { width: 16px; height: 16px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%; background: #edf2ea; color: #7f9589; font-size: 0.48rem; font-weight: 900; }
.aed-reminders p { color: #7e908f; font-size: 0.6rem; line-height: 1.45; }

.aed-finish-box { margin-top: auto; padding-top: 12px; }
.aed-finish-stars { color: #f1b93d; font-size: 1.05rem; letter-spacing: 0.15em; text-align: center; margin-bottom: 5px; }

.aed-side-bottom { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; padding-top: 11px; border-top: 1px solid #f1ece2; }
.aed-side-bottom > span { display: flex; align-items: flex-start; gap: 4px; color: #98a5a9; font-size: 0.53rem; line-height: 1.4; max-width: 74%; }
.aed-side-bottom svg { flex: 0 0 auto; margin-top: 1px; color: #e46e82; }

.compression-wave { position: absolute; z-index: 3; bottom: 20%; left: 50%; transform: translateX(-50%); display: flex; align-items: flex-end; gap: 4px; }
.compression-wave span { position: absolute; top: -12px; left: 50%; transform: translateX(-50%); color: #288f75; font-size: 0.46rem; font-weight: 800; white-space: nowrap; }
.compression-wave i { width: 4px; height: 12px; border-radius: 3px; background: #4bc39e; animation: free-wave 0.5s ease-in-out infinite alternate; }
.compression-wave i:nth-child(2) { animation-delay: -0.1s; height: 21px; }
.compression-wave i:nth-child(3) { animation-delay: -0.2s; height: 29px; }
.compression-wave i:nth-child(4) { animation-delay: -0.3s; height: 19px; }
.compression-wave i:nth-child(5) { animation-delay: -0.4s; height: 9px; }

.shock-flash { animation: shock-flash 0.55s ease; }
.patient-torso-wrap.is-analyzing .patient-svg { filter: drop-shadow(0 0 12px rgba(91, 226, 190, 0.55)); }
.analysis-ring { animation: spin 5s linear infinite; transform-origin: 180px 205px; }
.shock-target { animation: soft-blink 0.7s infinite; }
.placed-pad { animation: pad-snap 0.25s ease both; }

/* ============================================================
   CPR GAME
   ============================================================ */
.cpr-game { min-height: 100svh; }

.cpr-top-status { display: flex; align-items: center; gap: 6px; }
.bpm-pill, .compression-pill { padding: 5px 8px; border-radius: 6px; background: #f4f1e8; color: #7c8d91; font-size: 0.56rem; font-weight: 700; white-space: nowrap; }
.bpm-pill b { color: #288b75; font-size: 0.66rem; }
.compression-pill b { color: var(--navy); }

.cpr-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.72fr) minmax(300px, 0.9fr);
  gap: 12px;
}

.cpr-stage {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  border-radius: 20px;
  background: #e9e4d8;
  box-shadow: 0 13px 34px rgba(27, 54, 80, 0.15);
  border: 1px solid #e2d8c8;
}

.cpr-stage-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 13px; }
.cpr-beat-label { display: flex; align-items: center; gap: 4px; color: #8b9b96; font-size: 0.5rem; font-weight: 800; letter-spacing: 0.06em; }
.cpr-beat-label i { width: 6px; height: 6px; border-radius: 50%; background: #cfd3c9; }
.cpr-beat-label i.on { background: #3bc39a; box-shadow: 0 0 0 3px rgba(59, 195, 154, 0.16); animation: soft-blink 1s infinite; }

.cpr-scene {
  position: relative;
  flex: 1;
  min-height: 430px;
  overflow: hidden;
  background:
    radial-gradient(400px 250px at 50% 48%, rgba(255, 255, 255, 0.58), transparent 70%),
    linear-gradient(#e9f0e9 0 66%, #cbd4c7 66% 100%);
}

.cpr-floor { position: absolute; left: 5%; right: 5%; bottom: 8%; height: 21%; border-radius: 50%; background: rgba(74, 99, 86, 0.13); filter: blur(5px); }

.cpr-patient { position: absolute; left: 50%; top: 51%; transform: translate(-50%, -50%); width: 250px; height: 250px; }
.cpr-head { position: absolute; left: 50%; top: 2%; transform: translateX(-50%); width: 45px; height: 48px; border-radius: 48% 48% 46% 46%; background: #f0c4a0; box-shadow: inset 0 6px 0 #5a4136; }
.cpr-body { position: absolute; left: 50%; top: 21%; transform: translateX(-50%); width: 78px; height: 145px; border-radius: 22px 22px 16px 16px; background: #e6d4b9; box-shadow: inset 0 0 0 2px rgba(186, 162, 130, 0.22); }
.cpr-arms { position: absolute; left: 50%; top: 32%; transform: translateX(-50%); width: 175px; display: flex; justify-content: space-between; }
.cpr-arms span { width: 48px; height: 17px; border-radius: 99px; background: #ecc29f; }
.cpr-arms span:first-child { transform: rotate(-17deg); }
.cpr-arms span:last-child { transform: rotate(17deg); }
.cpr-hands { position: absolute; left: 50%; top: 34%; transform: translateX(-50%); width: 58px; height: 48px; z-index: 3; }
.cpr-hands .hand { position: absolute; top: 15px; width: 35px; height: 20px; border-radius: 50% 50% 45% 45%; background: #eab88f; box-shadow: inset 0 -3px 0 rgba(180, 126, 90, 0.25); }
.cpr-hands .hand-left { left: 0; transform: rotate(-13deg); }
.cpr-hands .hand-right { right: 0; transform: rotate(13deg); }
.cpr-hands.is-active { animation: cpr-press 0.55s ease-in-out infinite; }
.compression-flash { position: absolute; inset: 3px 4px auto; height: 12px; border-radius: 50%; background: rgba(255, 225, 130, 0.45); opacity: 0; }
.cpr-hands.is-active .compression-flash { animation: compress-flash 0.55s ease-in-out infinite; }
.cpr-chest-target { position: absolute; left: 50%; top: 31%; transform: translateX(-50%); z-index: 2; text-align: center; }
.cpr-chest-target i { display: block; width: 21px; height: 21px; margin: 0 auto 2px; border-radius: 50%; border: 2px dashed #a1a78f; }
.cpr-chest-target b { color: #8d9785; font-size: 0.44rem; font-weight: 700; }

.cpr-ring-wrap { position: absolute; right: 7%; top: 50%; transform: translateY(-50%); width: 200px; height: 200px; display: grid; place-items: center; }
.cpr-beat-ring { position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none; }
.cpr-beat-ring span { position: absolute; width: 100%; height: 100%; border-radius: 50%; border: 2px solid rgba(60, 195, 155, 0.35); opacity: 0.25; }
.cpr-beat-ring span:nth-child(2) { width: 78%; height: 78%; border-color: rgba(60, 195, 155, 0.48); }
.cpr-beat-ring span:nth-child(3) { width: 56%; height: 56%; border-color: rgba(60, 195, 155, 0.68); background: rgba(80, 214, 174, 0.08); }
.cpr-beat-ring.is-beating { animation: beat-ring 0.55s ease-out; }

.cpr-tap-zone { position: relative; z-index: 4; }
.cpr-tap-button { width: 112px; height: 112px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 0; border-radius: 50%; border: 5px solid rgba(255, 255, 255, 0.8); background: linear-gradient(145deg, #46c9a5, #27a683); color: #fff; box-shadow: 0 11px 25px rgba(30, 130, 105, 0.27), inset 0 0 0 2px rgba(255, 255, 255, 0.17); touch-action: manipulation; }
.cpr-tap-button:active { transform: scale(0.94); }
.tap-heart { font-size: 1.1rem; line-height: 1; }
.cpr-tap-button b { font-family: var(--display); font-size: 1.15rem; font-weight: 400; line-height: 1.2; }
.cpr-tap-button small { color: #c6f5e8; font-size: 0.45rem; font-weight: 800; letter-spacing: 0.06em; }

.cpr-tap-zone.rating-perfect .cpr-tap-button { box-shadow: 0 0 0 8px rgba(80, 223, 177, 0.2), 0 11px 25px rgba(30, 130, 105, 0.27); }
.cpr-tap-zone.rating-late .cpr-tap-button { box-shadow: 0 0 0 7px rgba(243, 177, 63, 0.2), 0 11px 25px rgba(30, 130, 105, 0.27); }
.cpr-tap-zone.rating-miss .cpr-tap-button { box-shadow: 0 0 0 7px rgba(232, 101, 82, 0.18), 0 11px 25px rgba(30, 130, 105, 0.27); }

.rating-float { position: absolute; left: 50%; bottom: -20px; transform: translateX(-50%); font-family: var(--display); font-size: 0.95rem; color: #2ca586; white-space: nowrap; animation: rating-pop 0.8s ease both; }
.rating-float.rating-late { color: #d49a29; }
.rating-float.rating-miss { color: #df6650; }

.cpr-intro-card, .cpr-done-card, .cpr-countdown { position: absolute; z-index: 6; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(350px, 82%); padding: 22px 24px; border-radius: 20px; background: rgba(255, 252, 244, 0.96); box-shadow: var(--shadow-lg); text-align: center; animation: modal-pop 0.25s ease both; }
.intro-badge { display: inline-block; padding: 3px 8px; border-radius: 5px; background: #e1f6ef; color: #16866e; font-size: 0.52rem; font-weight: 900; letter-spacing: 0.08em; }
.cpr-intro-card h2 { margin: 7px 0 6px; font-size: 1.48rem; line-height: 1.25; }
.cpr-intro-card > p { color: #6f8792; font-size: 0.68rem; line-height: 1.6; }
.cpr-intro-facts { display: flex; justify-content: center; gap: 5px; margin: 11px 0 13px; }
.cpr-intro-facts span { display: flex; align-items: center; gap: 3px; padding: 4px 7px; border-radius: 6px; background: #f5f3ea; color: #74867f; font-size: 0.55rem; font-weight: 700; }
.cpr-intro-facts i { width: 14px; height: 14px; display: grid; place-items: center; border-radius: 50%; background: #e0eee8; color: #5b8c7f; font-size: 0.45rem; font-style: normal; font-weight: 900; }
.cpr-intro-card small { display: block; margin-top: 8px; color: #9ba7a7; font-size: 0.51rem; }

.cpr-countdown { background: rgba(21, 62, 72, 0.92); color: #fff; box-shadow: 0 20px 50px rgba(15, 50, 60, 0.3); }
.cpr-countdown span { display: block; font-family: var(--display); font-size: 4rem; line-height: 1; color: #8df2d1; }
.cpr-countdown p { margin-top: 5px; color: #c9e3de; font-size: 0.66rem; }

.cpr-done-card .done-burst { display: block; font-size: 2.2rem; }
.cpr-done-card h2 { margin-top: 4px; font-size: 1.35rem; }
.cpr-done-card p { color: #768b8e; font-size: 0.66rem; margin: 3px 0 6px; }
.cpr-done-score { font-family: var(--display); color: #168f76; font-size: 2rem; line-height: 1.1; }
.cpr-done-score small { color: #9bada9; font-family: var(--body); font-size: 0.67rem; }
.cpr-done-card .game-btn { margin-top: 10px; }

.cpr-bottom-info { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 8px 13px; color: #879a99; font-size: 0.56rem; }
.cpr-bottom-info > span:first-child { display: flex; align-items: flex-start; gap: 4px; }
.cpr-bottom-info svg { flex: 0 0 auto; color: #85a39c; }
.cpr-source { color: #9dabaa; font-size: 0.5rem; white-space: nowrap; }

.cpr-side { display: flex; flex-direction: column; min-width: 0; padding: 16px; border-radius: 18px; background: rgba(255, 253, 248, 0.96); border: 1px solid #eae1d3; box-shadow: var(--shadow-sm); }
.cpr-side-head .eyebrow { font-size: 0.53rem; }
.cpr-side-head h2 { font-size: 1.14rem; margin: 2px 0 4px; }
.cpr-side-head p { color: #738995; font-size: 0.64rem; line-height: 1.55; }

.cpr-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin-top: 11px; }
.cpr-stats > div { display: flex; flex-direction: column; align-items: center; padding: 6px 4px; border-radius: 7px; background: #f7f6ef; }
.cpr-stats span { color: #98a6a6; font-size: 0.52rem; }
.cpr-stats b { color: var(--navy); font-family: var(--display); font-size: 1rem; font-weight: 400; }

.cpr-beat-visual { display: flex; align-items: center; gap: 10px; margin-top: 10px; padding: 9px 10px; border-radius: 10px; background: #f4faf7; border: 1px solid #e3f0e9; }
.beat-circle { position: relative; width: 46px; height: 46px; flex: 0 0 auto; display: grid; place-items: center; }
.beat-circle i { position: absolute; border-radius: 50%; }
.beat-circle i:nth-child(1) { inset: 0; border: 2px solid #a9ddcd; }
.beat-circle i:nth-child(2) { inset: 7px; border: 2px solid #73c8b0; }
.beat-circle i:nth-child(3) { inset: 14px; background: #48bd9b; animation: heartbeat 0.55s ease-in-out infinite; }
.beat-circle b { position: relative; z-index: 2; color: #fff; font-size: 0.48rem; font-weight: 900; }
.cpr-beat-visual > span { color: #879a94; font-size: 0.56rem; line-height: 1.45; }
.cpr-beat-visual > span b { color: #317d6b; }

.compression-progress { margin-top: 11px; }
.compression-progress-head { display: flex; justify-content: space-between; color: #7d9294; font-size: 0.57rem; font-weight: 700; margin-bottom: 5px; }
.compression-progress-head b { color: var(--navy); }
.compression-dots { display: flex; flex-wrap: wrap; gap: 3px; }
.compression-dots i { width: 8px; height: 8px; border-radius: 50%; background: #edeee7; }
.compression-dots i.filled { background: #d6ddd6; }
.compression-dots i.r-perfect { background: #3ec198; }
.compression-dots i.r-good { background: #7dcfae; }
.compression-dots i.r-late { background: #efbd56; }
.compression-dots i.r-miss { background: #e78370; }

.cpr-ratings { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.cpr-ratings span { display: inline-flex; align-items: center; gap: 3px; color: #8b9a99; font-size: 0.5rem; }
.cpr-ratings i { width: 5px; height: 5px; border-radius: 50%; }
.rating-perfect i { background: #3ec198; }
.rating-good i { background: #7dcfae; }
.rating-late i { background: #efbd56; }
.rating-miss i { background: #e78370; }

.cpr-tips { display: flex; flex-direction: column; gap: 5px; margin-top: 10px; }
.cpr-tips > div { display: flex; align-items: flex-start; gap: 6px; }
.cpr-tips span { flex: 0 0 auto; font-size: 0.72rem; }
.cpr-tips p { color: #7f9191; font-size: 0.58rem; line-height: 1.5; }
.cpr-tips b { color: #4f7e70; }

.cpr-side-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; padding-top: 10px; border-top: 1px solid #f1ece2; }
.cpr-side-foot span { color: #9ba8a7; font-size: 0.5rem; line-height: 1.4; max-width: 76%; }
.cpr-side-foot button { padding: 4px 6px; border: 0; background: none; color: #5b8d80; font-size: 0.54rem; font-weight: 700; text-decoration: underline; }

files.patch:
Index: src/index.css
===================================================================
--- src/index.css
+++ src/index.css
@@ -7630,5 +7630,1203 @@
 }

 .hazard-side-tip svg { flex: 0 0 auto; margin-top: 1px; color: #7fa8b8; }

+/* ============================================================
+   EXTINGUISHER GAME
+   ============================================================ */
+.extinguisher-game { min-height: 100svh; }

+.equip-progress-steps {
+  display: flex;
+  align-items: center;
+  gap: 2px;
+  flex-wrap: wrap;
+  justify-content: center;
+}
+
+.equip-progress-steps span {
+  display: inline-flex;
+  align-items: center;
+  gap: 4px;
+  padding: 4px 7px;
+  border-radius: 6px;
+  color: #9aa8ad;
+  font-size: 0.57rem;
+  font-weight: 700;
+  white-space: nowrap;
+}
+
+.equip-progress-steps span i {
+  width: 16px;
+  height: 16px;
+  display: grid;
+  place-items: center;
+  border-radius: 50%;
+  background: #eceae1;
+  color: #9ba5a4;
+  font-size: 0.5rem;
+  font-style: normal;
+  font-weight: 900;
+}
+
+.equip-progress-steps span.active { background: #fff1e8; color: #cc5b3b; }
+.equip-progress-steps span.active i { background: var(--primary); color: #fff; }
+.equip-progress-steps span.done { color: #3a9379; }
+.equip-progress-steps span.done i { background: #d7f4e9; color: #198b6d; }
+
+.extinguisher-layout {
+  flex: 1;
+  display: grid;
+  grid-template-columns: minmax(0, 1.8fr) minmax(330px, 1fr);
+  gap: 12px;
+  align-items: stretch;
+}
+
+.extinguisher-arena-wrap {
+  display: flex;
+  flex-direction: column;
+  gap: 8px;
+  min-width: 0;
+}
+
+.extinguisher-arena {
+  position: relative;
+  flex: 1;
+  min-height: 490px;
+  overflow: hidden;
+  border-radius: 20px;
+  background: linear-gradient(#e8dfd0 0 62%, #c9b292 62% 100%);
+  box-shadow: 0 13px 34px rgba(27, 54, 80, 0.16);
+  isolation: isolate;
+}
+
+.extinguisher-wall {
+  position: absolute;
+  inset: 0 0 38%;
+  background:
+    repeating-linear-gradient(90deg, transparent 0 70px, rgba(154, 130, 102, 0.16) 70px 73px),
+    repeating-linear-gradient(0deg, transparent 0 56px, rgba(154, 130, 102, 0.13) 56px 59px),
+    linear-gradient(#eee3d4, #e1d0b8);
+}
+
+.eq-tile { position: absolute; width: 5px; height: 5px; border-radius: 50%; background: rgba(122, 102, 81, 0.20); }
+.eq-tile.t1 { left: 18%; top: 22%; }
+.eq-tile.t2 { left: 87%; top: 16%; }
+.eq-tile.t3 { left: 55%; top: 12%; }
+
+.extinguisher-arena::after {
+  content: '';
+  position: absolute;
+  left: 0;
+  right: 0;
+  bottom: 0;
+  height: 38%;
+  background:
+    repeating-linear-gradient(98deg, transparent 0 83px, rgba(112, 82, 54, 0.14) 83px 87px),
+    linear-gradient(#bd9f7d, #ac8d6e);
+  border-top: 7px solid #9e7e5f;
+}
+
+.eq-fire-glow {
+  position: absolute;
+  left: 8%;
+  top: 37%;
+  width: 36%;
+  height: 48%;
+  border-radius: 50%;
+  background: radial-gradient(circle, rgba(255, 184, 67, 0.62), rgba(255, 114, 47, 0.17) 55%, transparent 72%);
+  filter: blur(5px);
+  animation: glow-pulse 1.6s ease-in-out infinite alternate;
+  z-index: 1;
+}
+
+.eq-fire {
+  position: absolute;
+  left: 15%;
+  bottom: 20%;
+  width: 27%;
+  height: 45%;
+  z-index: 2;
+}
+
+.eq-flame {
+  position: absolute;
+  bottom: 16%;
+  border-radius: 54% 46% 50% 50% / 68% 68% 32% 32%;
+  background: linear-gradient(#ffd45a, #ff8b31 54%, #e94c28);
+  transform-origin: center bottom;
+  animation: flame-flicker 0.8s ease-in-out infinite alternate;
+  filter: drop-shadow(0 0 15px rgba(255, 138, 52, 0.5));
+}
+
+.eq-flame.f1 { left: 37%; width: 26%; height: 55%; }
+.eq-flame.f2 { left: 17%; width: 31%; height: 38%; background: linear-gradient(#ffdf68, #ff9f37 58%, #ee5c2d); animation-delay: -0.3s; }
+.eq-flame.f3 { right: 15%; width: 21%; height: 43%; background: linear-gradient(#ffd45a, #ff8f2f 60%, #e44b2a); animation-delay: -0.55s; }
+
+.eq-pan {
+  position: absolute;
+  left: 2%;
+  right: 2%;
+  bottom: 5%;
+  height: 17%;
+  border-radius: 5px 5px 50% 50% / 5px 5px 34% 34%;
+  background: linear-gradient(#4c4d4b, #2c3030);
+  box-shadow: 0 5px 0 #1f2424, 0 7px 8px rgba(40, 30, 20, 0.24);
+}
+
+.eq-smoke { position: absolute; border-radius: 50%; background: rgba(115, 115, 115, 0.24); filter: blur(4px); animation: smoke-drift 5s ease-in-out infinite alternate; }
+.eq-smoke.s1 { width: 54%; height: 17%; right: 3%; bottom: 55%; }
+.eq-smoke.s2 { width: 41%; height: 12%; right: -8%; bottom: 72%; animation-delay: -2s; }
+
+.extinguisher-device {
+  position: absolute;
+  z-index: 4;
+  right: 5%;
+  bottom: 2%;
+  width: 35%;
+  height: 86%;
+  max-width: 340px;
+}
+
+.eq-svg { width: 100%; height: 100%; overflow: visible; filter: drop-shadow(0 12px 13px rgba(37, 40, 43, 0.18)); }
+
+.handle-pressed { transform: translateY(5px); transform-origin: 200px 70px; }
+
+.pulled-pin {
+  transform: translate(10px, -18px) rotate(26deg);
+  transform-box: fill-box;
+  transform-origin: center;
+  animation: pin-pop 0.3s ease both;
+}
+
+.pin-hotspot {
+  position: absolute;
+  left: 60%;
+  top: 8%;
+  width: 26%;
+  height: 24%;
+  border: 0;
+  border-radius: 50%;
+  background: transparent;
+  cursor: grab;
+  z-index: 7;
+  touch-action: none;
+}
+
+.pin-hotspot:active { cursor: grabbing; }
+.pin-hotspot.is-pulled { pointer-events: none; }
+
+.pin-ring {
+  display: block;
+  width: 46%;
+  height: 46%;
+  margin: 0 auto;
+  border-radius: 50%;
+  border: 3px solid #e3bc4a;
+  background: rgba(255, 244, 184, 0.3);
+  box-shadow: 0 0 0 4px rgba(255, 235, 155, 0.25);
+  transition: transform 0.05s;
+}
+
+.pin-drag-hint {
+  position: absolute;
+  left: 50%;
+  top: 72%;
+  transform: translateX(-50%);
+  padding: 4px 8px;
+  border-radius: 99px;
+  background: rgba(28, 43, 55, 0.84);
+  color: #fff;
+  font-size: 0.58rem;
+  font-weight: 800;
+  white-space: nowrap;
+  animation: hint-pulse 0.9s ease-in-out infinite alternate;
+}
+
+.aim-layer {
+  position: absolute;
+  inset: 0;
+  z-index: 8;
+  touch-action: none;
+}
+
+.aim-hint-bubble {
+  position: absolute;
+  left: 50%;
+  top: 7%;
+  transform: translateX(-50%);
+  padding: 8px 15px;
+  border-radius: 99px;
+  background: rgba(18, 40, 58, 0.86);
+  color: #fff;
+  font-size: 0.7rem;
+  font-weight: 700;
+  white-space: nowrap;
+  box-shadow: 0 5px 18px rgba(20, 30, 40, 0.2);
+  backdrop-filter: blur(4px);
+}
+
+.aim-hint-bubble::after {
+  content: '';
+  position: absolute;
+  left: 50%;
+  bottom: -5px;
+  width: 10px;
+  height: 10px;
+  transform: translateX(-50%) rotate(45deg);
+  background: inherit;
+}
+
+.aim-target {
+  position: absolute;
+  display: grid;
+  place-items: center;
+  min-width: 49px;
+  min-height: 49px;
+  padding: 5px;
+  border-radius: 50%;
+  border: 2px dashed rgba(255, 255, 255, 0.85);
+  background: rgba(255, 251, 238, 0.25);
+  color: #fff;
+  font-size: 0.55rem;
+  font-weight: 800;
+  text-shadow: 0 1px 3px rgba(30, 30, 30, 0.4);
+  transition: 0.15s;
+}
+
+.aim-target:hover { background: rgba(255, 255, 255, 0.45); color: var(--navy); text-shadow: none; transform: scale(1.06); }
+.aim-target.target-smoke { right: 29%; top: 15%; }
+.aim-target.target-flame { left: 34%; top: 30%; }
+.aim-target.target-base { left: 18%; top: 58%; border-color: #ffe06e; box-shadow: 0 0 0 6px rgba(255, 222, 92, 0.18); }
+
+.drag-nozzle {
+  position: absolute;
+  left: 55%;
+  bottom: 16%;
+  width: 64px;
+  height: 110px;
+  transform: translate(-50%, 0) rotate(-22deg);
+  animation: nozzle-float 1.4s ease-in-out infinite alternate;
+  filter: drop-shadow(0 6px 7px rgba(20, 30, 40, 0.28));
+  pointer-events: none;
+}
+
+.nozzle-tip { position: absolute; left: 9px; top: 0; width: 25px; height: 47px; border-radius: 8px 8px 2px 2px; background: linear-gradient(90deg, #525c5f, #9aa5a5 48%, #5d686a); }
+.nozzle-hose { position: absolute; left: 27px; top: 39px; width: 18px; height: 70px; border-radius: 9px; background: #343a3d; }
+.nozzle-label { position: absolute; left: 36px; top: 60px; padding: 2px 6px; border-radius: 4px; background: #f8f3e5; color: #596468; font-size: 0.5rem; font-weight: 800; }
+
+.lever-hotspot-wrap {
+  position: absolute;
+  right: 4%;
+  bottom: 7%;
+  z-index: 8;
+}
+
+.lever-hotspot {
+  position: relative;
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 4px;
+  width: 112px;
+  padding: 8px;
+  border: 2px dashed #f1d36f;
+  border-radius: 12px;
+  background: rgba(255, 251, 233, 0.85);
+  color: #6f5b2d;
+  font-size: 0.58rem;
+  font-weight: 800;
+  touch-action: none;
+  user-select: none;
+}
+
+.lever-hotspot.is-holding { background: #fff6cf; border-style: solid; }
+
+.lever-handle {
+  width: 52px;
+  height: 13px;
+  border-radius: 6px;
+  background: linear-gradient(#5b6669, #30383a);
+  box-shadow: 0 3px 0 #252c2e;
+  transition: transform 0.08s;
+}
+
+.lever-hotspot.is-holding .lever-handle { transform: translateY(4px); }
+
+.lever-progress {
+  width: 100%;
+  height: 4px;
+  overflow: hidden;
+  border-radius: 99px;
+  background: #e3dcc8;
+}
+
+.lever-progress i { display: block; height: 100%; border-radius: inherit; background: #e3a931; transition: width 0.08s linear; }
+.lever-copy { white-space: nowrap; }
+
+.sweep-layer {
+  position: absolute;
+  inset: 0;
+  z-index: 8;
+  touch-action: none;
+  cursor: crosshair;
+}
+
+.sweep-instruction {
+  position: absolute;
+  left: 50%;
+  top: 9%;
+  transform: translateX(-50%);
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  gap: 4px;
+  padding: 11px 18px;
+  border-radius: 14px;
+  background: rgba(18, 42, 58, 0.82);
+  color: #fff;
+  text-align: center;
+  backdrop-filter: blur(4px);
+}
+
+.sweep-instruction b { font-size: 0.76rem; }
+.sweep-instruction > span { color: #bbd2dc; font-size: 0.58rem; }
+.sweep-track { display: flex; gap: 4px; margin-top: 3px; }
+.sweep-track i { width: 27px; height: 5px; border-radius: 99px; background: rgba(255, 255, 255, 0.25); }
+.sweep-track i.done { background: #5ae0b8; }
+.sweep-count { color: #ffdd7d; font-size: 0.56rem; font-weight: 800; }
+
+.spray-stream {
+  position: absolute;
+  left: 12%;
+  top: 43%;
+  width: 42%;
+  height: 26%;
+  border-radius: 50%;
+  background: radial-gradient(ellipse at left, rgba(255, 248, 217, 0.85), rgba(255, 243, 194, 0.18) 58%, transparent 75%);
+  filter: blur(5px);
+  animation: spray-pulse 0.6s ease-in-out infinite alternate;
+}
+
+.equip-success-panel {
+  position: absolute;
+  z-index: 10;
+  left: 50%;
+  top: 46%;
+  transform: translate(-50%, -50%);
+  width: min(360px, 82%);
+  padding: 22px;
+  border-radius: 18px;
+  background: rgba(255, 253, 244, 0.96);
+  box-shadow: var(--shadow-lg);
+  text-align: center;
+  animation: modal-pop 0.28s ease both;
+}
+
+.success-burst { display: block; font-size: 2.3rem; }
+.equip-success-panel h2 { margin-top: 5px; font-size: 1.3rem; }
+.equip-success-panel p { margin: 6px 0 13px; color: #748b95; font-size: 0.7rem; line-height: 1.55; }
+
+.eq-scene-label {
+  position: absolute;
+  left: 12px;
+  bottom: 10px;
+  z-index: 7;
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+  padding: 4px 8px;
+  border-radius: 6px;
+  background: rgba(20, 39, 55, 0.55);
+  color: #eff8f8;
+  font-size: 0.56rem;
+  font-weight: 600;
+  backdrop-filter: blur(3px);
+}
+
+.live-dot { width: 5px; height: 5px; border-radius: 50%; background: #5fe1ae; box-shadow: 0 0 0 3px rgba(95, 225, 174, 0.18); animation: soft-blink 1.6s infinite; }
+
+.equip-scene-note {
+  display: flex;
+  align-items: flex-start;
+  gap: 6px;
+  padding: 9px 12px;
+  border-radius: 10px;
+  background: #fff7e7;
+  border: 1px solid #f2e3c5;
+  color: #826b37;
+  font-size: 0.62rem;
+  line-height: 1.5;
+}
+
+.equip-scene-note svg { flex: 0 0 auto; margin-top: 1px; color: #d59b30; }
+
+.equip-side {
+  display: flex;
+  flex-direction: column;
+  min-width: 0;
+  padding: 15px;
+  border-radius: 18px;
+  background: rgba(255, 253, 248, 0.96);
+  border: 1px solid #eae1d3;
+  box-shadow: var(--shadow-sm);
+}
+
+.equip-step-header {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 8px;
+  padding-bottom: 9px;
+  margin-bottom: 10px;
+  border-bottom: 1px solid #f0e9dc;
+}
+
+.equip-step-count { color: var(--navy); font-size: 0.62rem; font-weight: 900; letter-spacing: 0.05em; }
+.equip-mode { padding: 2px 7px; border-radius: 5px; background: #e8f7f2; color: #16866d; font-size: 0.52rem; font-weight: 800; }
+
+.safety-check-box { display: flex; flex-direction: column; }
+
+.check-icon {
+  width: 45px;
+  height: 45px;
+  display: grid;
+  place-items: center;
+  border-radius: 13px;
+  background: #fff5dc;
+  font-size: 1.5rem;
+  margin-bottom: 8px;
+}
+
+.safety-check-box h3 { font-size: 1.08rem; }
+.safety-check-box > p { margin: 5px 0 11px; color: #6e8593; font-size: 0.68rem; line-height: 1.6; }
+
+.check-choices { display: flex; flex-direction: column; gap: 6px; }
+
+.check-choice {
+  width: 100%;
+  padding: 9px 11px;
+  border: 1.5px solid #e8e1d4;
+  border-radius: 10px;
+  background: #fffefa;
+  color: #4d6878;
+  font-size: 0.66rem;
+  line-height: 1.45;
+  text-align: left;
+  transition: 0.13s;
+}
+
+.check-choice:hover:not(:disabled) { border-color: #bfdcd2; background: #f9fffc; }
+.check-choice.is-correct { border-color: #4bc59d; background: #eefbf6; color: #1c725d; }
+.check-choice.is-wrong { border-color: #ed8f7b; background: #fff4f0; color: #a4523e; }
+
+.check-feedback { margin-top: 9px; padding: 9px 10px; border-radius: 9px; background: #fff5ef; border: 1px solid #f5d9ce; }
+.check-feedback b { display: block; color: #9e4e39; font-size: 0.67rem; }
+.check-feedback p { margin-top: 2px; color: #91746b; font-size: 0.61rem; line-height: 1.5; }
+.check-feedback button { margin-top: 6px; padding: 4px 8px; border: 0; border-radius: 6px; background: #fff; color: #a75b46; font-size: 0.58rem; font-weight: 800; }
+
+.current-instruction {
+  display: flex;
+  align-items: flex-start;
+  gap: 10px;
+  padding-bottom: 11px;
+}
+
+.instruction-icon {
+  width: 43px;
+  height: 43px;
+  flex: 0 0 auto;
+  display: grid;
+  place-items: center;
+  border-radius: 12px;
+  background: #fff2d5;
+  font-size: 1.25rem;
+}
+
+.instruction-icon.done { background: #e2f8ef; color: #16876b; font-size: 1.1rem; }
+.current-instruction .eyebrow { font-size: 0.52rem; }
+.current-instruction h2 { font-size: 1.06rem; margin: 1px 0 3px; }
+.current-instruction p { color: #728995; font-size: 0.64rem; line-height: 1.5; }
+
+.equip-photo-guide {
+  display: flex;
+  align-items: center;
+  gap: 11px;
+  padding: 10px 12px;
+  margin-bottom: 9px;
+  border-radius: 11px;
+  background: #f8f8f1;
+  border: 1px solid #eeece3;
+}
+
+.guide-visual { display: flex; align-items: center; gap: 4px; flex: 0 0 auto; }
+.guide-ext, .guide-fire { font-size: 1.2rem; }
+.guide-arrow { color: #a6a494; font-size: 0.8rem; }
+.equip-photo-guide > span { color: #6e8290; font-size: 0.62rem; line-height: 1.45; }
+.equip-photo-guide b { color: #ca5e3b; }
+
+.equip-continuous { display: flex; flex-direction: column; gap: 6px; margin-bottom: 9px; }
+
+.equip-fact {
+  padding: 8px 10px;
+  border-radius: 8px;
+  background: #f4fbf8;
+  border-left: 3px solid #50c09a;
+}
+
+.equip-fact.subtle { background: #fff8eb; border-color: #ecc56d; }
+.equip-fact b { display: block; color: #3c7467; font-size: 0.6rem; }
+.equip-fact.subtle b { color: #8d6c28; }
+.equip-fact p { margin-top: 1px; color: #7b9189; font-size: 0.57rem; line-height: 1.5; }
+
+.equip-side-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: auto; padding-top: 10px; border-top: 1px solid #f2ece2; }
+.equip-side-actions .game-btn { min-height: 30px; padding: 0 9px; font-size: 0.58rem; }
+
+/* ============================================================
+   AED GAME
