/* ============================================================
   EMERGENCY CALL GAME
   ============================================================ */
.call-game { min-height: 100svh; }

.call-step-dots { display: flex; gap: 5px; }
.call-step-dots span { width: 20px; height: 4px; border-radius: 99px; background: #e6e4d9; }
.call-step-dots span.done { background: #31b58d; }
.call-step-dots span.active { width: 29px; background: #e85f43; }

.call-timer { display: inline-flex; align-items: center; gap: 5px; color: #71868c; font-size: 0.6rem; font-weight: 700; white-space: nowrap; }
.call-live-dot { width: 6px; height: 6px; border-radius: 50%; background: #ea6b51; box-shadow: 0 0 0 3px rgba(234, 107, 81, 0.13); animation: soft-blink 1.1s infinite; }

.call-layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(310px, 380px);
  gap: 14px;
  align-items: stretch;
  justify-content: center;
}

.call-scene-column { display: flex; flex-direction: column; gap: 8px; min-width: 0; }

.call-scene {
  position: relative;
  flex: 1;
  min-height: 420px;
  overflow: hidden;
  border-radius: 20px;
  background: #b9e7f3;
  box-shadow: 0 13px 34px rgba(27, 54, 80, 0.16);
  isolation: isolate;
}

.call-art { position: absolute; inset: 0; overflow: hidden; }
.call-sky { position: absolute; inset: 0 0 38%; }
.fire-sky { background: linear-gradient(#72c6e8, #c7eaf5 70%, #f8dfb0); }
.park-sky { background: linear-gradient(#8dd5ed, #d8f1f3 72%, #c2dea9); }
.accident-sky { background: linear-gradient(#94cdd7, #e3eeee 70%, #d6d9ca); }

.call-cloud { position: absolute; height: 24px; border-radius: 99px; background: rgba(255, 255, 255, 0.64); }
.call-cloud::before, .call-cloud::after { content: ''; position: absolute; border-radius: 50%; background: inherit; }
.call-cloud::before { width: 47%; height: 170%; left: 12%; bottom: 17%; }
.call-cloud::after { width: 36%; height: 130%; right: 10%; bottom: 22%; }
.call-cloud.c1 { width: 100px; top: 16%; left: 10%; }
.call-cloud.c2 { width: 72px; height: 18px; top: 9%; right: 20%; }
.call-cloud.c3 { width: 59px; height: 15px; top: 25%; left: 35%; }

.call-city-building {
  position: absolute;
  left: 18%;
  bottom: 21%;
  width: 31%;
  height: 47%;
  border-radius: 5px 5px 0 0;
  background: #e6c59f;
  box-shadow: inset 0 0 0 4px #d4ad80;
  z-index: 2;
}
.cc-roof { position: absolute; left: -7%; right: -7%; top: -13%; height: 16%; background: #b6694f; clip-path: polygon(10% 100%, 0 0, 100% 0, 90% 100%); }
.cc-window { position: absolute; width: 19%; height: 19%; border: 2px solid #f0d8b6; background: #86c2d3; }
.cc-window.w1 { left: 16%; top: 20%; }
.cc-window.w2 { right: 15%; top: 20%; }
.cc-window.w3 { left: 42%; top: 42%; }
.cc-door { position: absolute; left: 40%; bottom: 0; width: 25%; height: 32%; border-radius: 3px 3px 0 0; background: #865d46; }
.cc-fire { position: absolute; right: -3%; top: 5%; font-size: 2rem; }
.cc-smoke { position: absolute; width: 30%; height: 12%; border-radius: 50%; background: rgba(90, 94, 99, 0.25); filter: blur(3px); }
.cc-smoke.s1 { right: 4%; top: -6%; }
.cc-smoke.s2 { right: -8%; top: -14%; width: 24%; }

.call-ground { position: absolute; left: 0; right: 0; bottom: 0; height: 38%; background: #a9cfa0; border-top: 3px solid #8db987; }
.call-truck { position: absolute; right: 10%; bottom: 18%; font-size: clamp(2.4rem, 5vw, 4.5rem); z-index: 3; transform: scaleX(-1); }
.call-people { position: absolute; left: 9%; bottom: 15%; display: flex; gap: 4px; font-size: clamp(1.4rem, 3.5vw, 2.8rem); z-index: 3; }

