.call-safety-strip svg { flex: 0 0 auto; margin-top: 1px; color: #d69b2e; }

.call-story-notes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.call-story-notes > div { display: flex; align-items: flex-start; gap: 5px; padding: 8px 9px; border-radius: 9px; background: rgba(255, 253, 246, 0.93); border: 1px solid #eee6d8; }
