.phone-call-view { flex: 1; display: flex; flex-direction: column; min-height: 0; background: #f2f7f5; }
.phone-call-header { display: flex; align-items: center; justify-content: space-between; gap: 6px; padding: 25px 17px 10px; background: #173d52; color: #fff; flex: 0 0 auto; }
.call-status { display: inline-flex; align-items: center; gap: 3px; color: #81e5cd; font-size: 0.49rem; font-weight: 800; }
.call-status i { width: 5px; height: 5px; border-radius: 50%; background: #61e0c2; animation: soft-blink 1.2s infinite; }
.phone-call-header b { flex: 1; text-align: center; font-size: 0.65rem; }
.call-timer-mini { color: #b0c9cf; font-size: 0.52rem; font-variant-numeric: tabular-nums; }

.call-transcript { flex: 1 1 30%; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; padding: 10px 12px; scroll-behavior: smooth; min-height: 76px; }
.call-bubble { max-width: 88%; padding: 7px 9px; border-radius: 9px 9px 9px 3px; background: #e6eeea; color: #3e5b5c; font-size: 0.6rem; line-height: 1.5; animation: bubble-in 0.22s ease both; }
.call-bubble.caller { align-self: flex-end; border-radius: 9px 9px 3px 9px; background: #d9f2e9; color: #316d5e; }
.bubble-speaker { display: block; margin-bottom: 1px; color: #8ba5a0; font-size: 0.45rem; font-weight: 800; }

.call-choice-area { flex: 0 0 auto; display: flex; flex-direction: column; min-height: 0; padding: 10px 11px 13px; border-radius: 16px 16px 0 0; background: #fffdf8; box-shadow: 0 -5px 15px rgba(31, 57, 65, 0.06); max-height: 62%; overflow-y: auto; }
.call-question { display: flex; gap: 7px; align-items: flex-start; margin-bottom: 8px; }
.q-mark { width: 23px; height: 23px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 7px; background: #e8f7f2; color: #1d9579; font-family: var(--display); font-size: 0.7rem; }
.call-question > div { display: flex; flex-direction: column; min-width: 0; }
.call-question small { color: #99aaa7; font-size: 0.45rem; font-weight: 800; letter-spacing: 0.04em; }
.call-question b { color: var(--navy); font-size: 0.68rem; line-height: 1.4; }

.call-choices { display: flex; flex-direction: column; gap: 5px; }
.call-choice { display: flex; align-items: center; gap: 6px; width: 100%; padding: 8px 9px; border: 1.3px solid #e8e5da; border-radius: 8px; background: #fffefa; text-align: left; color: #4d686e; font-size: 0.58rem; line-height: 1.45; transition: 0.13s; }
.call-choice:hover:not(:disabled) { border-color: #c3ded4; background: #f9fffc; }
.call-choice > span { flex: 1; }
.call-choice small { display: block; color: #9ba9a6; font-size: 0.49rem; }
.call-choice i { flex: 0 0 auto; color: #b2bdba; font-size: 0.7rem; font-style: normal; }
.call-choice.is-correct { border-color: #48bf9a; background: #edfbf6; color: #1e6f5d; }
.call-choice.is-correct i { color: #21a984; }
.call-choice.is-wrong { border-color: #eb8c77; background: #fff4f0; color: #9d503c; }
.call-choice.is-wrong i { color: #d95f43; }

.call-feedback { display: grid; grid-template-columns: 24px 1fr; gap: 5px 7px; margin-top: 7px; padding: 7px 8px; border-radius: 8px; background: #effbf6; border: 1px solid #d3f0e5; animation: feedback-in 0.18s ease both; }
.call-feedback.wrong { background: #fff5f1; border-color: #f4d6cb; }
.call-feedback > span { width: 23px; height: 23px; display: grid; place-items: center; border-radius: 50%; background: #41bd97; color: #fff; font-size: 0.58rem; font-weight: 900; }
.call-feedback.wrong > span { background: #e47b61; }
.call-feedback > div { min-width: 0; }
.call-feedback b { display: block; color: #237560; font-size: 0.6rem; }
.call-feedback.wrong b { color: #9e4f3a; }
.call-feedback p { color: #76918b; font-size: 0.53rem; line-height: 1.45; }
.call-feedback .game-btn { grid-column: 1 / -1; justify-self: end; min-height: 28px; padding: 0 10px; font-size: 0.55rem; }

.phone-complete { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 22px 19px; text-align: center; overflow-y: auto; background: radial-gradient(circle at 50% 20%, #e1fbf1, #f7fbf7 65%); }
.complete-check { width: 62px; height: 62px; display: grid; place-items: center; border-radius: 50%; background: linear-gradient(145deg, #50cba7, #25a17f); color: #fff; font-size: 1.65rem; box-shadow: 0 10px 24px rgba(35, 160, 126, 0.25); }
.phone-complete .eyebrow { margin-top: 12px; font-size: 0.51rem; }
.phone-complete h2 { margin: 3px 0 4px; font-size: 1.3rem; }
.phone-complete > p { color: #6c8788; font-size: 0.62rem; line-height: 1.55; }
.call-summary { display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; width: 100%; margin: 13px 0 10px; }
.call-summary > div { display: flex; flex-direction: column; gap: 1px; padding: 6px 4px; border-radius: 7px; background: #fff; border: 1px solid #e9efe7; }
.call-summary span { color: #9caba7; font-size: 0.46rem; }
.call-summary b { color: var(--navy); font-size: 0.62rem; }
.phone-tip { display: flex; align-items: flex-start; gap: 5px; width: 100%; padding: 8px 9px; margin-bottom: 11px; border-radius: 8px; background: #fff7e7; color: #7f6b3f; text-align: left; }
.phone-tip svg { flex: 0 0 auto; margin-top: 1px; color: #d69b2f; }
.phone-tip p { font-size: 0.52rem; line-height: 1.5; }
.phone-complete .phone-disclaimer { margin-top: 9px; }

/* call scene art details */
.park-ground { position: absolute; left: 0; right: 0; bottom: 0; height: 37%; background: #a9d195; }
.park-path { position: absolute; left: 0; right: 0; bottom: 0; height: 21%; background: #d7c49f; clip-path: polygon(0 25%, 100% 0, 100% 100%, 0 100%); }
.park-tree { position: absolute; z-index: 2; width: 17%; height: 43%; }
.park-tree span { position: absolute; left: 0; right: 0; top: 0; height: 65%; border-radius: 50% 50% 47% 53%; background: #68a962; box-shadow: inset -10px -10px 0 rgba(48, 117, 53, 0.14); }
.park-tree i { position: absolute; left: 43%; bottom: 0; width: 14%; height: 47%; background: #8c6646; }
.tree-one { left: 8%; bottom: 24%; }
.tree-two { right: 8%; bottom: 30%; transform: scale(0.76); }
.park-bench { position: absolute; left: 32%; bottom: 24%; width: 23%; height: 20%; z-index: 2; }
.park-bench::before { content: ''; position: absolute; left: 0; right: 0; top: 13%; height: 18%; border-radius: 4px; background: #b47d4e; box-shadow: 0 10px 0 #b47d4e; }
.park-bench::after { content: ''; position: absolute; left: 10%; right: 10%; bottom: 0; height: 26%; border-left: 4px solid #71563f; border-right: 4px solid #71563f; }
.fallen-person { position: absolute; left: 23%; bottom: 19%; width: 24%; height: 20%; z-index: 4; transform: rotate(-8deg); }
.fp-head { position: absolute; left: 0; top: 16%; width: 19%; height: 34%; border-radius: 50%; background: #eabf9a; }
.fp-body { position: absolute; left: 16%; top: 25%; width: 52%; height: 31%; border-radius: 9px; background: #638caa; }
.fp-legs { position: absolute; left: 65%; top: 31%; width: 34%; height: 23%; border-radius: 99px; background: #4c5f6c; }
.bystanders { position: absolute; right: 18%; bottom: 17%; display: flex; gap: 4px; font-size: 2rem; z-index: 3; }

.accident-ground { position: absolute; left: 0; right: 0; bottom: 0; height: 37%; background: #b6b9a9; }
.accident-road { position: absolute; left: 0; right: 0; bottom: 0; height: 37%; background: #757a78; transform: skewX(-12deg) scale(1.2); }
.accident-road span { position: absolute; width: 17%; height: 4%; background: #e4d8a8; top: 58%; }
.accident-road span:nth-child(1) { left: 5%; }
.accident-road span:nth-child(2) { left: 40%; }
.accident-road span:nth-child(3) { left: 76%; }
.accident-car { position: absolute; left: 40%; bottom: 25%; width: 36%; height: 25%; z-index: 3; border-radius: 10px 17px 5px 5px; background: #d95e48; box-shadow: inset 0 -7px 0 #a63c2e; }
.accident-car::before { content: ''; position: absolute; left: 20%; top: -26%; width: 51%; height: 40%; border-radius: 18px 22px 3px 3px; background: #de6f57; }
.car-window { position: absolute; left: 26%; top: -18%; width: 20%; height: 26%; border-radius: 4px; background: #bfe6ef; }
.car-light { position: absolute; right: -4%; top: 30%; width: 8%; height: 18%; border-radius: 3px; background: #ffdf78; }
.accident-car i, .accident-car b { position: absolute; bottom: -18%; width: 21%; height: 34%; border-radius: 50%; background: #2a3234; box-shadow: inset 0 0 0 7px #838b88; }
.accident-car i { left: 10%; }
.accident-car b { right: 8%; }
.accident-bike { position: absolute; left: 30%; bottom: 23%; font-size: 2.4rem; z-index: 4; transform: rotate(-13deg); }
.accident-cone { position: absolute; right: 16%; bottom: 19%; font-size: 2rem; z-index: 4; }
.accident-people { position: absolute; right: 7%; bottom: 16%; display: flex; gap: 3px; font-size: 2.2rem; z-index: 4; }
.accident-intersection { position: absolute; left: 0; right: 0; bottom: 17%; height: 3px; background: #ddd7c4; opacity: 0.6; }

/* ============================================================
   ERROR / STANDALONE
   ============================================================ */
.mission-error { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 70svh; text-align: center; gap: 6px; }
.mission-error > span { font-size: 3rem; }
.mission-error h1 { font-size: 1.55rem; }
.mission-error p { color: var(--muted); font-size: 0.79rem; margin-bottom: 8px; }

.standalone-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px clamp(16px, 4vw, 48px);
  background: rgba(255, 252, 245, 0.9);
  border-bottom: 1px solid var(--line);
  color: var(--navy);
  font-size: 0.75rem;
  font-weight: 700;
}

.standalone-bar button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border: 1px solid #e5dac8;
  border-radius: 7px;
  background: #fff;
  color: #687e8c;
  font-size: 0.66rem;
  font-weight: 700;
}

/* ============================================================
   MODE / ACCESSIBILITY ADJUSTMENTS
   ============================================================ */
.app-mode-kids {
  --radius: 22px;
}

.app-mode-kids .game-btn { font-size: 1rem; }
.app-mode-kids .choice-copy b,
.app-mode-kids .call-choice > span { font-size: 0.82rem; }
.app-mode-kids .choice-copy small,
.app-mode-kids .call-choice small { font-size: 0.68rem; }
.app-mode-kids .brief-story > p,
.app-mode-kids .physical p { font-size: 0.9rem; }

.app-mode-senior {
  --ink: #1a2a3a;
  --muted: #455d70;
  --line: #d6c7b1;
}

.app-mode-senior .app-header { background: #fffdf7; }
.app-mode-senior .game-btn { min-height: 48px; font-size: 1rem; border-width: 2px; }
.app-mode-senior .choice-card { min-height: 60px; border-width: 2px; }
.app-mode-senior .choice-copy b { font-size: 0.86rem; }
.app-mode-senior .choice-copy small { font-size: 0.7rem; color: #647a86; }
.app-mode-senior .hazard-object { border: 2px dashed rgba(255, 255, 255, 0.42); background: rgba(255, 255, 255, 0.14); }
.app-mode-senior .call-choice { min-height: 46px; }
.app-mode-senior .call-choice > span { font-size: 0.68rem; }
.app-mode-senior .muted-note,
.app-mode-senior .decision-footnote { font-size: 0.7rem; }
.app-mode-senior .source-line,
.app-mode-senior .feedback-card > p { font-size: 0.72rem; }
.app-mode-senior .game-status-bar { border-width: 2px; }

.app-mode-educator .choice-card.is-correct { outline: 3px solid #38b48d; }
.app-mode-educator .source-line { background: #f0f8ff; padding: 3px 6px; border-radius: 5px; }

.reduced-motion *,
.reduced-motion *::before,
.reduced-motion *::after {
  animation-duration: 0.001ms !important;
  animation-iteration-count: 1 !important;
  transition-duration: 0.001ms !important;
  scroll-behavior: auto !important;
}

/* ============================================================
   ANIMATIONS
   ============================================================ */
@keyframes soft-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes modal-pop {
  from { opacity: 0; transform: scale(0.96) translateY(8px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes mascot-bob {
  0%, 100% { transform: translateY(0) rotate(-1deg); }
  50% { transform: translateY(-5px) rotate(1deg); }
}

@keyframes ember-rise {
  0% { transform: translate(0, 0) scale(0.7); opacity: 0; }
  15% { opacity: 0.85; }
  75% { opacity: 0.58; }
  100% { transform: translate(16px, -190px) scale(0.25); opacity: 0; }
}

@keyframes smoke-drift {
  from { transform: translate(-2%, 2%) scale(0.98); opacity: 0.68; }
  to { transform: translate(4%, -3%) scale(1.07); opacity: 1; }
}

@keyframes flame-flicker {
  from { transform: scaleY(0.94) scaleX(1.02) rotate(-1deg); }
  to { transform: scaleY(1.06) scaleX(0.96) rotate(1deg); }
}

@keyframes glow-pulse {
  from { opacity: 0.7; transform: scale(0.94); }
  to { opacity: 1; transform: scale(1.06); }
}

@keyframes card-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  55% { transform: translateX(4px); }
  78% { transform: translateX(-2px); }
}

@keyframes feedback-in {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes hint-pulse {
  from { transform: scale(0.94); opacity: 0.55; }
  to { transform: scale(1.05); opacity: 1; }
}

@keyframes room-shake {
  0%, 100% { transform: translateX(0); }
  20% { transform: translateX(-5px); }
  45% { transform: translateX(5px); }
  70% { transform: translateX(-3px); }
}

@keyframes pin-pop {
  from { transform: translate(0, 0) rotate(0); opacity: 1; }
  to { transform: translate(10px, -18px) rotate(26deg); opacity: 0.8; }
}

@keyframes nozzle-float {
  from { transform: translate(-50%, 0) rotate(-22deg); }
  to { transform: translate(-50%, -8px) rotate(-17deg); }
}

@keyframes spray-pulse {
  from { opacity: 0.56; transform: scaleX(0.88); }
  to { opacity: 0.95; transform: scaleX(1.08); }
}

@keyframes free-wave {
  from { transform: scaleY(0.55); }
  to { transform: scaleY(1.12); }
}

@keyframes pin-snap {
  from { transform: scale(1.15); opacity: 0.4; }
  to { transform: scale(1); opacity: 1; }
}

@keyframes pad-snap {
  from { transform: scale(1.18); opacity: 0.35; }
  to { transform: scale(1); opacity: 1; }
}

@keyframes shock-flash {
  0%, 100% { filter: none; }
  25% { filter: brightness(1.35) drop-shadow(0 0 20px rgba(255, 220, 90, 0.85)); }
  55% { filter: brightness(0.9); }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes cpr-press {
  0%, 100% { transform: translateX(-50%) translateY(0); }
  50% { transform: translateX(-50%) translateY(5px); }
}

@keyframes compress-flash {
  0%, 100% { opacity: 0; }
  40% { opacity: 1; }
}

@keyframes beat-ring {
  from { transform: scale(0.66); opacity: 0.2; }
  to { transform: scale(1); opacity: 1; }
}

@keyframes heartbeat {
  from { transform: scale(0.9); }
  to { transform: scale(1.08); }
}

@keyframes rating-pop {
  0% { opacity: 0; transform: translate(-50%, 6px) scale(0.9); }
  20% { opacity: 1; transform: translate(-50%, 0) scale(1.05); }
  75% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -21px) scale(0.97); }
}

@keyframes call-ring {
  0% { transform: scale(0.45); opacity: 0.9; }
  100% { transform: scale(1.12); opacity: 0; }
}

@keyframes bubble-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1240px) {
  .app-header-inner { gap: 10px; }
  .app-nav button { padding: 0 10px; font-size: 0.8rem; }
  .header-level > div { width: 60px; }
  .header-level { padding-right: 4px; margin-right: 0; }
  .fire-game-layout { grid-template-columns: minmax(0, 1fr) minmax(360px, 0.94fr); }
  .call-layout { grid-template-columns: minmax(0, 1fr) minmax(290px, 350px); }
  .phone-shell { height: calc(100svh - 90px); }
}

@media (max-width: 1080px) {
  .app-nav { display: none; }
  .mobile-nav {
    display: flex;
    position: fixed;
    z-index: 70;
    left: 50%;
    bottom: max(10px, env(safe-area-inset-bottom));
    transform: translateX(-50%);
    width: min(620px, calc(100vw - 20px));
    padding: 5px;
    border-radius: 16px;
    background: rgba(255, 252, 245, 0.95);
    border: 1px solid #e8ddcc;
    box-shadow: 0 10px 30px rgba(20, 42, 65, 0.2);
    backdrop-filter: blur(14px);
  }
  .mobile-nav button {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    min-width: 0;
    padding: 5px 2px;
    border: 0;
    border-radius: 11px;
    background: none;
    color: #6e8494;
    font-size: 0.56rem;
    font-weight: 700;
  }
  .mobile-nav button.is-active { background: var(--primary-soft); color: var(--primary-dark); }
  .app-footer { padding-bottom: 84px; }
  .app-game .app-footer { display: none; }
  .profile-hero-card { grid-template-columns: auto minmax(0, 1fr); }
  .profile-quick-stats { grid-column: 1 / -1; flex-direction: row; min-width: 0; }
  .profile-quick-stats > div { flex: 1; }
  .mode-grid { grid-template-columns: repeat(2, 1fr); }
  .brief-hero-copy { max-width: 68%; }
}

@media (max-width: 940px) {
  .screen-pad { padding: 24px 20px 46px; }
  .profile-layout { grid-template-columns: 1fr; }
  .profile-hero-card,
  .profile-mission-history { grid-column: 1; }
  .settings-layout { grid-template-columns: 1fr; }
  .mode-settings { grid-column: 1; }
  .brief-grid { grid-template-columns: 1fr; }
  .brief-mascot { right: 18px; opacity: 0.82; }
  .brief-hero-copy { max-width: 64%; }
  .brief-hero { min-height: 180px; }
  .brief-emoji { right: 100px; }

  .fire-game-layout { grid-template-columns: 1fr; }
  .fire-scene { min-height: 0; max-height: none; width: 100%; }
  .scene-bottom-note { margin-bottom: 2px; }

  .hazard-layout { grid-template-columns: 1fr; }
  .hazard-side { order: 2; }
  .hazard-checklist { max-height: none; display: grid; grid-template-columns: 1fr 1fr; }
  .hazard-clear-note, .hazard-side-tip { grid-column: 1 / -1; }

  .extinguisher-layout,
  .aed-layout,
  .cpr-layout { grid-template-columns: 1fr; }
  .extinguisher-arena { min-height: 430px; }
  .extinguisher-side,
  .aed-side,
  .cpr-side { min-height: 0; }
  .aed-scene { min-height: 480px; }
  .cpr-scene { min-height: 400px; }
  .aed-side-bottom,
  .cpr-side-foot,
  .equip-side-actions { margin-top: 12px; }

  .call-layout { grid-template-columns: 1fr; justify-items: center; }
  .call-scene-column { width: 100%; }
  .call-scene { min-height: 360px; }
  .phone-shell { width: min(370px, 100%); height: 640px; justify-self: center; }
  .result-hero { flex-wrap: wrap; }
  .result-title-block { flex-basis: calc(100% - 190px); }
  .result-score-card { width: 100%; border-left: 0; border-top: 1px solid #eee5d7; padding: 12px 0 0; flex-direction: row; justify-content: center; gap: 18px; }
  .result-reward-row { grid-template-columns: 1fr; }
  .result-reward-card { padding: 11px 14px; }
  .result-breakdown { grid-template-columns: 1fr 1fr; }
  .result-retry-tips ul { grid-template-columns: 1fr; }
  .game-status-bar { flex-wrap: wrap; }
  .equip-progress-steps { order: 3; width: 100%; justify-content: flex-start; }
  .aed-top-progress { order: 3; width: 100%; justify-content: flex-start; }
}

@media (max-width: 760px) {
  :root { --header-h: 62px; }
  .app-header-inner { padding: 0 14px; gap: 8px; }
  .app-brand-mark { width: 38px; height: 38px; border-radius: 12px; }
  .app-brand-copy b { font-size: 0.9rem; }
  .app-brand-copy small { font-size: 0.55rem; }
  .header-level { display: none; }
  .header-icon-btn { width: 32px; height: 32px; }
  .header-profile { width: 34px; height: 34px; }
  .header-profile svg { width: 29px; }
  .app-header-right { gap: 3px; margin-left: auto; }

  .screen-pad { padding: 20px 14px 92px; }
  .screen-header { margin-bottom: 15px; }

  .profile-hero-card { padding: 20px 18px; gap: 15px; grid-template-columns: 1fr; justify-items: center; text-align: center; }
  .profile-avatar-wrap { width: 124px; height: 124px; }
  .profile-avatar-ring { width: 124px; height: 124px; }
  .profile-avatar-ring svg { width: 106px; }
  .profile-identity h2 { font-size: 1.7rem; }
  .profile-xp { margin-left: auto; margin-right: auto; }
  .profile-mini-badges { justify-content: center; }
  .profile-quick-stats { width: 100%; flex-wrap: wrap; }
  .profile-quick-stats > div { min-width: 92px; }
  .skill-chart-wrap { flex-direction: column; }
  .radar-chart { width: min(220px, 72%); }
  .skill-bars { width: 100%; }
  .profile-history-rows { grid-template-columns: 1fr; }
  .badge-grid { gap: 6px; }

  .settings-card { padding: 18px 16px; }
