  .header-icon-btn { width: 29px; height: 29px; }
  .header-profile { width: 31px; height: 31px; }
  .header-profile svg { width: 26px; }

  .screen-pad { padding: 16px 10px 90px; }
  .screen-header h1 { font-size: 1.65rem; }
  .profile-hero-card { padding: 18px 13px; }
  .skill-card, .badge-collection, .stats-card, .profile-mission-history, .coach-card { padding: 17px 14px; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  .skill-bar-row { grid-template-columns: 82px 1fr 22px; gap: 5px; }
  .skill-label { font-size: 0.6rem; }
  .badge-info p { display: none; }

  .settings-card { padding: 16px 13px; }
  .settings-card-head { gap: 8px; }
  .settings-head-icon { width: 34px; height: 34px; }
  .text-size-options { display: grid; grid-template-columns: 1fr 1fr; }

  .brief-hero { padding: 16px; min-height: 225px; }
  .brief-hero-copy h2 { font-size: 1.35rem; }
  .brief-meta { max-width: 100%; }
  .brief-mascot { opacity: 0.28; }
  .brief-source-date { white-space: normal; }

  .result-screen { padding: 15px 8px 24px; }
  .result-topline { margin-bottom: 7px; }
  .result-hero { padding: 14px; }
  .result-mascot { display: none; }
  .result-title-block { flex-basis: 100%; text-align: center; }
  .result-title-block .stars { justify-content: center; }
  .result-breakdown { grid-template-columns: 1fr; }
  .result-breakdown > div { padding: 7px 10px; }
  .unlock-row { padding: 8px 9px; }
  .unlock-row p { display: none; }
  .result-retry-tips { padding: 12px; }

  .game-btn.btn-md { min-height: 40px; padding: 0 13px; font-size: 0.72rem; }
  .game-btn.btn-lg { min-height: 46px; padding: 0 17px; font-size: 0.8rem; }
  .game-btn.btn-sm { min-height: 30px; font-size: 0.6rem; }

  .room-canvas { aspect-ratio: 900 / 680; }
  .hazard-object { width: 33px; height: 33px; }
  .object-emoji { font-size: 1.25rem; }
  .decoy-object .object-emoji { font-size: 1.05rem; }
  .hazard-actions .game-btn { font-size: 0.56rem; padding: 0 7px; }
  .hazard-score-chip { min-width: 58px; padding: 6px 8px; }
  .hazard-score-chip b { font-size: 1rem; }

  .extinguisher-arena { min-height: 340px; }
  .extinguisher-device { width: 48%; }
  .eq-fire { left: 5%; width: 34%; }
  .aim-target { min-width: 37px; min-height: 37px; font-size: 0.45rem; }
  .sweep-instruction { width: 78%; }
  .equip-scene-note { font-size: 0.56rem; }

  .aed-scene { min-height: 400px; }
  .patient-torso-wrap { width: min(210px, 84%); }
  .aed-device { width: 95px; height: 133px; }
  .aed-screen { height: 75px; }
  .pad-tray { max-width: 118px; }
  .aed-pad { padding: 2px; font-size: 0.4rem; }
  .pad-shape { width: 20px; height: 24px; }
  .clear-controls, .shock-controls { max-width: 235px; }

  .cpr-scene { min-height: 350px; }
  .cpr-patient { transform: translate(-50%, -50%) scale(0.66); top: 46%; }
  .cpr-ring-wrap { width: 125px; height: 125px; right: 0; top: 46%; }
  .cpr-tap-button { width: 77px; height: 77px; border-width: 4px; }
  .cpr-tap-button b { font-size: 0.9rem; }
  .cpr-tap-button small { font-size: 0.39rem; }
  .cpr-intro-facts { flex-wrap: wrap; }
  .cpr-intro-card h2 { font-size: 1.15rem; }
  .cpr-bottom-info { display: none; }

  .call-scene { min-height: 220px; }
  .call-scene-caption { left: 8px; right: 8px; bottom: 8px; padding: 6px 8px; }
  .call-scene-caption p { display: none; }
  .call-scene-overlay { left: 8px; right: 8px; top: 8px; }
  .virtual-call-badge { font-size: 0.48rem; }
  .call-safety-strip { padding: 7px 9px; font-size: 0.56rem; }
  .phone-shell { height: 540px; width: 100%; padding: 5px; border-radius: 27px; }
  .phone-screen { border-radius: 22px; }
  .phone-notch { width: 72px; height: 14px; }
  .phone-call-header { padding: 19px 12px 8px; }
  .call-choice-area { padding: 8px 8px 10px; max-height: 67%; }
  .call-choice { padding: 7px; font-size: 0.55rem; }
  .call-question b { font-size: 0.63rem; }
  .call-summary { grid-template-columns: 1fr; }
  .call-summary > div { flex-direction: row; justify-content: space-between; }
  .phone-complete { justify-content: flex-start; padding: 18px 13px; }
}

@media (max-height: 700px) and (min-width: 941px) {
  .game-status-bar { min-height: 47px; margin-bottom: 8px; }
  .game-shell { padding-top: 8px; }
  .fire-scene { max-height: calc(100svh - 175px); }
  .room-canvas { max-height: calc(100svh - 250px); }
  .extinguisher-arena { min-height: 430px; }
  .aed-scene { min-height: 500px; }
  .cpr-scene { min-height: 390px; }
  .phone-shell { height: calc(100svh - 75px); min-height: 500px; }
}

/* ============================================================
   REDUCED MOTION PREFERENCE
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
  }
}

files.patch:
Index: src/index.css
===================================================================
--- src/index.css
+++ src/index.css
@@ -8827,6 +8827,885 @@
 .cpr-side-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: auto; padding-top: 10px; border-top: 1px solid #f1ece2; }
 .cpr-side-foot span { color: #9ba8a7; font-size: 0.5rem; line-height: 1.4; max-width: 76%; }
 .cpr-side-foot button { padding: 4px 6px; border: 0; background: none; color: #5b8d80; font-size: 0.54rem; font-weight: 700; text-decoration: underline; }

+/* ============================================================
+   EMERGENCY CALL GAME
+   ============================================================ */
+.call-game { min-height: 100svh; }

+.call-step-dots { display: flex; gap: 5px; }
+.call-step-dots span { width: 20px; height: 4px; border-radius: 99px; background: #e6e4d9; }
+.call-step-dots span.done { background: #31b58d; }
+.call-step-dots span.active { width: 29px; background: #e85f43; }

+.call-timer { display: inline-flex; align-items: center; gap: 5px; color: #71868c; font-size: 0.6rem; font-weight: 700; white-space: nowrap; }
+.call-live-dot { width: 6px; height: 6px; border-radius: 50%; background: #ea6b51; box-shadow: 0 0 0 3px rgba(234, 107, 81, 0.13); animation: soft-blink 1.1s infinite; }
+
+.call-layout {
+  flex: 1;
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(310px, 380px);
+  gap: 14px;
+  align-items: stretch;
+  justify-content: center;
+}
+
+.call-scene-column { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
+
+.call-scene {
+  position: relative;
+  flex: 1;
+  min-height: 420px;
+  overflow: hidden;
+  border-radius: 20px;
+  background: #b9e7f3;
+  box-shadow: 0 13px 34px rgba(27, 54, 80, 0.16);
+  isolation: isolate;
+}
+
+.call-art { position: absolute; inset: 0; overflow: hidden; }
+.call-sky { position: absolute; inset: 0 0 38%; }
+.fire-sky { background: linear-gradient(#72c6e8, #c7eaf5 70%, #f8dfb0); }
+.park-sky { background: linear-gradient(#8dd5ed, #d8f1f3 72%, #c2dea9); }
+.accident-sky { background: linear-gradient(#94cdd7, #e3eeee 70%, #d6d9ca); }
+
+.call-cloud { position: absolute; height: 24px; border-radius: 99px; background: rgba(255, 255, 255, 0.64); }
+.call-cloud::before, .call-cloud::after { content: ''; position: absolute; border-radius: 50%; background: inherit; }
+.call-cloud::before { width: 47%; height: 170%; left: 12%; bottom: 17%; }
+.call-cloud::after { width: 36%; height: 130%; right: 10%; bottom: 22%; }
+.call-cloud.c1 { width: 100px; top: 16%; left: 10%; }
+.call-cloud.c2 { width: 72px; height: 18px; top: 9%; right: 20%; }
+.call-cloud.c3 { width: 59px; height: 15px; top: 25%; left: 35%; }
+
+.call-city-building {
+  position: absolute;
+  left: 18%;
+  bottom: 21%;
+  width: 31%;
+  height: 47%;
+  border-radius: 5px 5px 0 0;
+  background: #e6c59f;
+  box-shadow: inset 0 0 0 4px #d4ad80;
+  z-index: 2;
+}
+.cc-roof { position: absolute; left: -7%; right: -7%; top: -13%; height: 16%; background: #b6694f; clip-path: polygon(10% 100%, 0 0, 100% 0, 90% 100%); }
+.cc-window { position: absolute; width: 19%; height: 19%; border: 2px solid #f0d8b6; background: #86c2d3; }
+.cc-window.w1 { left: 16%; top: 20%; }
+.cc-window.w2 { right: 15%; top: 20%; }
+.cc-window.w3 { left: 42%; top: 42%; }
+.cc-door { position: absolute; left: 40%; bottom: 0; width: 25%; height: 32%; border-radius: 3px 3px 0 0; background: #865d46; }
+.cc-fire { position: absolute; right: -3%; top: 5%; font-size: 2rem; }
+.cc-smoke { position: absolute; width: 30%; height: 12%; border-radius: 50%; background: rgba(90, 94, 99, 0.25); filter: blur(3px); }
+.cc-smoke.s1 { right: 4%; top: -6%; }
+.cc-smoke.s2 { right: -8%; top: -14%; width: 24%; }
+
+.call-ground { position: absolute; left: 0; right: 0; bottom: 0; height: 38%; background: #a9cfa0; border-top: 3px solid #8db987; }
+.call-truck { position: absolute; right: 10%; bottom: 18%; font-size: clamp(2.4rem, 5vw, 4.5rem); z-index: 3; transform: scaleX(-1); }
+.call-people { position: absolute; left: 9%; bottom: 15%; display: flex; gap: 4px; font-size: clamp(1.4rem, 3.5vw, 2.8rem); z-index: 3; }
+
+.call-scene-overlay { position: absolute; z-index: 6; left: 13px; right: 13px; top: 12px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
+.virtual-call-badge { padding: 4px 8px; border-radius: 5px; background: rgba(255, 255, 255, 0.9); color: #c4573c; font-size: 0.55rem; font-weight: 800; }
+
+.call-scene-caption { position: absolute; z-index: 6; left: 14px; right: 14px; bottom: 16px; padding: 9px 11px; border-radius: 10px; background: rgba(19, 39, 55, 0.64); color: #fff; backdrop-filter: blur(4px); }
+.call-scene-caption b { display: block; font-size: 0.72rem; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.call-scene-caption p { margin-top: 1px; color: #cfe4e8; font-size: 0.58rem; line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
+
+.call-safety-strip { display: flex; align-items: flex-start; gap: 6px; padding: 9px 11px; border-radius: 10px; background: #fff8e9; border: 1px solid #f1e1be; color: #7e6a37; font-size: 0.62rem; line-height: 1.5; }
+.call-safety-strip svg { flex: 0 0 auto; margin-top: 1px; color: #d69b2e; }
+
+.call-story-notes { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
+.call-story-notes > div { display: flex; align-items: flex-start; gap: 5px; padding: 8px 9px; border-radius: 9px; background: rgba(255, 253, 246, 0.93); border: 1px solid #eee6d8; }
+.call-story-notes span { flex: 0 0 auto; color: #b6c1c1; font-family: var(--display); font-size: 0.57rem; }
+.call-story-notes p { color: #7a8c96; font-size: 0.58rem; line-height: 1.45; }
+.call-story-notes b { color: #496b7c; }
+
+/* phone */
+.phone-shell {
+  position: relative;
+  width: min(100%, 372px);
+  height: calc(100svh - 96px);
+  max-height: 760px;
+  min-height: 560px;
+  align-self: center;
+  justify-self: center;
+  padding: 10px;
+  border-radius: 38px;
+  background: linear-gradient(145deg, #1a1d24, #343a42 56%, #16191f);
+  box-shadow: 0 20px 45px rgba(18, 38, 58, 0.3), inset 0 0 0 1px rgba(255, 255, 255, 0.18);
+}
+
+.phone-notch { position: absolute; left: 50%; top: 10px; transform: translateX(-50%); width: 88px; height: 18px; border-radius: 0 0 12px 12px; background: #101217; z-index: 15; }
+.phone-notch::after { content: ''; position: absolute; left: 50%; top: 5px; transform: translateX(-50%); width: 31px; height: 4px; border-radius: 99px; background: #242a31; }
+.phone-screen { position: relative; width: 100%; height: 100%; overflow: hidden; border-radius: 29px; background: #eff5f4; display: flex; flex-direction: column; isolation: isolate; }
+.phone-screen::before { content: ''; position: absolute; left: -20%; right: -20%; top: -20%; height: 55%; background: radial-gradient(ellipse at center, rgba(111, 215, 200, 0.25), transparent 64%); pointer-events: none; }
+
+.phone-homebar { position: absolute; left: 50%; bottom: 16px; transform: translateX(-50%); width: 105px; height: 4px; border-radius: 99px; background: rgba(255, 255, 255, 0.45); z-index: 14; }
+.phone-screen .phone-homebar { display: none; }
+
+.phone-intro { position: relative; z-index: 2; flex: 1; display: flex; flex-direction: column; padding: 26px 22px 22px; color: var(--navy); overflow-y: auto; }
+.phone-intro-top { display: flex; justify-content: space-between; color: #607c81; font-size: 0.51rem; font-weight: 700; }
+.phone-signal { letter-spacing: 0.11em; color: #5e8b83; font-size: 0.42rem; }
+.phone-intro-center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
+.phone-emergency-icon { width: 80px; height: 80px; display: grid; place-items: center; border-radius: 24px; background: linear-gradient(145deg, #ff7858, #e7442c); color: #fff; font-family: var(--display); font-size: 1.7rem; box-shadow: 0 12px 26px rgba(218, 68, 43, 0.26); }
