+/* ============================================================
+   ANIMATIONS
+   ============================================================ */
+@keyframes soft-blink {
+  0%, 100% { opacity: 1; }
+  50% { opacity: 0.55; }
+}
+
+@keyframes fade-in {
+  from { opacity: 0; }
+  to { opacity: 1; }
+}
+
+@keyframes modal-pop {
+  from { opacity: 0; transform: scale(0.96) translateY(8px); }
+  to { opacity: 1; transform: scale(1) translateY(0); }
+}
+
+@keyframes toast-in {
+  from { opacity: 0; transform: translateY(8px) scale(0.97); }
+  to { opacity: 1; transform: translateY(0) scale(1); }
+}
+
+@keyframes mascot-bob {
+  0%, 100% { transform: translateY(0) rotate(-1deg); }
+  50% { transform: translateY(-5px) rotate(1deg); }
+}
+
+@keyframes ember-rise {
+  0% { transform: translate(0, 0) scale(0.7); opacity: 0; }
+  15% { opacity: 0.85; }
+  75% { opacity: 0.58; }
+  100% { transform: translate(16px, -190px) scale(0.25); opacity: 0; }
+}
+
+@keyframes smoke-drift {
+  from { transform: translate(-2%, 2%) scale(0.98); opacity: 0.68; }
+  to { transform: translate(4%, -3%) scale(1.07); opacity: 1; }
+}
+
+@keyframes flame-flicker {
+  from { transform: scaleY(0.94) scaleX(1.02) rotate(-1deg); }
+  to { transform: scaleY(1.06) scaleX(0.96) rotate(1deg); }
+}
+
+@keyframes glow-pulse {
+  from { opacity: 0.7; transform: scale(0.94); }
+  to { opacity: 1; transform: scale(1.06); }
+}
+
+@keyframes card-shake {
+  0%, 100% { transform: translateX(0); }
+  25% { transform: translateX(-5px); }
+  55% { transform: translateX(4px); }
+  78% { transform: translateX(-2px); }
+}
+
+@keyframes feedback-in {
+  from { opacity: 0; transform: translateY(-4px); }
+  to { opacity: 1; transform: translateY(0); }
+}
+
+@keyframes hint-pulse {
+  from { transform: scale(0.94); opacity: 0.55; }
+  to { transform: scale(1.05); opacity: 1; }
+}
+
+@keyframes room-shake {
+  0%, 100% { transform: translateX(0); }
